// 显示结束，printf函数不会自动跳至下一行，需要\n(换行符)



/*2.3 注释*/
//   /*标记注释开始，*/标记注释结束例如  /* This is a comment */
//   /*该注释可以占多行。如果遇到/*,那么编辑器读入(并且忽略)随后的内容直到遇到*/为止。
//   c99提供了另一种类型的注释，以//(两个相邻的斜杠)开始:  // This is a comment   (该注释风格在行末自动终止)



/*2.4 变量和赋值*/
// 大多数程序在产生输出之间往往需要执行一系列的计算，因此需要在程序执行过程中有一种临时存储数据的方法。C语言中这类存储单元被称为变量(variable)



/*2026.10.15*/
/*2.4.1 类型*/
// 每一个变量都有一个类型(type)。类型用来说明变量所存储的数据的种类。C语言拥有广泛多样的类型。但是现在，我们将只限定在两种范围内:int类型和float类型。
// 类型会影响变量的存储方式以及允许对变量进行的操作，所以选择合适的类型是非常关键的。
// 数值型变量的类型决定了变量所能存储的最大值和最小值，同时也决定了是否允许在小数点后出现数字。

// int(integer的简写)型变量可以存储整数，如0、1、392、或-2553。但是，整数的取值范围(7.1节)有限制。最大通常是2147483647,某些计算机可能是32767.
// float(floating-point的简写)型变量可以存储比int型变量大很多的数值。可存储带小数位的数，如2.1。   
// float计算比int慢，更重要的是其所存储的数值往往只是实际数值的近似值。如存储0.1，可能变量值为0.09999999999999987，这是舍入造成的误差。



/*2.4.2 声明*/
// 使用变量前必须声明(为编辑器所做的描述)。  首先指定变量类型，然后说明变量的名字(程序员决定变量名字，命名规则2.7节)
//     int height;     <--声明height是一个int型变量，也意味着其可以存储一个整数值。
//     float profit;   <--声明profit是一个float变量

// 如有几个变量具有相同的类型，就可以把它们的声明合并:
//     int height, length, width, volume;   <--用逗号隔开，最后用分号收尾
//     float profit, loss;     <--每一条完整的声明都要以分号结尾

// 当main函数包含声明时，必须把声明放置在语句前
/*

int main(void)
{
    声明
    语句
}         
     
*/

// 在C99中，声明可以不在语句之前。例如main函数可以先有一个声明，后面更一条语句，然后再跟一个声明。



/*2.4.3 赋值*/
// 变量通过赋值(assignnment)的方式获得值。
//     height = 8;   <--把8赋给height，8称为常量(constant)
//     length = 12;
//     width = 10;

// 变量在赋值时需要声明
//      int height;  <--顺序不能反，必须先声明变量，再赋值。C程序从上至下读取编译
//      height = 8;  <--顺序不能反

// 赋值给float型的变量的常量通常带小数点。
//      profit = 2150.48;  当我们把一个包含小数点的常量赋值给float型变量时，最好在该常量后加一个字母f(代表float)--> profit = 2150.48f;

// 正常情况下将int型值赋给int型变量，float同理。混合类型赋值(把int型值赋给float型变量，反之)是可以的，但不一定安全
// 变量一旦被赋值，就可以用来辅助计算其他变量的值:
//      height = 8;
//      length = 12;
//      width = 10;
//      volume = height * length * width;   /* volume is now 960 */
// 在C语言中，符号*表示乘法运算。通常情况下，赋值运算的右侧可以是一个含有常量、变量、和运算符的公式(在C语言的术语中称为表达式)



/*2.4.4 显示变量的值*/
