/*2.4.5 初始化*/
// 当程序开始执行时，某些变量会被自动设置为零，而大多数变量则不会(18.5节)。没有默认值并且尚未在程序中被赋值的变量是未初始化的(uninitializedd)。
// 如果试图访问未初始化的变量(如printf显示变量的值，或在表达式中使用该变量)，可能得到如2568、-30891或者其他同样没有意义的数值。某些编译器会崩溃

