/*2.8 C程序的书写规范*/
// 把C程序看作一连串记号(token)，即许多再不改变意思的情况上无法再分割的字符组。标识符和关键字都是记号。像+和-这样的运算符、逗号和分号这样的标点符号以及字串面，都是记号:
//      printf("Height: %d\n", height);   <-- 由7个符号组成
// 1. printf;   2. (;    3. "Height: %d\n";   4. ,;   5. height;   6. );   7. ;;   <-- 记号1和5是标识符，记号3是字面串,记号2、4、6、7是标点符号
// 一般记号之间可以不用空格，除非两个记号合并会产生第三个记号

// 语句可以分开放在任意多行内:
//      printf("Dimendional weight (pounds): %d\n",
//          (volume + INCHES_PER_POUND - 1) / INCHES_PER_POUND);

// 记号之间的空格让我们更容易区分:      volume = height * length * width;
// 注意别在记号内添加空格或缩进



/*2026.10.17*/
/* 第三章  格式化输入/输出 */


/* 3.1 printf函数 */
// printf函数被设计为显示格式串(format string)的内容，可在指定位置插入可能的值。调用必须提供格式串，格式串后面的参数是需要显示时插入的值:
// printf(格式串, 表达式1, 表达式2, ...);    <-- 显示值可以是常量、变量或更加复杂的表达式。

// 格式串包含普通字符和转换说明(conversion specification),转换说明以字符%开头，是用来表示打印过程中的带填充的值的占位符。
// 跟随在字符%后边的信息指定了把数值从内部形式(二进制)转换成打印形式(字符)的方法，这就是“转换说明”这一术语的由来:例如转换说明%d指定printf函数把int型值从二进制形式转换成十进制数字组成的字符串
// 内存里确实全是二进制，int 这类类型是编译期契约，规定"占几字节 + 怎么编码解码"。编译后类型消失，运行期只剩位和指令。

// 注意: C语言编译器不会检测格式串中转换说明的数量是否和输出项的数量相匹配:
//      int i = 10, j = 20;
//      float x = 43.2892f, y = 5527.0f;
//      printf("%d %d\n", i);   <-- 正常显示变量i的值，接着显示另一个(无意义的)整数值。
//      printf("%d\n", i, j);   <-- 会显示变量i的值，但不显示变量j的值。

// 此外，C语言编译器也不检测转换说明是否合适要显示项的数据类型:
//      printf("%f %d\n", i, x);  <-- printf函数必须服从于格式串，所以它将如实显示出一个float型值和一个int型值。可惜两个值都是无意义的
// printf 和 scanf 都只认格式串、不认变量类型；区别是 printf 按格式串"解码读出"，scanf 按格式串"编码写入"。 格式串写错，printf 输出乱码，scanf 直接写坏内存。
// 输入流是"队列"，scanf 按格式串消费，没消费完的留在缓冲区，下次继续用。这确实像"提前接收"——但接收的是输入流，不是内存。



/* 3.11 转换说明 */
// 转换说明可以包含格式化信息。具体来说，可以用%.1f来显示小数点后带一位数字的float型值。
// 更一般地，转换说明可以用( %m.pX )格式或( %-m.pX )格式，这里面的m和p都是整型常量，而X是字母。m和p都是可选的。如果省略p，m和p之间的的小数点要去掉(%m.X合法，这时算p是0)
// 在转换说明 %10.2f 中,m是10，p是2，X是f。  在转换说明 %10f 中，m是10，p(连同小数点一起)省去了;而在转换说明 %.2f 中，p是2，m省去了

/* 最小栏宽 */
// 最小栏宽(minimum field width)m制定了要显示的最少字符数量。如果需显示的数值所需字符数少于m，那么值在字段内向右对齐。(在之前面防治额外空格)
// 例如转换说明 %4d 将以 ·123 的形式显示数 123(本章用符号 · 表示空格字符)
// 如果要显示的值所需的字符数多于m那么栏宽会自动扩展为所需的尺寸。因此，转换符说明 %4d 将以12345显示12345，不会丢失数字。
// 在m前放上一个负号会导致左对齐;转换符说明 %-4d 将以 123· 的形式显示 123

/* 精度 */
// 精度(precison)p的含义很难描述，因为它依赖于转化指定符(conversion specifier)X的选择。X表明在显示数值前需要对其进行哪种转换。
 
// d —— 表示十进制(基数为10)形式的整数,p指明了待显示数字的的最少个数(必要时在数前加上额外的零);如果省略p默认为1
// e —— 表示指数(科学计数法)形式的浮点数。p指明了小数点后应该出现的数字个数(默认6).如p为0，则不显示小数点。
// f —— 表示“定点十进制”形式的浮点数，没有指数。p的含义与说明符e中一样
// g —— 表示指数形式或定点十进制形式的浮点数，形式的选择根据数的大小决定。p意味着可以显示的有效数字(不是小数点后的数字)的最大数量。与转换指定符f不同，g的转换将不显示尾随的零。此外，如果要显示的数值没有小数点后的数字，g就不会显示小数点
// E < -4 或 E >= P 用 %e，否则用 %f；E 是科学计数法指数，P 是精度（默认6）。 选完再去尾零、去多余点。边界是"定点形式是否还合理"，不是比字符串长短。
// 编写程序无法预知数大小或者数值变化范围很大的情况下，说明符g对于数的显示特别有用，显示适中采用定点十进制，过大或过小转换成指数形式以便减少所需的字符数

// 除了%d, %e, %f, %g以外，还有许多其他的说明符[整形说明符(7.1节)， 浮点型说明符(7.2节)， 字符说明符(7.3节)， 字符串说明符(13.3节)]



/* 程序: 用printf函数格式化数(tprintf.c)*/



/* 3.1.2 转义序列*/
// 格式串中常用的代码\n被称为转义序列(escape sequence)。转义序列(7.3节)使字符串包含一些特殊字符而不会使编译器引发问题
// 这些字符包括非打印的(控制)字符和对编译器有特殊含义的字符(如")。后面会提供完整的转义序列表，现在先看一组示例。
// 警报(响铃)符: \a
// 回退符: \b
// 换行符: \n
// 水平制表符: \t

// 当这些转义序列出现在printf函数的格式串中时，它们表示在显示中执行的操作。在大多数机器上，输出\a会产生一声鸣响，
// 输出\b会使光标从当前位置会退一个位置，输出\n会使光标跳到下一行的起始位置，输出\t会把光标移动到下一个制表符的位置

// 字符串可以包含任意数量的转义序列:
//      printf("Them\tUnit\tPurchase\n\tPrice\tDate\n");
// 显示如下:
//      Item    Unit    Purchase
//              Price   Date

// 另一种转义序列是\",它表示字符"。因为字符"标记字符串的开始和结束，所以它不能出现在没有使用上述转义序列的字符串内:
//      printf("\"Hello!\"");
// 输出如下:
//      "Hello!"
// 附带提一下，不能在字符串中只放置单独一个字符\，编译器会认为它是一个转义序列的开始。为了单独显示一个字符\，需要放置两个字符\:
//      printf("\\");    <-- 打印一个字符\


/* 3.2 scanf函数*/
// 如同printf函数用特定的格式显示输出一样，scanf函数的格式也根据特定的格式读入输入。像printf函数的格式串一样
// scanf函数的格式串也可以包含普通字符和转换说明(不过没有精度.p)两部分，其两者转换说明的用法本质一样。

// 在多数情况，scanf函数的格式串只包含转换说明，如下例所示:
//      int i, j;
//      float x, y;
//      scanf("%d%d%f%f", &i, &j, &x, &y);  <-- 这种"紧密压缩"的格式串很普遍，而printf函数很少这样

// 指数（科学计数法 e）只是人类为了好写、好看而发明的一种“表示形式”（语法糖）；
// 而计算机内存里真正存的，只有浮点数格式（通常是 IEEE 754 标准的二进制），所以在scanf函数输入"-4.0e3"，会赋值-4000.0给地址变量

// 注意检查scanf函数转换说明的数量是否与输入的变量数量相匹配，并检查每个转换是否适合相对应的变量(编译器无法检测出)，符号&常常(但不总是)是需要的

/*****************************************   注意    *******************************************/
// 如果 scanf 函数调用中忘记在变量前面放置符号 &，将产生不可预知甚至可能是毁灭性的结果。程序崩溃是常见的结果。
// 最轻微的后果则是从输入读进来的值无法存储到变量中，变量将保留原有的值（如果没有给变量赋初始值，那么这个原有值可能是没有意义的）。
// 忽略符号 & 是极为常见的错误，一定要小心！一些编译器可以检查出这种错误，并产生一条类似“format argument is not a pointer”的警告消息。
// （术语指针将在第 11 章定义，符号 & 用于创建一个指向变量的指针。）如果抛出警告消息，检查一下是否遗漏了符号 &。



/* 3.2.1 scanf函数的工作方法*/
// scanf函数能做的事很多，其本质上是一种"模式匹配"函数，试图把输入的字符组与转换说明相匹配。
// 和printf函数一样，其是由格式串控制。调用时从左边处理字符串中的信息，并在必要时跳过空格。然后读取数据，并在遇到不可能属于此项的字符停止。
// 如果读取数据成功，那么scanf函数会继续处理格式串的剩余部分;如果某一项不能成功接入，那么scanf函数将不再查看格式串的剩余部分(或者余下的输入数据)，并立即返回

// 在寻找数的起始位置时，scanf函数会忽略空白字符(white-space character，包括空格符、水平和垂直制表符、换页符和换行符)。因此可以把数字放在同一行或分为几行来输入:

//      scanf("%d%d%f%f", &i, &j, &x, &y);
// 假设用户录入3行输入:
//        1
//      -20   .3
//         -4.0e3
//      (敲回车的隐藏¤,实则每一行都有)
// scanf会给它们看成一个连续的字符流:
//      ··1¤-20···.3¤···-4.0e3¤        <-- (这里使用符号·代表空格符，符号¤表示换行符)
// 因为scanf函数在寻找每个数的起始位置时会跳过空白字符，所以它可以成功读取这些数。在接下来的代码示意中，字符下方的s表示此项被跳过，而字符下面的r表示此项被读取为输入项的一部分:
//      ··1¤-20···.3¤···-4.0e3¤
//      ssrsrrrsssrrssssrrrrrrr
// scanf函数"忽略"了最后的换行符，实际上没有取用它。这个换行符将是下一次scanf函数调用到第一个字符。
/* 
================================================================================
                    C语言 scanf 输入流与换行符(\n) 避坑完全指南
================================================================================

【核心概念】
1. 终端敲的回车，本质是字符流中的一个普通字符：'\n'（换行符）。
2. scanf 在处理输入时，就像流水线上的工人，按格式串的要求挑选零件，多余的留在传送带上（输入缓冲区）。
3. 格式串里的 '\n' 和终端敲的 '\n'，在 scanf 眼里是完全不同的两个东西。

--------------------------------------------------------------------------------
场景一：终端敲的回车（针对 %d、%f）
--------------------------------------------------------------------------------
* 现象：你输入 "10" 然后按下回车。
* 输入流：字符串 "10\n" 进入缓冲区。
* scanf行为：%d 和 %f 是“自动吸尘器”，它们在找数字。读完 10 后，遇到 '\n'，
              会认为这是“空白字符”而自动跳过，继续往后找下一个数字。
* 结果：数字完美录入。
* 隐患：被跳过的 '\n' 并没有消失，它依然留在输入缓冲区里，准备坑下一次输入。

--------------------------------------------------------------------------------
场景二：终端敲的回车（针对 %c）
--------------------------------------------------------------------------------
* 现象：你输入 "A" 然后按下回车。接着代码里还有一句 scanf("%c", &ch2);
* 输入流：字符串 "A\n" 进入缓冲区。
* scanf行为：%c 是“极度死心眼”，它绝对不跳过任何空白字符！
              第一个 scanf 读走了 'A'。第二个 scanf 会瞬间读走留在缓冲区里的 '\n'。
* 结果：程序看起来“跳过”了你的第二次输入，直接往下运行了。
* 解法：在 %c 前面加个空格！写成 scanf(" %c", &ch); 
        这个空格是在命令 scanf：“先把前面所有的空白字符（包括换行）全给我吃掉，再读字符”。

--------------------------------------------------------------------------------
场景三：scanf 格式串里主动写了换行 \n（如 scanf("%d\n", &i)）
--------------------------------------------------------------------------------
* 现象：代码里写了 scanf("%d\n", &i);
* scanf行为：格式串里的 '\n' 不是数据，而是一个“死等指令”。
              意思是：读完数字后，一直往后吃空白字符，直到遇见一个“非空白字符”才肯收工。
* 结果：程序卡死。你输入 "10" 回车，程序不走；你必须再输入一个字符（比如 'X'）再回车，
        它吃了空格吃了回车，看到 'X' 发现不是空白，指令结束。但 'X' 还会留在缓冲区里坑下一个 scanf。
* 铁律：【永远不要在 scanf 的格式串末尾写 '\n' 或空格！】

--------------------------------------------------------------------------------
场景四：scanf 格式串里写了普通字符（如 scanf("%d,%d", &a, &b)）
--------------------------------------------------------------------------------
* 现象：代码里写了逗号。
* scanf行为：遇到非空白普通字符（逗号、横杠等），scanf 要求用户输入必须“严丝合缝”地匹配。
* 结果：你必须输入 "10,20" 才能成功。如果你输入 "10 20"，scanf 读完 10 后期待逗号，
        结果遇到了空格，它会立刻罢工（读取失败），导致 b 变量根本没有被赋值。

--------------------------------------------------------------------------------
场景五：读完了，但没读干净（多余残留）
--------------------------------------------------------------------------------
* 现象：书上的例子，输入流 "... -4.0e3\n"。
* scanf行为：当格式串要求的 4 个变量 (i, j, x, y) 都塞满了，scanf 任务完成，立刻收工。
* 结果：指针刚好停在这个最后的 '\n' 前面。这个换行符被彻底遗留在缓冲区，
        它将成为下一次 scanf 函数调用读取到的“第一个字符”。

--------------------------------------------------------------------------------
终极记忆口诀：
--------------------------------------------------------------------------------
1. %d %f 不吃草（自动跳过所有空格、换行等空白字符）。
2. %c 吃草不挑食（连空格、换行都当成普通字符吃进去）。
3. 格式串里别写 \n（写了程序必定卡死等输入）。
4. 草没吃完会发臭（多余的换行留在缓冲区，随时坑死下一次读取）。
5. 想清空残留？ 用 while ((c = getchar()) != '\n' && c != EOF); 把缓冲区吸干。
================================================================================
*/

// 当读取整数时，scanf函数首先寻找正号或负号，然后读取数字，直到读到一个非数字时才停止。当要求读入浮点数时，scanf函数会寻找一个正号或负号(可选)
// 随后是一串数字(可能含有小数点)，再往后是一个指数(可选)。指数由字母e(或者字母E)、可选的符号，以及一个或多个数字构成。scanf函数%e,%f,%g可以互换

// 注意一个 C 语言允许的变态语法：
// 你输入 1e 会怎样？
// scanf 读完 1，看到 e，以为指数来了，准备吃指数。结果发现后面是回车（没有数字）。这时候，scanf 会把 e 吐回缓冲区，只把 1 存进变量里。 
// （因为指数必须是完整的，没数字的 e 不合法，它不认）。

// 当scanf函数遇到一个不可能属于当前项的字符时，它会把此字符"放回原处"，以便在扫描下一个输入项或者下一次调用scanf函数时再次接入。思考(公认有问题)4个数排列:
//      1-20.3-4.0e3¤
// 我们使用与以前一样的scanf函数调用:
//      scanf("%d%d%f%f", &i, &j, &x, &y);
// 下面列出了 scanf 函数处理这组新输入的方法:

// ● 转换说明 %d。第一个非空的输入字符是 1；因为整数可以以 1 开始，所以 scanf 函数接着读取下一个字符，即 -。
// scanf 函数识别出字符 - 不能出现在整数内，因此把 1 存入变量 i 中，而把字符 - 放回原处。

// ● 转换说明 %d。随后，scanf 函数读取字符 -、2、0 和 .（句点）。
// 因为整数不能包含小数点，所以 scanf 函数把 -20 存入变量 j 中，而把字符 . 放回原处。

// ● 转换说明 %f。接下来 scanf 函数读取字符 .、3 和 -。
// 因为浮点数不能在数字后边有负号，所以 scanf 函数把 0.3 存入变量 x 中，而把字符 - 放回原处。

// ● 转换说明 %f。最后，scanf 函数读取字符 -、4、.、0、e、3 和 \n（换行符）。
// 因为浮点数不能包含换行符，所以 scanf 函数把 -4.0×10³ 存入变量 y 中，而把换行符放回原处。
// 因为换行符没有被读取，所以它将留给下一次scanf函数调用

// 在m.p中:
// · 省了 m（前面没数）：就是 0，不补空格。
// · 省了 p（连点都没写）：浮点默认留 6 位小数。
// · 写了点，但 p 没数（如 %10.f）：强行把它当 0，保留 0 位小数（直接输出整数）。



/*3.2.2 格式串中的普通字符*/
// 空白字符。当scanf遇到连续多个空白字符时，scanf函数从输入中重复读空白字符，直到遇到一个非空白字符(把该字符"放回原处")为止，放回去再去看转换说明执行操作
// 格式串中空白字符数量无关紧要，格式串中的一个空白字符可以与输入中的任意数量的空白字符相匹配。
// (格式串中包含空白字符并不意味着输入中必须包含空白字符。格式串中的一个空白字符可以与输入总任意数量的空白字符相匹配，包括零个)

// 无数字的 %c = 单字符搬运工（只拿 1 个）。
// 加了数字的 %3c = 多字符搬运工（拿指定个数）。
// 但它永远不挑食，也永远不跳过前面的空白。

// 其他字符。当在格式串遇到非空白字符，scanf函数将它与下一个输入字符进行比较。如果两个字符相匹配，那么scanf函数放弃输入字符，并继续处理格式串。
// 如不匹配，那么scanf函数会把不匹配的字符放回输入中，然后异常退出，而不进一步处理格式串或者从输入中读取字符。

// 例如，假设格式串是"%d/%d"。如果输入的是:
//      ·5/·96    <-- 在寻找整数时，scanf函数会跳过第一个空格，把%d与5相匹配，把/与/相匹配(实则是识别到了/之后结束第一个%d然后看格式串里面，之后有个/再回缓冲区匹配)，之后%d又去匹配·96，其中·被跳过
// 另一方面，如果输入的是:
//      ·5·/·96   <--在格式串/时，匹配的是·，二者不匹配，因此scanf函数把空格放回原处，把字符·/·96交给下一次scanf函数(后面的%d不管了)调取。为了允许第一个数后面有空格，应使用格式串"%d /%d"(第一个%d后面有空格)。



/*3.2.3 易混淆的printf函数和scanf函数*/
//      printf("%d %d\n", &i, &j);   <-- 常见错误:变量前放置&(这种错误很容易发现，printf函数将显示一对样子奇怪的数，而不是变量i和j的值)
// 在寻找数据项的时，scanf函数通常会跳过空白字符。因此除了转换说明，格式串通常不需要包含字符(如果包含了字符，且不与转换格式对应就相当于之前的/了，要与缓冲区对应，不然直接跳过该函数(崩溃))。
//      scanf("%d, %d", &i, &j);   <-- 首先寻找整数存入变量i中;然后试图把逗号与下一个输入字符相匹配。如果下一个不是逗号，该函数终止操作。不再读取j

// 1. 读数字（%d, %f）或单词（%s）：不需要在格式串里加空格。它们天生就会跳过前面的空格和回车。
// 2. 读单字符（%c）：无条件在 %c 前面加一个空格（如 " %c"），不管它是第几个转换说明。这是 C 语言里最保命的习惯。
// 3. 绝对不要在 scanf 格式串的结尾加空格或换行（如 "%d "），否则程序会死死卡住，等你输入一个非空白字符才肯退出。
// 4. 读带空格的字符串：放弃 scanf("%s")，因为它遇到空格就断。去用 fgets()。

// printf 的精度 .p 规则：
// 1. 浮点数（%f/%e/%g）：四舍五入（底层遵循向偶数舍入）。
// 2. 字符串（%s）：直接截断（取前 p 个字符，绝不进位）。
// 3. 整数（%d）：不涉及小数，.p 代表最少数字位数（补零）。
// 精度（.p）和四舍五入、截断，只属于 printf 及其变体（sprintf, fprintf）。scanf 家族根本没有精度概念，只有宽度（读取最大字符数）。



