/* ============================================================================
 * 【C语言作用域底层哲学：物理隔离与内存操作】
 * ============================================================================
 * 1. 变量创建：声明变量（如 int a;）不是改数据，而是在内存里【圈地建新坑】。
 * 2. 变量遮蔽：内层声明同名变量，会在新内存建新坑，与外层同名变量物理隔离。
 * 3. 修改数据：
 *    - 内层直接写 a = 20，修改的是内层新坑，不改变外层内存。
 *    - 若想改变外层内存，唯一途径是提前传递外层变量的【指针（地址）】。
 * 4. 设计哲学：C语言绝不帮你猜，所有跨作用域的内存修改，必须通过指针显式进行。
 *    （这也是C语言极易引发指针越界漏洞的根源）。
 * ============================================================================
 */

 /* ============================================================================
 * 【底层铁律：表达式内的“自动转换” vs 函数内的“强行解释”】
 * ============================================================================
 * 1. 表达式与基本算法（大括号内部）：
 *    - 编译器充当“老妈子”，发现类型不同会自动进行隐式转换（如 int 提升为 float）。
 * 
 * 2. 函数调用（跨过括号的那一刻）：
 *    - 编译器不负责转换！它只负责把数据（或地址）按物理内存压入栈/寄存器。
 *    - 到了函数内部，函数定义了什么类型，就按什么类型去“强行解释”这段内存。
 *    - 变参函数（printf/scanf）更是瞎子，完全听格式符的解释。
 * 
 * 3. [安防警告]：
 *    - 形参的类型就是函数的防御边界。如果传入的数据大小与形参不符（如 64位传给 32位），
 *      会导致高位截断，黑客经常利用这种“截断解释”绕过函数内部的校验。
 * ============================================================================
 */


