/* ============================================================================
 * 【printf 并不转换类型：格式错配产生的“垃圾值”全解析】
 * ============================================================================
 * 
 * 【前情提要 / 编译器特权】
 * 1. printf 中 %f 和 %lf 完全等价：
 *    - 原因：传参时编译器强制将 float 提升为 double（8字节），且 %f/%lf 解析方式相同。
 *    - [安全警告]：在 printf 中随意用，但在 scanf 中混用必死（会导致越界写）！
 * 
 * ============================================================================
 * 【格式错配引发的两种致命灾难】
 * ============================================================================
 * 
 * 灾难一：尺寸截断（大范围变小范围）
 *    - 案例：用 %d 打印 long long (8字节)。
 *    - 底层：%d 图纸只允许抓 4 字节，直接导致高 4 字节被物理丢弃，数值彻底变样。
 * 
 * 灾难二：物理与编码错位（尺寸不对等 + 编码不兼容）
 *    - 案例：用 %f 打印 int (4字节)。
 *    - 底层动作分两步错：
 *      1. 尺寸错位：%f 默认要抓 8 字节（double），而 int 只有 4 字节，多抓的 4 字节是内存垃圾。
 *      2. 编码错位：即便碰巧拿到了那 4 字节，%f 也会用 IEEE 754 浮点规则去解码整数的补码，产生极度离谱的浮点乱码。
 * 
 * ============================================================================
 * 【终极结论】
 * printf 就是个瞎子，格式符是唯一图纸。
 * 尺寸对不上，就发生越界读；编码对不上，就产生乱码！
 * ============================================================================
 */



/* ============================================================================
 * 【内存双雄：栈 (Stack) 与 堆 (Heap)】
 * ============================================================================
 * 1. 栈 (Stack)：
 *    - 管理者：编译器。
 *    - 存放内容：局部变量、函数参数、返回地址。
 *    - 分配方式：自动分配、自动释放（出大括号即销毁）。
 *    - 特性：速度极快，空间小，向下生长。
 *    - [漏洞温床]：缓冲区溢出（Stack Overflow），覆盖返回地址。
 * 
 * 2. 堆 (Heap)：
 *    - 管理者：程序员（通过 malloc/free）。
 *    - 存放内容：动态分配的内存块。
 *    - 分配方式：手动申请、手动释放。
 *    - 特性：速度较慢，空间大，向上生长。
 *    - [漏洞温床]：内存泄漏（忘记 free）、UAF（释放后使用）、双重释放。
 * 
 * [核心区别]：
 *    - 栈：系统帮你擦屁股，不用你管。
 *    - 堆：你不擦屁股，系统就炸给你看。
 * ============================================================================
 */



 /* ============================================================================
 * 【printf 的输出缓冲区机制】
 * ============================================================================
 * 1. 存在意义：提高效率。避免频繁调用操作系统内核（系统调用），攒够了一起发车。
 * 2. 三种模式：
 *    - 终端屏幕：行缓冲（遇到 \n 才刷新）。
 *    - 磁盘文件：全缓冲（缓冲区满了才刷新）。
 *    - 报错输出（stderr）：无缓冲（立刻刷新）。
 * 
 * 3. [大坑]：如果 printf 里没有 \n，终端不会立刻显示。程序崩溃前的内容可能会丢失。
 * 4. [杀手锏]：使用 fflush(stdout); 强制清空缓冲区，让内容立刻显示。
 * ============================================================================
 */



/*自增运算符与自减运算符*/
//      i = i + 1, j = j - 1;  <-- 可以用复合运算符缩短  i += 1, j -= i;
// 而C语言允许用++(自增)和--(自减)运算符将这些语句缩的更短。
// 分前缀(++i和--i)和后缀(i++和i--)，同时，有副作用，计算表达式++i("前缀自增")结果是i+1，而副作用的效果是自增i

/* ============================================================================
 * 【C语言自增自减（++ / --）底层完全指南】
 * ============================================================================
 * 
 * 一、 核心铁律：表达式的“值” 与 “副作用”
 * ----------------------------------------------------------------------------
 * 1. 表达式的值（Value）：这个算式最终交出的结果（用于参与外层运算或赋值）。
 * 2. 副作用（Side Effect）：在计算过程中，偷偷改变了内存中变量的实际数值。
 * 
 * 二、 前缀 (++i) vs 后缀 (i++)
 * ----------------------------------------------------------------------------
 * 【前缀 ++i】（如 ++i, --i）
 * - 动作：先发生副作用（内存里的 i 立刻 +1），再交出表达式的值。
 * - 结果：i 和表达式的值，都是更新后的“新值”。
 * - 结合性：右结合（与一元正负号相同）。
 * 
 * 【后缀 i++】（如 i++, i--）
 * - 动作：先交出表达式的值（当前旧值），随后发生副作用（内存里的 i 再 +1）。
 * - 结果：表达式的值是“旧值”，但 i 随后变成了“新值”。
 * - 结合性：左结合（优先级极高，甚至高于乘除号）。
 * 
 * 三、 经典求值推导（合法且无歧义）
 * ----------------------------------------------------------------------------
 * 场景：i = 1; j = 2; k = i++ + j++;
 * 执行步骤：
 * 1. 先取值：i++ 交出 1，j++ 交出 2。
 * 2. 算外层：k = 1 + 2 = 3。
 * 3. 副作用生效：i 变成 2，j 变成 3。
 * 结果：k=3, i=2, j=3。（此处绝对没有未定义行为，结果唯一确定）
 * 
 * 场景：i = 1; j = 2; k = ++i + j++;
 * 执行步骤：
 * 1. 前缀 i 先自增：i 变成 2，++i 交出 2。
 * 2. 后缀 j 先取值：j++ 交出 2。
 * 3. 算外层：k = 2 + 2 = 4。
 * 4. 后缀 j 副作用生效：j 变成 3。
 * 结果：k=4, i=2, j=3。
 * 
 * 四、 致命雷区：未定义行为（UB）
 * ----------------------------------------------------------------------------
 * C 语言标准只规定了“交值”和“自增”的顺序，并没有规定“自增”和“赋值/参数求值”的先后。
 * 因此，在【两个顺序点之间】（比如同一个表达式里），绝对不要对同一个变量多次修改！
 * 
 * ❌ 错误示范 1：i = i++;
 *    - 编译器可能先算右边的 i++ (交出1)，然后再赋值给 i (i=1)，最后副作用 (i=2)。
 *    - 也可能先副作用 (i=2)，再赋值 (i=2)，结果变成 2。
 *    - 结果不可控，不同编译器行为不同。
 * 
 * ❌ 错误示范 2：printf("%d %d", i++, i++);
 *    - 参数是从右往左求值还是从左往右？自增什么时候发生？
 *    - C 标准说：编译器自己看着办。你可能会看到 "1 2"、"2 1" 甚至直接崩溃。
 * 
 * 五、 [安防视角] 指针与自增的千层套路
 * ----------------------------------------------------------------------------
 * 1. *p++  等价于 *(p++) 
 *    - 动作：先取 p 指向的值，然后再让 p 指针向后移动一个单位。
 *    - 黑客场景：在遍历网络数据包时，常用于连续读取缓冲区数据。
 * 
 * 2. (*p)++ 
 *    - 动作：取出 p 指向的值，然后把那个内存里的值 +1。
 *    - 黑客场景：如果 p 指向的是系统的权限标志位，这个操作能悄悄篡改权限，而指针本身不动。
 * ============================================================================
 */

// ++i意味着“立即自增i”,i++意味着“现在先用i的原始值，稍后在自增i”。这个稍后C语言标准没给出精准时间，但可以放心在下一条语句执行使用
// 其中前缀与一元的正负优先级相同而且是右结合，后缀则优先级高一点，且是左结合(求值顺序和结合性是两码事)



/*4.4 表达式求值*/
// 优先级: 1   (后缀)自增、自减    ++    --   左结合
// 优先级: 2   (前缀)自增、自减    一元正号、负号   ++    --    +    -    右结合
// 优先级: 3   乘法类    *   /   %    左结合
// 优先级: 4   加法类    +    -    左结合
// 优先级: 5   赋值    =    *=    /=    +=    -=    右结合

// a = b += c++ - d + --e / -f
// 第一优先级:  a = b += (c++) - d + --e / -f        <--   c++
// 第二优先级:  a = b += (c++) - d + (--e) / (-f)   <--   --e  和  -f
// 第三优先级:  a = b += (c++) - d + ((--e) / (-f))   <--   /
// 第四优先级:  a = b += (((c++) - d) + ((--e) / (-f)))   <--  +  和  -
// 第五优先级:  (a = b += (((c++) - d) + ((--e) / (-f))))   <--   =

/*子表达式的求值顺序*/
// 表达式的值可能依赖于子类表达式的求值顺序，C语言没有定义子类表达式的求值顺序[除了含有逻辑与运算符及逻辑或运算符(5.1节)、条件运算符(5.2节)、以及逗号运算符(6.3节)的子表达式]
// 因此在表达式(a + b) * (c - d) 中无法确定子表达式(a + b)是否在子表达式(c - d)之前求值:
//      a = 5;
//      c = (b = a + 2) - (a = 1);   <--  不知道运算顺序，大多数编译器而言，c值是6或2，跟计算顺序有关 

// 在表达式中既在某处访问变量的值又在别处修改它的值是不可取的,就如同上面的那个例子
// 为了避免出现此类问题，好主意是不在子类表达式中使用赋值运算符，而是采用一串分离的赋值表达式

// 除了赋值运算符，仅有自增和自减运算符可以改变操作数。使用这些运算符时，要注意表达式不要依赖特定的计算顺序。在下面的例子中，j 有两个可能的值：

//      i = 2;
//      j = i * i++;

// 人们很自然地就会认定 j 赋值为 4。但是，该语句的执行效果是未定义的，j 也可能赋值为 6。
// 这种情况具体如下：(1) 取出第二个操作数（i 的原始值），然后 i 自增；(2) 取出第一个操作数（i 的新值）；(3) i 的原始值和新值相乘，结果为 6。
// “取出”变量意味着从内存中获取它的值。变量的后续变化不会影响已取出的值，因为已取出的值通常存储在 CPU 中，称为寄存器（18.2 节）的一个特殊位置。

// 上述的两个例子都会导致"未定义行为",这跟4.1节中讲的由实现定义的行为是不同的。应该极力避免，否则无法通过编译，通过也无法运行，运行也可能崩溃。

/* ============================================================================
 * 【C语言底层避坑指南：三大“异常”行为等级】
 * ============================================================================
 * 核心痛点：C 语言为了跨平台和极致性能，留了很多“后门”。了解这三个等级，
 *           是写出安全代码（和挖出底层漏洞）的必经之路。
 * ============================================================================
 */

/* ----------------------------------------------------------------------------
 * 第一级：由实现定义的行为（Implementation-defined behavior）
 * ----------------------------------------------------------------------------
 * 1. 通俗理解：国家（C 标准委员会）不管，把锅甩给地方（编译器厂商）。
 *    地方可以自己定规矩，但【必须写在公告牌（编译器官方文档）上】。
 * 
 * 2. 核心特征：
 *    - 结果可能因编译器而异。
 *    - 但【在同一个编译器下，结果永远是固定、确定的】。
 *    - 【绝对不会导致程序崩溃】。
 * 
 * 3. 典型例子：
 *    - int 到底是 2 字节还是 4 字节？（现代电脑通常是 4 字节）。
 *    - char 默认是有符号 (signed) 还是无符号 (unsigned)？
 *    - 有符号整数右移时，左边补 0 还是补 1？
 *    - 负数取模（如 -5 % 3），结果符号跟着谁？（通常跟被除数）。
 * 
 * 4. 防御手段：查阅你当前使用的编译器（如 GCC、MSVC）的官方文档。
 * ---------------------------------------------------------------------------- */

/* ----------------------------------------------------------------------------
 * 第二级：未定义行为（Undefined behavior, 简称 UB）
 * ----------------------------------------------------------------------------
 * 1. 通俗理解：国家不管，地方也不知道怎么管，直接【摆烂】。
 * 
 * 2. 核心特征：
 *    - 编译器可以直接忽略，或者生成极其离谱的机器码。
 *    - 【不仅结果不可预测，甚至可能导致程序直接闪退（段错误）】。
 *    - 黑客最爱的漏洞温床。
 * 
 * 3. 典型例子：
 *    - 数组越界访问（如 int arr[3]; arr[10] = 1;）。
 *    - 在同一个表达式里多次修改同一变量（如 i = i++; 或 j = i * i++;）。
 *    - 解引用野指针或空指针。
 * ---------------------------------------------------------------------------- */

/* ----------------------------------------------------------------------------
 * 第三级：未指定行为（Unspecified behavior）
 * ----------------------------------------------------------------------------
 * 1. 通俗理解：标准允许几种合法的结果，但编译器选哪一种，标准不管，也不要求记录。
 * 2. 典型例子：函数参数的求值顺序（printf("%d %d", func1(), func2())，谁先执行？）。
 * ---------------------------------------------------------------------------- */

/* ============================================================================
 * 【安全开发与逆向工程的启示】
 * ============================================================================
 * 1. 可移植性受损：千万不要写出依赖“由实现定义的行为”的代码。
 *    比如：试图用一个 int 存超过 32767 的数字，换到单片机上就溢出成负数了。
 * 
 * 2. 寻找跨平台漏洞（黑客视角）：在 Windows 上跑的恶意软件，如果遇到了
 *    “由实现定义的行为”上的差异，可能移植到 Linux 上就失效了。
 * 
 * 3. 终极铁律：在 C 语言里，永远不要去“猜”结果。要么查阅文档，要么用 sizeof 
 *    去测试大小，要么用标准库（如 stdint.h 里的 int32_t）强制固定字节数。
 * ============================================================================
 */


/*4.5 表达式语句*/
// C语言有一条不同寻常的规则，那就是任何表达式都可以用作语句。换句话来说，不管表达式是什么类型、计算什么结果，我们都可以通过在后面添加分号将其转换语句 
 
/* ============================================================================
 * 【C语言哲学：表达式即语句】
 * ============================================================================
 * 1. 定义：
 *    - 表达式 (Expression)：能算出一个值的代码（如 3+5, a=10, i++）。
 *    - 语句 (Statement)：C 语言的最小执行单位，以分号 ; 结尾。
 * 
 * 2. 核心规则：在 C 语言中，任何表达式在末尾加上分号，就能升级为一条合法的语句。
 *    - 例如：a + b; 是合法的（虽然毫无意义，算出的值直接丢弃）。
 *    - 例如：i++; 是合法的（利用的是自增的副作用）。
 * 
 * 3. [安防致命漏洞：多余的分号]
 *    - 在 if / while / for 语句的括号后，如果不小心多加了分号，
 *      会导致语句变成“空语句”，引发严重的逻辑绕过。
 *      如：if (x == 1); { 恶意代码 } -> 这里的代码无条件执行。
 *      分号意味着语句的结束，所以判断后面加分号，代表判断了个寂寞，什么都不做。
 * ============================================================================
 */

// 在  ++i;  这个语句中，i先自增，之后取出，但是++i不是更长的表达式的一部分，所以它的值会被丢弃，执行下一条语句(当然对i的改变是永久的)
// 因为会丢掉值，所以除非表达式有副作用，否则将表达式用作语句并没有什么意义
//      i = 1;   <--  i存储了1然后取出i的新值，但是未使用

// CPU 的底层慢动作：
// 代码：i = 1;

// 第一步：写入（存储）CPU 收到指令：“把数字 1 塞进变量 i 的内存地址里”。CPU 把 1 的二进制（00000001）写进内存。此时，内存里的 i 变成了 1。

// 第二步：读取（取出新值）在 C 语言里，i = 1 这个整体，是一个“赋值表达式”。C 语言的底层铁律是：任何表达式在算完之后，都必须产生一个“结果”（Value）。
// 所以，CPU 刚把 1 塞进内存，紧接着又会顺着这个地址，把刚刚塞进去的 1 重新读出来，放进 CPU 的寄存器（比如 EAX 寄存器）里。这个 1，就是这个赋值表达式的返回值。

// 第三步：未使用（丢进垃圾桶）现在，CPU 的寄存器里拿着一个 1。
// 但是！你代码在这个表达式后面加了一个分号 ;。分号的意思就是：“这个表达式算完了，结束了。”
// 既然结束了，寄存器里的这个 1，因为没有被赋值给别的变量（比如没写成 a = (i = 1);），也没有被打印，所以 CPU 就直接把它忽略了（扔掉了）。

//      i--;   <-- 取出i的值未使用，随后i自减
//      i * j - 1;   <-- 计算后丢弃，i，j都没改变，这个没意义

// 某些编译器会警告一些这种无意义行为



/*2026.10.22*/
/* ============================================================================
 * 【终极铁律：printf/scanf 的物理压栈与解析顺序】
 * ============================================================================
 * 1. 传参物理顺序（进栈/寄存器）：
 *    - 大多数编译器约定（如 cdecl 调用约定）为【从右向左】压栈。
 *    - 目的：保证最左侧的参数（如格式串地址）最后入栈，位于栈顶，方便函数直接读取。
 * 
 * 2. 格式符解析顺序：
 *    - 永远是【从左向右】依次匹配参数。
 * 
 * 3. 表达式计算顺序：
 * 1. 未指定行为（参数顺序）：
 *    - printf("%d %d", f1(), f2());
 *    - C 标准不规定 f1 和 f2 谁先执行。不同编译器结果可能完全不同。
 * 
 * 2. 未定义行为（同一变量多次修改）：
 *    - printf("%d", i++ + i++); 
 *    - 绝对禁止在函数参数列表里修改同一个变量。没有序列点的保护，
 *      编译器想怎么排布底层汇编就怎么排布，结果完全不可控。
 * ============================================================================
 */


/* ============================================================================
 * 【时空分离铁律：参数计算 vs 格式匹配】
 * ============================================================================
 * 1. 时间维度（表达式计算顺序）：
 *    - 发生在调用函数之前。
 *    - C 标准未指定（未定义行为）。先算 f1 还是先算 f2 全看编译器心情。
 * 
 * 2. 空间维度（格式符匹配顺序）：
 *    - 发生在函数内部。
 *    - 永远是【从左到右】依次去寄存器/栈坑位拿。
 *    - 它只认坑位里装的值，不认这个值是怎么算出来的。
 * 
 * 3. [安防漏洞]：
 *    - 黑客利用格式化字符串（%x, %n）攻击时，根本不是在执行计算，而是在做【空间越界读取】。
 *    - 因为 printf 只认“从左往右”的图纸匹配，黑客精准计算偏移量把恶意地址垫在栈上，
 *      printf 就会按图纸依次去抓，最终抓中黑客的假地址，实现任意写。
 * ============================================================================
 */


 /* ============================================================================
 * 【终极底层暴击：格式化字符串漏洞全景解析与内存布局】
 * ============================================================================
 * 
 * 一、 物理大前提：栈的“生长方向”与“幽灵残留”
 * ----------------------------------------------------------------------------
 * 1. 内存参考系：栈（Stack）在宏观上是向【低地址】生长的，但数据写入是从
 *    【低地址向高地址】填充的。
 * 
 * 2. 及时清理（逻辑废弃）：函数返回时，栈指针（RSP）复位（弹栈），系统立刻
 *    收回逻辑空间，防止栈无限生长导致程序崩溃。
 * 
 * 3. 幽灵残留（物理不清零）：操作系统的清理只是移动了指针，【物理内存绝不自动清零】。
 *    废弃栈帧里的密码、密钥或伪造地址会一直残留，直到被下一次调用覆盖。
 *    -> [漏洞温床]：这是信息泄露（%s 读取残留数据）的物理根源。
 * 
 * ============================================================================
 * 
 * 二、 核心机制：参数“进阀”与“8字节指针”定律
 * ----------------------------------------------------------------------------
 * 1. 字符串打包：黑客输入的 Payload（包含目标地址、%x、%n）是一个整体，
 *    存放在内存（栈/堆）中，是连续的字节流。
 * 2. 指针即参数：当这串数据首地址传给 printf 时，printf 会把字符串里的
 *    数据当作“参数”去抓取。在 64 位系统中，【一个地址（指针）固定占 8 字节】，
 *    printf 每次按 8 字节的步长去读取参数。
 * 
 * ============================================================================
 * 
 * 三、 攻击实操三步曲：图纸与数据的“空间错位”
 * ----------------------------------------------------------------------------
 * 假设程序存在漏洞：printf(user_input);
 * 
 * 步骤 1：探路找偏移（暴露内存）
 *    - 输入：AAAA%x-%x-%x-%x-%x
 *    - 如果屏幕打印出 ...-41414141-...，说明 printf 抓取的第 N 个参数，
 *      刚好是输入字符串的开头（AAAA）。
 * 
 * 步骤 2：排兵布阵（伪造参数）
 *    - 把开头的 AAAA 替换为【真实的目标攻击地址】（如 0x0804a020，转成二进制字节）。
 *    - 前面用 N-1 个 %x 消耗掉不需要的栈位置。
 *    - 图纸变为：[目标地址(8字节)] + %x%x%x + %n
 * 
 * 步骤 3：终极绝杀（越位写入）
 *    - printf 顺图纸解析。前面的 %x 把无关参数消耗殆尽。
 *    - 当执行到 %n 时，它按 8 字节步长去抓参数，刚好抓到了黑客埋伏在
 *      字符串最开头的【目标地址】。
 *    - %n 将当前已打印的字符数量，强行写入该目标地址（实现任意地址写）。
 * 
 * ============================================================================
 * 
 * 四、 【重要纠错】之前探讨中的认知误区修正
 * ----------------------------------------------------------------------------
 * 1. 字符串没有“打包”进栈：
 *    进栈（寄存器/栈参数区）的不是字符串内容，而是【首地址】。内容一直躺在内存里。
 * 
 * 2. %n 和输出缓冲区无关：
 *    %n 的破坏力依赖于“图纸解析”和“地址寻址”，跟 printf 的输出缓冲区（stdout buffer）
 *    没有任何关系，关闭缓冲区也不能防御 %n。
 * 
 * 3. 连续 %n 的连环写入：
 *    如果写两个 %n，黑客会在字符串开头连续放两个 8 字节地址。printf 会按顺序
 *    逐个抓取，完成高低地址的完美拆分写入。
 * 
 * ============================================================================
 * 
 * 五、 安防警告与防御铁律
 * ----------------------------------------------------------------------------
 * 1. 这是“任意地址写（Arbitrary Write）”的终极原理，可篡改权限位或覆盖返回地址。
 * 2. 只要用户的输入被当成“图纸”去解析，底层灾难就不可避免。
 * 3. 【防御铁律】永远不要使用 printf(用户输入)！
 *    必须写成：printf("%s", 用户输入);
 * ============================================================================
 */


 /* ============================================================================
 * 【底层终极笔记：从字符表象到 CPU 执行的全链路真相】
 * ============================================================================
 * 核心思想：人类看到的是字符，网线传输的是电信号（二进制），CPU 执行的是指令。
 * 中间的每一次“转换/解码”，都是黑客发动攻击的温床。
 * 
 * ============================================================================
 * 一、 物理真相：引号与二进制的“千层套路”（表象 vs 本质）
 * ============================================================================
 * 1. 物理层（无差别）：
 *    - 字符 '  、URL 编码 %27 、十六进制 0x27，在经过网卡发送时，
 *      跑的全是同一串物理电信号（00100111）。哪怕上帝来了也看不出区别。
 * 
 * 2. 软件层（千变万化）：
 *    - 为什么黑客要搞出这么多花样？为了“欺骗中间的解码器（WAF、服务器）”。
 *    - 发纯字符 '  ：容易暴露特征，被 WAF 一眼拦截。
 *    - 发 %27      ：URL 编码。骗过不解码的初级 WAF，后端自动解码成 '。
 *    - 发 \x27     ：纯二进制。直接通过 Socket 穿透协议层，绕过只看文本特征的防御。
 * 
 * 3. [安防暴击：宽字节注入]
 *    - 黑客输入 %bf%27。后端转义为 %bf\ (0xbf 0x5c 0x27)。
 *    - 底层解码器（GBK）发现 0xbf > 128，触发多字节判定，吃掉 0x5c（反斜杠）。
 *    - 单引号 (0x27) 暴露，SQL 注入成功。
 * 
 * ============================================================================
 * 二、 编译与执行流水线：从源码到 CPU 寄存器
 * ============================================================================
 * 1. 编译期（编码写入，固化字节）：
 *    - 源码解码：编译器用 UTF-8 读源码，把 "你" 还原成 Unicode 编号。
 *    - 编译转码：根据目标系统执行字符集（如 GBK），把编号变成物理字节。
 *    - 固化存储：把转好的字节，连同 \0，写死进可执行文件的 .rodata 段。
 * 
 * 2. 运行期（取指 Fetch，带入寄存器）：
 *    - CPU 顺着地址总线，把内存（RAM）里的指令和数据，
 *      按 64 位（8字节）的口径，一把抓进内部寄存器（如 RAX、RDI）。
 * 
 * 3. CPU 解码（Decode，定生死）：
 *    - 译码器识别这堆 0 和 1：这是指令？还是数据？还是地址？
 *    - 如果数据（如输入字符）被错误地当成了指令去解码，就会触发
 *      【代码执行漏洞/缓冲区溢出（Shellcode）】。
 *    - 如果写入的编码规则（UTF-8）和解码规则（GBK）不一致，就会乱码或引发注入。
 * 
 * ============================================================================
 * 三、 终极融合口诀（极客防身术）
 * ============================================================================
 * 1. 万物皆比特：字符、引号、指令，在物理层全是一串电信号。
 * 2. 变形皆为骗：所有编码变形（%27, \x27）都是为了骗过中间层的解析器。
 * 3. 解码即执行：数据如果被错误解码（当成指令），系统就会沦为肉鸡。
 * 4. 边界即漏洞：跨语言、跨系统、跨协议时的“编码/解码不一致”，就是黑客的提款机。
 * ============================================================================
 */


 /* ============================================================================
 * 【物理纠偏：内存与栈的层级关系】
 * ============================================================================
 * 1. 内存（RAM）：物理硬件疆域。包含代码段、数据段、堆区、栈区。
 * 2. 栈（Stack）：内存中划出的一块特殊区域，遵循后进先出（LIFO）原则，
 *    用于存放局部变量、函数返回地址，自动分配和自动回收。
 * 3. 真正的“跨频道”对比：
 *    - CPU 寄存器（最快，极小） vs 内存 RAM（较慢，较大）。
 *    - 黑客做任意地址写（%n）或栈溢出，本质上都是在【内存】这片物理疆域里搞破坏。
 * ============================================================================
 */



