// C语言还有其他两类语句，一类是复合语句(把几条语句组合成一条语句)，一类是空语句(不执行任何操作)。


/*5.1 逻辑表达式*/
// 包括if语句在内的某些C语句必须测试表达式的值是“真”还是“假”。许多语言都有类似 i < j 的表达式，其具有特殊的“布尔类型”或“逻辑类型”。
// 这样的类型只有两个值，即真和假。C语言中， i < j 会产生整数:0(假)或1(真)。



/*5.1.1 关系运算符*/
// C语言的关系运算符(relational operator，见表5-1)与数学上<、>、<=、>=对应，只不过产生的结果是0(假)1(真)
// 关系运算符可以用作比较整数和浮点数。关系运算符左结合。

/* ============================================================================
 * 【破除教材谎言：优先级 ≠ 运算（求值）顺序】
 * ============================================================================
 * 1. 教材的谎言：优先级决定谁先算，同级看结合性。
 * 2. 底层的真相：
 *    - 优先级 & 结合性：发生在【编译期】，只决定语法树（图纸）怎么画。
 *      比如 a + b * c，只决定算的是 (a + (b*c))，而不是 ((a+b)*c)。
 *    - 求值顺序：发生在【运行期】，决定 CPU 先执行哪条指令。
 *      C 标准基本不规定求值顺序，全看编译器优化（先算乘法还是先读a，看心情）。
 * 
 * 3. 只有极少数强制顺序：
 *    - &&, ||, ?:, 逗号表达式，以及分号（序列点）。
 * 
 * 4. [安防致命漏洞：未定义行为 (UB)]
 *    - 因为优先级不决定执行顺序，如果你写 a[i] = i++。
 *    - 虽然 = 优先级低，++ 优先级高，但你先算 a[i] 的地址，还是先算 i++，
 *      完全未知。不同编译器结果不同，是黑客进行逻辑绕过的完美温床。
 * ============================================================================
 */

 /* ============================================================================
 * 【认知纠偏：编译器画图，CPU搬砖】
 * ============================================================================
 * 1. 优先级与结合性（编译器）：发生在编译期。编译器根据规则，决定语法树怎么画，
 *    并生成最终的机器指令。是编译器在“分得清”。
 * 
 * 2. CPU（运行期）：完全不认识源码和优先级。它只认汇编指令（MOV, ADD, MUL）。
 *    指令先后顺序是编译器安排好的。
 * 
 * 3. 乱序执行（Out-of-Order）：现代 CPU 为了速度，在不违反数据依赖的前提下，
 *    会偷偷打乱指令执行顺序。所以真正底层的“执行顺序”，是高度并发的乱序。只要没有数据依赖和内存屏障，CPU 会再次打乱指令顺序并行计算。
 * 
 * 4. [安全警告]：不要利用优先级去控制副作用（如 i++ + i++）。
 *    编译器画出来的图是固定的，但 CPU 的乱序执行和优化器，会导致未定义行为（UB）。
 * ============================================================================
 */


 /* ============================================================================
 * 【C语言标准的底层哲学：管杀不管埋】
 * ============================================================================
 * 核心总结：两者都是 C 语言标准不管，交给编译器处理。
 * 
 * 1. 未指定行为（Unspecified）：
 *    - 性质：本身是可以的（合法代码）。
 *    - 表现：多个合法的执行路径，编译器随意挑一个，程序绝对安全。
 * 
 * 2. 未定义行为（Undefined Behavior, UB）：
 *    - 性质：不合理（非法/违背逻辑的代码）。
 *    - 表现：编译器直接放弃治疗，为了优化任意删改代码，极易引发崩溃或安全漏洞。
 * 
 * [安防铁律]：
 * 我们可以容忍未指定行为（求值顺序不同），但绝不能容忍未定义行为（存在逻辑炸弹）。
 * ============================================================================
 */

// 表达式 i < j < k 在C语言中是合法的，但可能不是你所期待的含义。因为<运算符是左结合，所以这个表达式等价于:
//      (i < j) < k
// 先检测i是否小于j，然后用比较后产生的结果(1或0)来和k进行比较。这个表达式并不是测试j是否位于k之间。(后面可见，正确是i<j && j<k)



/*5.1.2 判等运算符*/
// ==(等于)    !=(不等于)     <-- 也是左结合(从左往右)
// i < j == j < k    等价于    (i < j) == (j < k)    <-- i < j和 j < k同时成立，该表达式为真



/*5.1.3 逻辑运算符*/
// "!" 是一元运算符，"&&"和"||"是二元运算符。
// "!" 逻辑非      "&&" 逻辑与     "||"逻辑或
// 逻辑运算符所产生的结果是0或1.操作数的值经常是0或1，但这不是必须的。逻辑运算符将任何非零值操作数作为真值来处理，同时将任何零值操作数作为假值来处理。

// 如果表达式的值为0，那么!表达式的结果为1;
// 如果表达式1和表达式2的值都是非零值，那么表达式1 && 表达式2的结果为1;
// 如果表达式1或表达式2的值中任意一个是(或者两者都是)非零值，那么表达式1 || 表达式2的结果为1.
// 在所有其他结果，这些运算符产生的结果都为0.

// 运算符&&和||都对操作数进行"短路"计算。也就是说，这些运算符首先计算出左操作数的值，然后计算右操作数。
// 如果表达式的值可以仅由左操作数的值推导出来，那么将不计算右操作数的值:
//      (i != 0) && (j / i > 0)   <-- 先推断(i != 0)是否成立，如不成立直接跳过后面的判断，给出0(假)，这就是短路:
//      i > 0 && ++j > 0     <-- 如果i > 0不成立则短路，那么j的自增也不会进行，可以换成 ++j > 0 && i > 0解决，更好是单独对j进行自增

/* ============================================================================
 * 【硬核底层：现代 CPU 的狂飙与底线】
 * ============================================================================
 * 1. 乱序执行（OoOE）：只要没有“数据依赖”(a = 1;b = a + 2;)，CPU 会强行打乱指令执行顺序，
 *    利用等待时间并行计算，怎么快怎么搞。
 * 2. 顺序退出（In-Order Retire）：虽然乱序执行，但最终结果必须按代码的逻辑顺序提交。
 * 3. 强制踩刹车：遇到“内存屏障（Memory Barrier）”或序列点，CPU 必须停止乱序，按顺序结算副作用。
 * 4. [安防暴击：侧信道攻击]：CPU 为了提高性能的“提前执行（预测执行）”，
 *    会让无权限的代码提前读取敏感数据（如 Spectre 幽灵漏洞），从而被黑客利用时间差盗取密码。
 * ============================================================================
 */

 // 运算符!的优先级和一元正负号的优先级相同，运算符&&和运算符!!的优先级低于关系运算符(<、>等)和判等运算符(==、!=)
 // 运算符!是右结合的，而运算符&&和运算符||都是左结合的。


 
/*5.2 if语句*/
// if语句允许程序通过测试表达式的值从两种选项中选择一种。if语句的简单形式如下:
// [if语句]  if (表达式) 语句  <-- 表达式两边的圆括号是必须的，它们是if语句的组成部分，而不是表达式的内容
// 还要注意，与在其它一些语言中的用法不同，单词then没有出现在圆括号的后边

// 执行if语句时，先计算圆括号内表达式的值。如果表达式的值非零(C语言把非零值解释为真值，非零即真)，那么接着执行圆括号后面的语句:
//      if (line_num == MAX_LINES)
//          line_num = 0;    <-- 如果条件为真，就执行
// 别混淆=(赋值)和==(判等)

// 通常if语句的表达式能判定变量是否落在某个数值范围内。例如，为了判定0<=i<n是否成立:
//      if (0 <= i && i < n)...
// 相反，判定i在此数值以外:
//      if (i < 0 || i >= n)...



/*5.2.1 复合语句*/
// 注意，在if语句里面，语句是一条语句而不是多条语句:
// if (表达式) 语句
// 如果想用if语句处理两条或更多条语句，可以引用复合语句(compound statement)。由一对花括号，以及花括号内的声明和语句混合而成(也可以么有声明或多条)
// 一条复合语句实例:
//      { line_num = 0; page_num++; }
// 为了清楚，将一条复合语句放在多行内:
//      { 
//        line_num = 0;
//        page_num++;
//      }
// 复合语句也常出现在循环和其他需要多条语句(但C语言的语法要求一条语句)的地方:
//      if (line_num == MAX_LINES) {
//          line_num = 0;
//          page_num++;
//      }
/* ============================================================================
 * 【C语言：复合语句（Compound Statement）】
 * ============================================================================
 * 1. 语法痛点：if / while / for 后面只能跟【一条】语句。
 * 2. 解决办法：用 {} 将多条语句包起来，变成【一条】复合语句（代码块）。
 * 3. 底层真相：{} 不仅用于语法打包，还划定了局部变量的【作用域】与内存的【生命周期】。
 * 4. [致命坑点]：
 *    - 忘写 {} 导致 if 无法控制多行代码，引发严重逻辑漏洞。
 *    - if (条件); 的分号本质是一条“空语句”，直接终结了 if。
 * ============================================================================
 */

// if以语句结尾，而非分号(;)



/*5.2.2 else子句*/
// if语句可以有else子句:
// [带有else子句的if语句]   if (表达式)语句 else语句
// 如果圆括号的表达式的值为0，那么就执行else后边的语句。
// 下面是一个含有else子句的if语句例子:
//      if (i > j)     <-- 后面没引号，和Python不同
//          max = i;   <-- 两条"内部"语句以分号结束
//      else           <-- 后面没引号，和Python不同
//          max = j;   <-- 两条"内部"语句以分号结束

// if语句包含else子句时，出现了布局问题:许多C程序员把它和if对齐排列在语句的起始位置。内部语句通常采用缩进格式;但是如果内部语句很短，可以把它们与if和else放置在同一行:
//      if (i > j) max = i;
//      else max = j;   <-- else后面也只能写一条语句，必要时用花括号括起来，且else跟在结束的if语句(表达式)后面

// C语言对可以出现在if语句内部的语句类型没有限制，if语句内部嵌套其他if语句是非常普遍的，下面的if语句是找到i、j、k中所存储的最大值并保存到max中:
//      if (i > j)
//          if (i > k)     <-- C语言里，if语句缩进纯好看，在Python则不一样
//              max = i;
//          else            <-- 先比较出一个大的，再在内部筛选一次
//              max = k;
//      else 
//          if (j > k)
//              max = j;
//          else            <-- 先比较出一个大的，再在内部筛选一次
//              max = k;
// if语句可以嵌套任意层。注意，把每个else同与它匹配的if对齐排列，这哟昂很容易辨别嵌套层次。如果仍然混乱，加花括号就可以了:
//      if (i > j) {
//          if (i > k)     <-- C语言里，if语句缩进纯好看，在Python则不一样
//              max = i;
//          else            <-- 先比较出一个大的，再在内部筛选一次
//              max = k;
//    } else {
//          if (j > k)
//              max = j;
//          else            <-- 先比较出一个大的，再在内部筛选一次
//              max = k;
//      }

// 也可以为每个if子句和else子句都使用一对花括号，除了复杂，可以添加更多语句进入子句，程序更易于修改;可以避免向子句增加语句忘记使用花括号



/*5.2.3 级联式if语句*/
// 编程时常常需要判定一系列的条件，一旦其中某一个条件为真就立刻停止。“级联式”if语句常常试编写这类系列判定的最好方法。例如，下面这个级联式if语句来判定n是小于0、等于0、还是大于0:
//      if (n < 0)
//          printf("n is less than 0\n");
//      else
//          if (n == 0)
//              printf("n is equal to 0\n");
//          else
//              printf("n is greater than 0\n");
// 虽然第二个if语句是嵌套在第一个if语句内部的，但是C程序员通常不会对它进行缩进，而是把每个else都与最初的if对齐:
//      if (n < 0)
//          printf("n is less than 0\n");
//      else if (n == 0)
//          printf("n is equal to 0\n");
//      else
//          printf("n is greater than 0\n");
/* ============================================================================
 * 【跨语言语法对比：else if vs elif】
 * ============================================================================
 * 1. 逻辑等价性：两者都用于实现多分支判断。
 * 2. 语法底层差异：
 *    - C 语言：else if 是嵌套语法（else 里面包着另一个 if）。没有独立关键字。
 *      不写大括号 {} 极易引发悬垂 else 漏洞。
 *    - Python：elif 是独立关键字，层级扁平，强制缩进，物理免疫悬垂 else 漏洞。
 * 3. [底层优化]：无论 C 还是 Python，编译成机器码后，底层全都是连续的
 *    CMP（比较）和 JMP（跳转）指令。
 * ============================================================================
 */
// else if 其实和elif 用法都一样，底层不同罢了，一个靠括号来确定层级，一个靠缩进，层级错了容易引起漏洞(C语言的悬垂漏洞是障眼法)

/* ============================================================================
 * 【安防极简笔记：悬垂漏洞】
 * ============================================================================
 * 一、 悬垂 else (Dangling else)
 * 1. 语法规则：else 永远与离它最近且未配对的 if (往上找)结合。
 * 2. 安防漏洞：没有 {} 时，人类的缩进错觉会导致逻辑走向完全相反，引发权限绕过。
 * 3. 防御：哪怕只有一行代码，if / else 内部也必须用 {} 包裹。
 * 
 * 二、 悬垂指针 (Dangling Pointer)
 * 1. 物理现象：free(p) 后，p 仍保留着内存地址。
 * 2. 安防漏洞：UAF（释放后使用）。指针被复用分配了恶意数据，导致程序崩溃或被控制。
 * ============================================================================
 */

 /* ============================================================================
 * 【C语言终极防御铁律：专治悬垂 else】
 * ============================================================================
 * 1. 规矩：else 永远与离它最近且未配对的 if 结合（编译器只认语法，无视缩进）。
 * 2. 隐患：不写括号，极易因为人类视觉错觉，导致逻辑被错误执行或绕过。
 * 3. 铁律：只要写 if / else / for / while，【哪怕里面只有一行代码，也强制加上 {}】。
 *    这不仅是代码规范，更是防范逻辑漏洞的顶级手段。
 * ============================================================================
 */

// 这样的安排带给级联式if语句独特的书写形式:
//     if (表达式)
//         语句
//     else if (表达式)
//         语句
//     ...
//     else if (表达式)
//         语句
//      else
//          语句
// 这样的匹配只能是层级往下走到底了，没有越级平级，
// 如果真要最后补一个else与前面的if对应，那就把这个else前面的与要配对的if后面的打一个花括号也够

// 请记住，级联式if语句不是新的语句类型，它仅仅是普通的if语句，只是碰巧有另外一条if语句作为else子句(而这条if语句又有另外一条if语句作为它自己的else子句，以此类推)



/*程序: 计算股票经纪人的佣金(broker.c)*/



/* ============================================================================
 * 【C语言运行时的终极真相：图纸与地址的粗暴游戏】
 * ============================================================================
 * 1. scanf (输入加工厂)：
 *    - 流程：接受字符流 -> 按图纸解析转换 -> 顺地址强行写入。
 *    - 原则：不认变量声明，只看地址大小，大小，注意字节数对应。图纸与地址尺寸匹配，无事发生；
 *            尺寸不匹配，直接越界覆盖相邻内存（栈溢出漏洞）。
 * 
 * 2. printf (盲目解释器)：
 *    - 流程：拿到图纸 -> 去寄存器/栈按图纸尺寸抓数据 -> 强行编码输出。
 *    - 特例：%f 和 %lf 等价，因为编译器传参时把 float 强制提升为 8字节 double。
 *    - 原则：除了浮点数，其他格式符（%d, %x, %c, %s）如果你给的参数不对应，
 *            它就按图纸的尺寸强行截断或越界读取，瞎解释一通（产生垃圾值）。
 * 
 * [终极定律]：类型在编译后消失。运行时，格式符（图纸）+ 内存地址 = 一切。
 * ============================================================================
 */
// scanf函数先接受，再想办法转换(前提是字节数要对应)，无事发生，只要地址与格式转换符对应就行，printf除了%f和%lf其他的你就给我对应，不然就强行解释了
// 这就是为什么声明一个浮点，再用scanf%f存入地址，输入就算是整型(字节数对应)也没事，会转化(用float型解释)的，只要地址和格式转换符对应就行，不用担心接受到不相干的东西，格式转换符规定了怎么那数据
// 但是后者是未定义行为



