/*5.2.5 条件表达式*/
// C语言还提供了一种特殊的运算符，这种运算符允许表达式依据条件的值产生两个值中的一个。
// 条件运算符(conditional operator)由符号?和符号:组成，两个符号必须按照如下格式一起使用:
// [条件表达式]   表达式1 ? 表达式2 : 表达式3
// 表达式1、表达式2和表达式3可以是任何类型的表达式，按上述方式组合成的表达式称为条件表达式(conditional exxxpression)。三元运算符

// 把  表达式1?表达式2:表达式3  读作"如果表达式1成立，那么表达式2，否则表达式3"，先计算表达式1的值，不为零则计算表达式2的值，否则计算表达式3的值;且这个计算的值就是整个条件表达式的值
//      int i, j, k;
//      i = 1, j = 2;
//      k = i > j ? i : j;     <--  k is now 2,因为i>j为假(0)，所以将j=2的值给k
//      k = (i >= 0 ? i : 0) + j;  <-- k is now 3,因为优先级过低，所以用括号括起来，括号里最后拿到的是i，再＋j赋给k
// 条件表达式使程序更短小但也更难阅读，因此最好避免使用。然而，在少数地方仍会使用，其中一个是return语句:
//      if (i > j)
//          return i;
//      else
//          return j;
// 替换为:
//      return i > j ? i : j;

// printf函数的调用有时候会得益于条件表达式:
//      if (i > j)
//          printf("%d\n", i);
//      else
//          printf("%d\n", j);
// 简化为:
//      printf("%d\n", i > j ? i : j);
// 条件表达式也普遍适用于某些类型的宏定义中(14.3节)

/* ============================================================================
 * 【条件表达式（三元运算符 ? :）底层速查】
 * ============================================================================
 * 1. 本质：它是表达式，必定产出值。底层汇编与 if-else 完全等价（CMP + JMP）。
 * 2. 结合性：右结合（a ? b : c ? d : e 等价于 a ? b : (c ? d : e)）。
 * 3. “什么都接”的隐患：会触发隐式类型提升。如 int 与 unsigned 混用，
 *    -1 会被强转为巨大的无符号数，极易引发逻辑绕过漏洞。
 * 4. 可读性雷区：嵌套超过两层就是灾难，代码审计时极易成为黑客隐藏后门的温床。
 * 5. [安全铁律]：能用 if-else 解决的复杂逻辑，绝不装逼写嵌套三目运算符。
 * ============================================================================
 */


 /* ============================================================================
 * 【同级右结合的“括号破坏定律”】
 * ============================================================================
 * 1. 定义：当多个运算符优先级相同时，C语言采用右结合（从右向左传递结果）。
 * 2. 危害：如果强行用 () 将左半部分先圈起来算，会强制变成左结合。
 * 3. 惨案：
 *    - a += b = 10（合法，b=10 传给 +=） vs (a += b) = 10（语法报错，右值不可赋值）
 *    - a ? b : c ? d : e（右结合短路） vs (a ? b : c) ? d : e（左结合，强制算完前缀，短路破坏）
 * 4. [铁律]：遇到同级的右结合（如赋值、三目），顺着从右往左的物理链路去读，【千万不要】用人类从左往右的直觉去加括号。
 * ============================================================================
 */


 /* ============================================================================
 * 【C语言底层真相：赋值表达式的返回值】
 * ============================================================================
 * 1. C语言中，赋值 = 是运算符。a = b 这个表达式，返回的值就是 b 的值。
 * 2. 这就是为什么 a = b = c = 10 能生效（右结合，不断返回 10 往下传）。
 * 3. [致命陷阱]：if (a = b) 恒为真（除非 b 是 0），且会篡改 a 的值。
 * 4. [高阶用法]：while ((ch = getchar()) != EOF) 利用返回值简化代码。
 * 5. [跨语言对比]：Python 的普通赋值不返回值，只有 3.8 之后的海象运算符 := 类似。
 * ============================================================================
 */



/*5.2.6 C89中的布尔值*/
// 多年来C语言一直缺乏适当的布尔类型，C89标准中也没有定义布尔类型。因此许多程序许需要变量能存储假或真值，麻烦。针对C89这一限制，一种解决方法是:
//      int flag;    <-- 先声明一个int型变量，然后将其赋值为0或1
//      flag = 0;
//      ...
//      flag = 1;
// 虽然可行，但没对可读性有贡献，该方法没有明确的表示flag的赋值只能是布尔值，并且没有明确指出0和1就是表示假和真。
//  为了是程序跟利于理解，C89程序员通常使用TRUE和FALSE这样的名字定义宏:
//      #define TRUE 1
//      #define FALSE 0
// 现在对flag的赋值有了更加自然的形式:
//      flag = FALSE;
//      ...
//      flag = TRUE;

// 为了判定flag是否为真，可以用
//      if (flag == TRUE) ...
// 或者只写
//      if (falg) ...

// 为了发扬这一思想，甚至可以定义一个可用作类型的宏:
//      #define BOOL int
//      BOOL flag;    <-- 声明布尔变量是可以用BOOL代替int;
// 现在非常清楚flag不是普通整型变量，而是布尔条件(当然，编译器仍然把falg看作int型变量。)后面介绍更好的方法，类型定义(7.5节)和枚举(16.5节)在C89中设置布尔类型



/*5.2.7 C99中的布尔值*/
// C99解决了缺乏布尔类型问题，提供了_Bool变量(实际上就是整型变量,更准确的说是无符号整型);但是和一般的的整型不用，_Bool只能赋值为0或1。一般来说，往_Bool变量中存储非零值会导致变量赋值为1:
//      _Boll flag;  <-- 布尔变量可以这样声明
