//      flag = true;
// <stdbool.h>头使用起来非常方便，因此在后面的程序中需要使用布尔变量时都用到了这个头。



/*5.3 switch语句*/
// 日常需要把表达式和一系列值进行比较，从中找出当前匹配的值。下面的级联式if语句根据成绩的等级显示出相应的英语单词:
//      if (grade == 4)
//          printf("Excellent");
//      else if (grade == 3)
//          printf("Good");
//      else if (grade == 2)
//          printf("Average");
//      else if (grade == 1)
//          printf("Poor");
//      else if (grade == 0)
//          printf("Failling");
//      else
//          printf("Illegal grade")
// C语言提供了switch语句作为这类级联式if语句的替代。下面的switch语句等价于前面的级联式if语句:
//      switch (grade) {                         <-- 执行这条语句时，变量grade的值与4、3、2、1、0进行比较(实则是匹配)，值匹配相同则执行下面的子句
//          case 4:     printf("Excellent");
//          case 3:     printf("Good");
//          case 2:     printf("Average");
//          case 1:     printf("Poor");
//          case 0:     printf("Failing");
//          default:    printf("Illegal grade");      <-- 如果都不匹配，按摩执行default分支
//                      break;                        <-- 然后break语句把控制传递给switch后面的语句
//      }


/* ============================================================================
 * 【C语言底层终极笔记：switch 语句的物理实现与漏洞利用】
 * ============================================================================
 * 核心口诀：密集建表瞬移，稀疏二分排查；break只是局部跳转，漏写直接穿透。
 * 
 * ============================================================================
 * 一、 底层实现机制（两种模式，取决于编译器的优化）
 * ============================================================================
 * 1. 跳转表（Jump Table）模式 —— O(1) 瞬间寻址：
 *    - 触发条件：case 的值是【连续】或【密集】的（如 case 1, 2, 3...）。
 *    - 物理本质：它不是元组，而是编译器在只读数据段（.rodata）建的一个【指针数组】。
 *    - 数组元素：存放的是每一个 case 代码块的【门牌号（内存地址）】。
 *    - 寻址公式：目标地址 = 表基地址 + (变量值 - 最小case值) * 指针大小(64位系统8字节)。
 *    - 编译器抠门优化：通过减去最小 case 值，让稀疏的 case 也能变成连续下标，避免数组空洞浪费。
 *    - 优势：无论 case 有多少个，一步数学运算瞬间定位，速度极快（相当于查字典）。
 * 
 * 2. 逐级比较/二分查找模式 —— O(n) 或 O(log n)：
 *    - 触发条件：case 的值极其【稀疏】（如 case 1, case 100, case 99999）。
 *    - 物理动作：退回为 if-else if 的逻辑，生成连续的 CMP 和 JMP 指令。
 * 
 * ============================================================================
 * 二、 致命陷阱：Fall-through（穿透）与 break 的真相
 * ============================================================================
 * 1. case 的本质：
 *    - case 并不是代码块的分隔符，它仅仅是内存里的一个【标签（Label）】。
 * 
 * 2. 为什么会发生穿透？
 *    - 编译器是【从左到右】单向扫描的。遇到 break，就吐一条 JMP（无条件跳转）
 *      指令；如果没写 break，编译器绝不会多管闲事生成 JMP。
 *    - CPU 顺着物理内存执行完当前 case 的代码后，因为没有 JMP 拦截，会顺理成章
 *      地“滑进”下一个 case 的代码块，导致后面的代码被连带执行。
 * 
 * 3. break 的作用域（局部暴君）：
 *    - break 绝不是作用全局的。它只作用于【离它最近的那一层】 switch 或循环。
 *    - 在嵌套结构中（如 for 循环里套 switch），switch 里的 break 只能跳出 switch，
 *      外层的 for 循环依然会继续跑。
 * 
 * ============================================================================
 * 三、 [安防暴击]：黑客如何利用 switch 搞破坏？
 * ============================================================================
 * 1. 逻辑穿透越权（漏写 break）：
 *    - 程序员在普通用户 case (Level 1) 忘写 break，黑客利用低权限账号进入，
 *      执行流顺延滑落进管理员 case (Level 9)，直接触发提权代码。
 * 
 * 2. 控制流劫持（篡改跳转表/越界读）：
 *    - 如果没写 default 且未校验变量范围，极端数值（如超大数或负数）会导致数组越界读。
 *    - 若黑客配合其他内存漏洞（如栈溢出），篡改了跳转表里的真实地址，CPU 就会
 *      直接跳进黑客构造的 Shellcode（恶意代码）里。
 * 
 * 3. 必须使用 default 兜底：
 *    - 如果变量值不匹配任何 case，程序会直接跳过 switch。在权限校验中，必须用
 *      default 抛出错误或拒绝访问，防止静默放行。
 * ============================================================================
 */

// switch语句最常用的格式如下:
// [switch语句] switch (表达式) {
//                  case 常量表达式: 语句
//                  ...
//                  case 常量表达式: 语句
//                  default: 语句
//              }

// switch语句十分复杂，下面逐一看一下它的组成成分:
// 控制表达式。switch后面必须跟着由圆括号括起来的整型表达式。C语言把字符(7.3节)当成整数来处理，因此在switch语句中可以对字符进行判定。但是，这不适用于浮点数和字符串。

// 分支表号。每个分支的开头都有一个标号，格式如下:
// case 常量表达式:

// 常量表达式很像普通的表达式，只是不能包含变量和函数调用。因此，5是常量表达式，5 + 10也是常量表达式，但n + 10不是常量表达式(除非n是表示常量的宏)。分支标号中常量表达式的值必须是整数(字符也可以)。

// 语句。每个分支标号的后边可以跟任意数量的语句，并且不需要用花括号括起来(是C语言少数几个不要花括号地方)。每组语句的最后一条通常是break语句


// C语言不允许有重复的分支标号，但对分支的顺序没有要求，特别是default分支不一定要放置在最后
// case后边只可以跟随一个常量表达式。但是多个分支标号可以放置在同一组语句的前面:
//      switch (grade) {
//          case 4:             <-- 多米诺骨牌效应，4、3、2、1完全执行同一个语句
//          case 3:
//          case 2:
//          case 1:     printf("Passing");
//                      break;
//          case 0:     printf("Failing");
//                      break;
//          default:    printf("Illegal grade");
//                      break;
//          }

// 为了节省空间，程序员有时还会把几个分支标号放置在同一行:
//      switch (grade) {
//          case 4: case 3: case 2: case 1:
//              printf("Passing");
//          case 0:     printf("Failing");
//          default:    printf("Illegal grade");
//                      break;
//      }
// switch语句不要求一定有default分支。如果default不存在，而且控制表达式的值和任何一个分支标号都不匹配的话，控制会直接传给switch语句后面的语句。

/* ============================================================================
 * 【switch 的“静默放行”危机与 default 的兜底】
 * ============================================================================
 * 1. 概念纠偏：C语言有“控制表达式”（即 switch 括号里的变量）。
 * 2. 底层真相：当控制表达式的值与所有 case 都不匹配且无 default 时，
 *    CPU 执行无条件跳转（JMP），直接滑过整个 switch 结构。
 * 
 * 3. [安防暴击：Fail-Open 静默放行漏洞]
 *    - 如果用于安全过滤（如防火墙、权限校验），漏写 default 会让未知输入
 *      直接绕过整个安全检查，执行后续代码。
 *    - 铁律：在任何涉及安全逻辑的 switch 中，【必须】写上 default 作为兜底，
 *      并在 default 中执行拒绝（deny）或报错逻辑，斩断控制流。
 * ============================================================================
 */

 /*break语句的作用*/
 // 需要break语句是由于switch语句实际上是一种"基于计算的跳转"。对控制表达式求值时，控制会跳转到与switch表达式的值相匹配的分支标号处。
 // 分支标号只是一个说明switch内部位置的标记。在执行完分支最后一条语句，程序控制"向下跳转"到下一个分支的第一条语句上，忽略下一个分支标号。
 // 如果没有break语句(或者其他某种跳转语句)，控制将从一个分支流向下一个分支。

 // 虽然switch语句中最后一个分支不需要break语句，但通常还是会放一个，以防将来增加分支数目时出现"丢失break"的问题。



 /*程序 显示法定格式的日期(date.c)*/



 /* ============================================================================
 * 【跨语言语法纠偏：C语言语句头不用冒号】
 * ============================================================================
 * 1. 语法真相：C语言的控制流语句头（if, while, for）绝对不加冒号，用 {} 划分作用域。
 * 2. 冒号在 C 语言里的四大去处：
 *    - case 标签/default (case 1:) —— 本质是内存地址的 Label。
 *    - 位段 (int a : 3) —— 精确切割内存比特位。
 *    - 三元运算符 (a ? b : c) —— 二选一分流。
 *    - goto 标签 (label:) —— 汇编 JMP 指令的马甲。
 * 3. [跨语言对比]：Python 的冒号是“缩进代码块”的开始；C 语言的冒号是“内存标签”。
 * ============================================================================
 */


 /* ============================================================================
 * 【C语言底层概念：标号 (Label)】
 * ============================================================================
 * 1. 本质：代码段里的一个“地址标记（门牌号）”，语法为 `标识符:`。
 * 2. 物理特性：不占内存空间，不生成机器指令，仅存于编译器的符号表中。
 * 3. 命名空间：拥有独立的命名空间，标号名可以与变量名完全相同而不冲突。
 * 4. 常见用法：
 *    - 配合 goto 语句实现强制无条件跳转（汇编 JMP）。
 *    - switch-case 里面的 case 和 default 本质上也是一种标号。
 * 
 * 5. [安防/逆向视角]：
 *    - 滥用 goto 标号会导致控制流混乱（面条代码），是代码审计重点盯防的对象。
 *    - 逆向时看到 JMP 指令，目标地址就是一个标号。栈溢出攻击（PWN）的本质，
 *      就是篡改程序流，让程序“goto”到恶意代码的地址。
 * ============================================================================
 */


// 每个case分支代表一个小世界，里面可以装很多表达式，甚至其他标号，直到遇到break，或下一个case或者结束switch语句
/* ============================================================================
 * 【switch 的微观世界：case 的物理边界与作用域陷阱】
 * ============================================================================
 * 1. case 的本质：只是一个内存地址标签，不提供物理隔离（没有自带大括号 {}）。
 * 2. 小世界的边界：break（JMP 指令）、下一个 case（Fall-through 滑落）、switch 的 }（尽头）。
 * 3. [安防暴击：跳过初始化]：
 *    - 所有的 case 共享 switch 的同一个栈帧。
 *    - 如果直接跳转到后面的 case，会跳过前面 case 里的变量初始化，导致变量变成垃圾值。
 * 4. [安全铁律]：如果要在 case 里声明变量并初始化，【必须】用大括号 {} 把整个分支包起来，
 *    强行开辟独立的作用域。
 * ============================================================================
 */



 /* ============================================================================
 * 【C语言底层终极总结：结合性、求值顺序与编译/CPU的错位博弈】
 * ============================================================================
 * 
 * 一、 核心概念切割：语法图纸 vs 物理执行
 * ----------------------------------------------------------------------------
 * 1. 优先级与结合性（编译期，画图纸）：
 *    - 优先级决定“谁和谁结合得更紧密”。
 *    - 结合性决定“同级相遇时，从左往右抱团，还是从右往左抱团”。
 *    - 【铁律】：优先级/结合性只决定【语法树（AST）长什么样】，绝对不代表 CPU 会先执行谁！
 * 
 * 2. 求值顺序（运行期，搬砖）：
 *    - 决定 CPU 真正在底层先算哪一块。
 *    - C 标准规定：大部分运算符（如 +, *, 函数传参）的求值顺序是【未指定】的（看编译器心情）。
 *    - 只有极少数运算符严格规定求值顺序：&&, ||, ?:（条件）, 逗号 ,（严格从左往右）。
 * 
 * ============================================================================
 * 
 * 二、 方向大乱斗：编译器、CPU 分别怎么读？
 * ----------------------------------------------------------------------------
 * 1. 编译器解析方向：
 *    - 左结合运算符（+ - * /）：从左往右解析构建树。
 *    - 右结合运算符（=, 三目 ?:）：从右往左解析构建树。
 * 
 * 2. 物理压栈方向（历史遗留）：
 *    - 函数传参（如 x86 cdecl 约定）：参数是【从右往左】压入栈的，为了确保第一个参数（格式串首地址）在栈顶。
 * 
 * 3. 求值执行方向（短路求值）：
 *    - 逻辑运算符 &&, || 严格【从左往右】执行。
 *    - 如果左边能决定结果（如 || 左边为真），右边整块代码【物理跳过不执行】。
 * 
 * 4. CPU 真实执行方向（乱序执行）：
 *    - 只要没有“数据依赖”，CPU 为了快，底层指令【怎么快怎么乱序跑】。
 *    - 但最终写回结果时，会按编译器的原本顺序（Retire）排列，欺骗人类。
 * 
 * ============================================================================
 * 
 * 三、 经典连环坑（不看必死）
 * ----------------------------------------------------------------------------
 * [坑点 1]：++i || ++j && ++k （假定 i=j=k=1）
 * - 编译器视角：&& 优先级高，把 ++j && ++k 画成一棵子树。
 * - 执行视角：遇到 ||，先算 ++i。i 变 2（真），直接短路！
 * - 结果：++j 和 ++k 整块被物理跳过，j 和 k 仍是 1，最终输出 2 1 1。
 * 
 * [坑点 2]：i = i++ （未定义行为 UB）
 * - 为什么会 UB？因为赋值 = 和自增 ++ 的求值顺序在 C 标准中未指定。
 * - 不同编译器（甚至同一编译器不同优化级别）可能先算 =，也可能先算 ++。
 * - 结果：未定义，不可预测。
 * 
 * ============================================================================
 * 
 * 四、 极客防身术（安防/底层视角）
 * ----------------------------------------------------------------------------
 * 1. 绝不在同一个表达式中，对同一个变量进行多次修改（如 i++, i-- 混用）。
 * 2. 遇到逻辑判断，先找最外层的 && 或 ||，看左边能不能直接短路，右边直接当垃圾处理。
 * 3. 永远用括号 () 强制锁死运算顺序。不要试图用人脑去推算优先级叠加。
 * 4. 永远不要试图预测未定义行为（UB）的结果，那是在用玄学写代码。
 * ============================================================================
 */



/* ============================================================================
 * 【底层寻址真相：相对偏移量 (Offset) vs 绝对地址 (Absolute Address)】
 * ============================================================================
 * 
 * ============================================================================
 * 一、 什么时候编译器会生成“绝对地址”？
 * ============================================================================
 * 1. 非PIE（位置无关代码）程序中的全局变量：
 *    - 现代系统默认编译为 PIE（允许程序加载到内存任意位置）。
 *    - 但如果关闭 PIE（例如某些老旧的嵌入式程序或加了 -no-pie 编译），全局变量
 *      在链接阶段就会被分配一个硬编码的绝对地址（如 0x00404020）。
 *    - 此时机器码里直接写死这个绝对地址，每次运行都不变。
 * 
 * 2. 内存映射 I/O (MMIO) / 硬件寄存器：
 *    - 在单片机或底层驱动开发中，你要控制某个硬件引脚，代码里会直接写死一个物理绝对地址。
 *    - 比如 `volatile int *reg = (int *)0x40010000;`，这里的 0x40010000 就是绝对的物理硬件地址。
 * 
 * ============================================================================
 * 二、 什么时候是在“运行期”才产生绝对地址？
 * ============================================================================
 * 1. 函数指针 / 数组指针：
 *    - 当你写 `int (*p)() = func;` 时，`p` 变量里存的，就是 `func` 在内存中的绝对地址。
 *    - 因为 CPU 的 RIP (指令指针寄存器) 需要跳转时，必须知道绝对的物理坐标，不能是个未知数。
 * 
 * 2. 全局偏移表 (GOT - Global Offset Table)：
 *    - 我们调用动态库函数（如 printf）时，编译期不知道它的绝对地址。
 *    - 操作系统在加载程序时，会去查动态库，把 printf 的【绝对真实地址】填入 GOT 表。
 *    - 程序运行时去 GOT 表里取的，就是绝对地址。
 * 
 * 3. 栈上的返回地址：
 *    - 当你调用一个函数时，CPU 会把“下一条指令的绝对地址”压入内存栈。
 *    - 栈溢出漏洞，就是黑客用恶意代码的【绝对地址】，覆盖了原本的返回地址。
 * 
 * ============================================================================
 * 三、 CPU 眼里的终极“绝对地址”（物理层面）
 * ============================================================================
 * 1. 虚拟地址 (Virtual Address)：
 *    - 你在 C 语言里用 `printf("%p", &a)` 看到的，都是虚拟绝对地址。
 *    - 它看起来是绝对固定的（比如 0x7ffc1234），但其实映射到物理内存的位置是系统随时换的。
 * 
 * 2. 物理绝对地址：
 *    - 真正打在内存条金属引脚上的电压信号。
 *    - 虚拟地址和物理地址之间，隔着 CPU 内部的 MMU（内存管理单元）。MMU 负责把它们翻译转换。
 * 
 * ============================================================================
 * 四、 黑客攻击视角：如何获取并利用“绝对地址”？
 * ============================================================================
 * 因为现代系统开了 ASLR（地址随机化），导致绝对地址每次都在变。
 * 黑客攻击（如 PWN、ROP）的终极流程，就是寻找“绝对地址”的过程：
 * 1. 【泄露】：用格式化字符串（%p）或内存溢出，泄露栈上或寄存器里的一个绝对地址。
 * 2. 【算基址】：用泄露的地址，减去它距离程序入口的“固定偏移量”，算出程序这次的【绝对基址】。
 * 3. 【打击】：将算出的基址 + `system` 函数的固定偏移量 = `system` 的绝对地址。
 * 4. 【覆盖】：把这个绝对地址，精准地覆盖到栈上的函数返回地址中。
 * ============================================================================
 */


// 在现代操作系统中：
// · 99% 的应用层代码（栈变量、函数跳转、全局变量）：机器码里记的全是【相对偏移量（Offset）】。
// 因为它要应对操作系统的 ASLR（地址随机化），所以代码必须是“位置无关代码（PIE）”。只要系统把基址（Base）一换，偏移量搭上去，程序照样跑。
// · 1% 的底层硬核代码：机器码里写死了【绝对地址（Absolute Address）】。主要出现在底层裸机开发（操作硬件引脚），或者关闭了 ASLR 的老旧系统/特殊固件中。


/* ============================================================================
 * 【计算机底层微观全景：虚拟地址、CPU、OS 与内存的“虚假游戏”】
 * ============================================================================
 * 
 * ============================================================================
 * 一、 四大核心“演员”
 * ============================================================================
 * 1. CPU（执行者）：无情的指令执行机器。它只认机器码，不认识变量名。
 * 2. 操作系统 (OS)（大管家）：负责内存分配、进程调度。为防黑客破坏，它给每个程序
 *    画了一张“大饼”，即分配独立的【虚拟内存空间】。
 * 3. MMU（内存管理单元）：长在 CPU 内部的硬件。专门负责把“虚拟地址”翻译成真实的“物理地址”。
 * 4. 内存条 (RAM)（仓库）：只认真实的物理地址，按地址提供数据电信号。
 * 
 * ============================================================================
 * 二、 程序运行时的寻址“四步曲”
 * ============================================================================
 * 1. 操作系统建字典（页表）：
 *    - 程序启动时，OS 在物理内存中建立一张【页表 (Page Table)】。
 *    - 记录了虚拟地址与物理地址的映射关系（受 ASLR 机制保护，每次运行的映射关系都随机打乱）。
 * 
 * 2. CPU 发号施令（拿假地址）：
 *    - CPU 执行机器码（如 MOV EAX, [0x7ffe1234]），此时它拿到的是【虚拟地址】。
 *    - CPU 将此假地址交给内部的 MMU。
 * 
 * 3. MMU 查字典翻译：
 *    - MMU 去查 OS 建好的【页表】。
 *    - 若查到：将虚拟地址替换为真实的【物理地址】。
 *    - 若没查到/越权访问：触发硬件异常，OS 介入，直接击毙该进程（即发生【段错误 Segmentation Fault】）。
 * 
 * 4. 内存条提供数据：
 *    - 真实的物理地址被送往内存条，内存条读出数据并返回给 CPU。
 * 
 * ============================================================================
 * 三、 为什么系统要搞这么复杂？（隔离与安全）
 * ============================================================================
 * 1. 防止互相踩踏：如果大家全用物理地址，程序 A 的野指针一不小心就会覆盖掉程序 B 的数据。
 * 2. 防御黑客攻击：因为引入了虚拟地址和 ASLR，黑客在本地根本不知道目标函数在物理内存的真实位置。
 * 
 * ============================================================================
 * 四、 安防与漏洞视角的降维映射
 * ============================================================================
 * 1. 野指针与段错误：
 *    - 黑客输入非法地址，MMU 查页表发现没这个假地址，或者权限不对，程序当场暴毙。
 * 
 * 2. 幽灵漏洞（Spectre）的物理基础：
 *    - CPU 的预测执行抢跑了，数据已经被拉进了 CPU 的【缓存 (Cache)】。
 *    - 随后 MMU 发现越权并报错（清空了寄存器），但数据残留在缓存中，黑客通过测速即可窃取。
 * 
 * 3. 漏洞利用（PWN）的本质：
 *    - 黑客需要先利用格式化字符串（%p）等漏洞，泄露一个真实的绝对地址。
 *    - 推算出程序本次运行的“基址（Base）”，从而绕过 MMU 的检查，精准篡改返回地址（执行恶意代码）。
 * ============================================================================
 */



 /* ============================================================================
 * 【底层战役复盘：CPU 内部的流水线与主战场】
 * ============================================================================
 * 1. 主战场（寄存器）：ALU 只能对寄存器进行运算，数据在这里诞生和消亡。
 * 2. 后勤部（Cache）：缓解内存速度慢的问题，按 Cache Line 喂数据给寄存器。
 * 3. 指挥部（控制器 CU）：取指、译码，指挥寄存器下一步该干嘛。
 * 4. 情报局（MMU）：把虚拟地址翻译成物理地址。
 * 5. 预测引擎：指令重排、乱序执行，确保寄存器永远满载运行。
 * 
 * [安防暴击]：黑客的终极目标，就是通过内存溢出，篡改【指令指针寄存器 (RIP)】，
 * 让主战场按照黑客的意志去执行代码。
 * ============================================================================
 */


 /* ============================================================================
 * 【底层终极暴击：switch 语句的物理实现、穿透陷阱与架构抉择】
 * ============================================================================
 * 
 * ============================================================================
 * 一、 底层实现：跳转表（Jump Table）的诞生与执行
 * ============================================================================
 * 1. 【编译器动作】（编译期：造图纸与字典）
 *    - 扫描 case 值：判断密度。密集则建表，稀疏则退化为 if-else。
 *    - 建立跳转表：在只读数据段(.rodata)创建一个【指针数组】。存放每个 case 代码块的
 *      真实内存地址（Label）。
 *    - 抠门减法：找到最小的 case 值，生成指令时自动将控制变量减去这个最小值，以节省
 *      数组的内存空洞。
 *    - 生成公式：生成指令（如 基址 + (x - 最小case) * 步长），不生成逐个比较的 CMP。
 * 
 * 2. 【CPU 动作】（运行期：无脑算地址与瞬移）
 *    - 接收变量：拿到 switch(x) 里的真实输入值。
 *    - 现场算数：执行减法（减最小值），执行乘法（乘步长 8 或 4），加上基址。
 *    - 盲跳：执行 JMP 指令，直接瞬移到算出的地址，全程 0 比较，实现 O(1) 极速。
 * 
 * ============================================================================
 * 二、 核心陷阱：Fall-through（穿透/贯穿）
 * ============================================================================
 * 1. 【编译器动作】：
 *    - 遇到 case 和 default：仅为其分配内存地址标签，不提供物理隔离（无大括号）。
 *    - 遇到 break：生成一条 JMP End_Switch 的无条件跳转指令。
 *    - 遇到故意不写 break：编译器原封不动地生成连续指令，中间不插跳转。
 * 
 * 2. 【CPU 动作】：
 *    - 顺着物理内存执行：如果没遇到 JMP（break），CPU 的指令指针（RIP）就会一往无前。
 *    - 多米诺骨牌：从当前 case 的标签处，直接滑落进下一个 case，甚至 default 也会被穿透。
 * 
 * ============================================================================
 * 三、 语法限制的物理原因
 * ============================================================================
 * 1. 【编译器动作】：检查类型。只有整型（int/char/enum）才能放进数组当索引。
 *    浮点数（有精度/连续）和字符串（本质是指针地址）会被直接报错拦截。
 * 2. 【CPU 动作】：如果是区间（如 >10），CPU 必须执行多条 CMP 指令；而整型的精准
 *    匹配，CPU 可以直接通过硬件内存寻址瞬间完成。
 * 
 * ============================================================================
 * 四、 [安防暴击] 黑客如何利用 switch 搞破坏？
 * ============================================================================
 * 1. 逻辑穿透越权：
 *    - 程序员漏写 break（没生成 JMP），黑客输入低权限 case，CPU 顺滑进入高权限代码。
 * 
 * 2. 跳转表越界读（控制流劫持）：
 *    - 编译器不检查边界。黑客输入极大/极小值，CPU 算出的 (x - 最小值) 变成非法下标。
 *    - CPU 会用这个非法下标去内存里读表，读到垃圾地址后强行 JMP，直接跳进黑客的陷阱。
 * 
 * ============================================================================
 * 五、 架构抉择：switch vs if-else vs 函数指针数组
 * ============================================================================
 * 1. switch：
 *    - 适合密集整数匹配。底层 O(1)，纯数学寻址无函数调用开销（不压栈）。
 * 2. if-else：
 *    - 适合区间判断、浮点/字符串比较、复杂逻辑。
 * 3. 函数指针数组（查表法）：
 *    - 适合状态机。用数组按值直接调用函数，极度灵活，但有函数调用的压栈/弹栈开销。
 * ============================================================================
 */


 /* ============================================================================
 * 【底层暴击：gcc 到底是个啥？】
 * ============================================================================
 * 1. gcc 的真相：它是一个【驱动程序 (Driver)】，负责调度四个底层工具：
 *    - 预处理器 (cpp)
 *    - 编译器核心 (cc1)
 *    - 汇编器 (as)
 *    - 链接器 (ld)
 * 
 * 2. 所有后缀的文件（.i, .s, .o, .exe）都是 gcc 命令生成的（具体由背后的工具产出）。
 * 3. 对应的 gcc 指令：
 *    - gcc -E : 只调预处理器，出 .i
 *    - gcc -S : 调预处理器+编译器，出 .s
 *    - gcc -c : 调预处理器+编译器+汇编器，出 .o
 *    - gcc    : 四个全套都调，出可执行文件
 * ============================================================================
 */


 /* ============================================================================
 * 【C语言底层语法：for 循环的空表达式】
 * ============================================================================
 * 1. 语法规则：for(初始化; 条件; 更新) 的三个表达式均可为空，但两个分号必须存在。
 * 2. 全部为空：for(;;) 等价于 while(1)，底层生成无条件死循环的机器码。
 * 3. 省略条件：默认条件恒为真，必须依靠内部 break 强行退出（JMP 指令）。
 * 4. 省略更新：常用于逻辑复杂的指针跳跃，或者在循环体内更新。
 * 5. [极客心法]：for 的本质就是“初始化、判断、跳转”。当你了解了它的底层骨架，
 *    三个表达式怎么摆弄，完全取决于你想怎么控制 CPU 的跳转指令。
 * ============================================================================
 */


 /* ============================================================================
 * 【极客重构指南：如何将“卫语句”写到完美？】
 * ============================================================================
 * 核心思想：Fail-Fast（快速失败）。一旦发现不合法，立刻终止当前函数，绝不让脏数据往下流。
 * 
 * ============================================================================
 * 一、 卫语句的“三层拦截体系”（从外到内完善）
 * ============================================================================
 * 完美的卫语句，不是把所有问题塞进一个 if，而是分层剥离：
 * 
 * 1. 第一层（防崩溃）：防御系统级灾难。
 *    - 如：指针判空（if (p == NULL) return;）、除零检查（if (b == 0) return;）。
 *    - 这种错误一旦放过去，程序直接报段错误（Segmentation Fault）。
 * 
 * 2. 第二层（防逻辑漏洞）：防御业务规则破坏。
 *    - 如：输入字符是否在合法白名单内（计算器里的 op 只能是 + - * / %）。
 *    - 这种错误不会让程序崩溃，但会让业务逻辑彻底乱套（比如执行了非法指令）。
 * 
 * 3. 第三层（防脏数据）：防御输入格式错误。
 *    - 如：检查 scanf 返回值是否为预期数量。确保变量里装的是用户输入，而不是内存里的随机垃圾值。
 * 
 * ============================================================================
 * 二、 C语言中完善卫语句的“利刃”
 * ============================================================================
 * 1. 多用 return，少用 else：
 *    - 一旦触发卫语句，直接 return，把后面的主干代码从嵌套里“解放”出来。
 *    - 物理动作：底层直接 RET 退栈，不执行后面的任何代码，效率极高。
 * 
 * 2. Linux 内核风格：goto 清理（终极杀招）
 *    - 如果在卫语句前，你已经 malloc 申请了内存，或者打开了文件。直接 return 会导致内存泄漏！
 *    - 完美解法：把卫语句统一指向错误处理标签。
 *    
 *    // 伪代码示例：
 *    // if (输入错误) goto error_cleanup;
 *    // if (内存不足) goto error_cleanup;
 *    // ... [主干逻辑] ...
 *    // return 0;
 *    // 
 *    // error_cleanup:
 *    //     free(ptr); // 统一释放资源
 *    //     return 1;
 * 
 * ============================================================================
 * 三、 计算器代码的“完美卫语句”骨架（只留逻辑，直接贴入你的函数中）
 * ============================================================================
 * 
 * int calculate(int a, char op, int b) {
 *     
 *     // 【卫语句 1：拦截非法运算符】
 *     if (op != '+' && op != '-' && op != '*' && op != '/' && op != '%') {
 *         printf("错误：非法运算符！\n");
 *         return 0; // 直接退出
 *     }
 *     
 *     // 【卫语句 2：拦截数学错误（除零）】
 *     if ((op == '/' || op == '%') && b == 0) {
 *         printf("错误：除数不能为 0！\n");
 *         return 0;
 *     }
 *     
 *     // ==========================================
 *     // 【主干逻辑区】（没被拦住，说明绝对是合法输入，代码不需要嵌套）
 *     // ==========================================
 *     switch (op) {
 *         case '+': return a + b;
 *         case '-': return a - b;
 *         case '*': return a * b;
 *         case '/': return a / b;
 *         case '%': return a % b;
 *     }
 *     return 0;
 * }
 * 
 * ============================================================================
 * 四、 [安防视角] 为什么黑客最喜欢没有卫语句的代码？
 * ============================================================================
 * 1. 逻辑绕过：如果程序员忘了写 op 是否合法的卫语句，黑客输入一个 '@'，
 *    程序可能直接跳过 switch，把未初始化的垃圾值当成结果，或者触发未知的副作用。
 * 2. 资源泄漏：如果在申请内存后，没有用卫语句拦截异常，程序中途 return，
 *    内存就永久泄露了（DoS攻击的根源）。
 * ============================================================================
 */


