/*
============================================================================
【极客复盘：C语言从编译到调试的底层全链路解析】
============================================================================
【核心心法】：源码只是图纸，GCC 负责把它变成物理实体，GDB 负责在内存里解剖它。

一、 逻辑本质与承上启下：
   - C 语言是编译型语言。源代码(.c)是纯文本，操作系统（CPU）根本不认识。
   - 必须经过编译器(GCC)翻译成机器码，链接成可执行文件(.exe / ELF)，CPU 才能执行。
   - 但程序跑起来后，如果出了 Bug 怎么查？这时就需要调试器(GDB)上场。
   - 调试的本质，是利用操作系统的 ptrace 机制，强行让 CPU 在指定的机器指令处暂停，
     并允许我们随意读取、修改内存和寄存器状态。

二、 GCC 编译指令与底层四步曲（承上）：
   - 基础指令：gcc 源文件.c -o 目标文件.exe
   - 核心参数：
     * -g：极度重要！告诉编译器在生成的可执行文件中，保留“源码行号与机器指令”的映射表（调试符号表）。没有这个，GDB 就是个瞎子，无法打断点。
     * -o：指定输出的文件名（output）。
     * -fdiagnostics-color=always：让编译器报错时带颜色（现代化 IDE 必备）。
   - 底层四步物理动作：
     1. 预处理：展开 #include 头文件，宏替换，删除注释（生成 .i）。
     2. 编译：把 C 代码翻译成汇编代码（生成 .s）。
     3. 汇编：把汇编代码翻译成机器指令（生成 .o / .obj 目标文件，此时还不能运行）。
     4. 链接：把目标文件与 C 标准库（如 printf 的底层实现）打包在一起，填平地址坑位，生成最终的 .exe。

三、 调试器配置与原理（启下）：
   - VS Code 只是个记事本，它靠两个 JSON 文件指挥外部工具：
   - 【tasks.json】（包工头）：
     - 作用：告诉 VS Code 怎么调用 gcc 编译。
     - 底层：执行 gcc 命令，并带上 -g 参数生成带调试信息的 exe。
   - 【launch.json】（指挥官）：
     - 作用：告诉 VS Code 怎么启动 gdb。
     - 底层："program" 指定要调试的 exe；"miDebuggerPath" 指定 gdb 在哪；
       "preLaunchTask" 表示在启动 gdb 之前，先触发 tasks.json 去编译。
   - 【联动原理】：
     按 F5 -> launch.json 启动 -> 触发编译任务 -> gcc 生成 exe -> 
     gdb 接管 exe -> 程序停在断点处。

四、 核心操作（上帝视角）：
   - F5 (继续)：全速运行，直到撞上红点（断点）或程序崩溃。
   - F10 (单步跳过)：执行下一行源码。遇到函数直接执行完，不钻进函数体。
   - F11 (单步进入)：执行下一行，遇到函数则“钻”进函数内部（进栈帧），看底层实现。
   - Shift+F5 (停止)：强行杀掉当前调试进程。
   - 左侧面板：
     * VARIABLES：看变量实时内存值。
     * REGISTERS：看寄存器（如 RIP 指令指针，RSP 栈顶指针）。
     * CALL STACK：看函数调用栈帧。
   - 反汇编视图：右键代码 -> “打开反汇编视图”，直接看 C 代码对应的底层汇编（MOV, ADD）。

五、 坑与反例（血泪铁律）：
   - 【路径含中文/空格死全家】：GCC 链接器 (ld.exe) 底层基于 ASCII，遇到中文或空格会直接解析为乱码，报错 "cannot open output file... No such file or directory"。代码工程路径必须全英文无空格。
   - 【没加 -g 参数】：哪怕你配了 json，如果 tasks.json 里没有 "-g"，gdb 会提示找不到符号表，断点打不上。
   - 【终端冲突】："externalConsole": true 会弹独立黑框；设为 false 则用内部终端。若内部终端调试带 scanf 的程序卡死，需检查输入流抢占。

六、 [安全微架构备注（黑客视角）]：
   - 为什么搞 PWN（二进制漏洞）的极客离不开这个？
   - 当黑客输入超长数据（如大量 0x41 也就是 'A'）导致【栈溢出】时，程序崩溃。
   - 在 GDB 中，黑客会死死盯着 RIP 寄存器。正常情况 RIP 应指向合法指令地址；
     但如果 RIP 变成了 0x4141414141414141，黑客就笑了：
     “脏数据不仅填满了缓冲区，还顺流而上，精确覆盖了栈帧底部的返回地址。”
   - 调试器让你亲眼看到内存溢出、指针越界、栈帧被撕裂的物理瞬间。懂了这个，你就拿到了底层世界的大门钥匙。
============================================================================
"""
*/


/*6.3.1 for语句的惯用法*/
// 对于“向上加”(自变量自增)或“向下减”(变量自减)的循环来说，for语句通常是最好的选择。对于向上加或向下减n次的情况，for语句经常会采用下列形式中的一种。

// 从0向上加到n-1(遍历0到n-1,共计n个元素):
// [惯用法]  for (i = 0; i < n; i++) ...

// 从1向上加到n:
// [惯用法]  for (i = 1; i <= n; i++) ...

// 从n-1向下减到0:
// [惯用法]  for (i = n - 1; i >= 0; i--) ...

// 从n向下减到1:
// [惯用法]  for (i = n; i > 0; i--) ...



/* 6.3.2 在for语句中省略表达式*/
// for语句比看得到的灵活，通常由三个表达式控制循环，但是有一些for循环可能不需要则还没多:
