//          printf("T minus %d and counting\n", i--);

// 如果省略第二个表达式，那么它默认为真值，因此for语句不会停止(除非以某种其他的形式停止)。
// 例如，某些程序员用下列for语句建立无限循环:  [惯用法]  for (; ;) ...



