/*6.3.4 逗号运算符*/
// 当我们编写多个初始表达式的for语句，或者希望在每次循环时一次对几个变量进行自增操作。使用逗号运算符作为for语句中第一个或第三个表达式可以实现这些想法。
// 逗号表达式的格式如下所示:
// [逗号表达式]  表达式1, 表达式2
// 这里的表达式1和表达式2是两个任意的表达式。逗号表达式的计算通过两步来实现:
// 第一步，计算表达式1并且扔掉计算出的值;第二步，计算表达式2，把这个值作为整个表达式的值。会表达式1的计算应该始终会有副作用;如果没有，那么表达式1就没有了存在的意义。

// 例如，假设变量i和变量j的值分别为1和5，当计算逗号表达式++i，i+j时，变量i先进行自增，然后计算i+j，所以表达式的值为7.(而且，显然现在变量i的值为2)，逗号运算符优先级最低，所以不需要在外面加圆括号。

// 有时需要把一串逗号表达式串联在一起，就如同某些时候把赋值表达式串联在一起。逗号运算符是左结合

// for语句是唯一可以发现逗号运算符的地方。例如，假设在进入for语句时希望初始化两个变量:
//    sum = 0;
//    for (i = 1; i <= N; i++)
//      sum += 1;
// 改写为
//    for (sum = 0, i = 1; i <- N; i++)


