/* ============================================================================
 * 【极客复盘：打破 for 循环的语法枷锁与底层真相】
 * ============================================================================
 * 
 * 1. 逻辑本质（大白话翻译）：
 *    for 循环的括号里虽然有三个位置，但本质上只有三个功能模块：
 *    - 表达式1（放要用的数）：初始化状态，只在开局干一次。
 *    - 表达式2（控制流表达式）：决定生死的闸刀，非0即真（继续），0即假（退出）。
 *    - 表达式3（状态更新语句）：只要跟“改变状态/值”有关的操作，全都可以往这里塞！
 *      绝不仅限于 i++，你可以写 i+=2、i*=2、甚至函数调用。
 * 
 * 2. 底层行为（语法糖的解构）：
 *    for 循环只是 while 循环的高级封装。编译器在底层会把 for 展开为：
 *    表达式1;
 *    while (表达式2) {
 *        循环体;
 *        表达式3; // <--- 物理上永远被放在这里（循环体末尾）
 *    }
 * 
 * 3. 第三个表达式的极限骚操作（极客专属）：
 *    - 步长突变：for (i = 1; i <= 1000; i *= 2)  // 每次翻倍
 *    - 双线操作：for (i=0, j=10; i<j; i++, j--)   // 利用逗号表达式同时改俩
 *    - 指针滑动：for (p=head; p!=NULL; p=p->next) // 数据结构遍历标配
 * 
 * 4. 核心顿悟与工程铁律：
 *    - [顿悟] 表达式2不一定专门用来限制次数，它也可以用来“校准”（如 n*n <= limit）。
 *    - [铁律] 表达式3虽然是个万能插槽，但工程上极度建议：只在这里修改“与循环
 *      终止条件相关”的变量，否则极易写出逻辑混乱的死循环。
 * 
 * 5. [安防视角：控制流与整数溢出]：
 *    - 如果把控制流表达式写得太复杂（如 n * n <= limit），黑客输入极大数值会导致
 *      n * n 发生【整数溢出】，变成负数后可能绕过判断，引发死循环（DoS）。
 *    - 防弹写法：用除法代替乘法（n <= limit / n），避免乘法溢出。
 *    - 空循环/死循环（for(;;)）：在底层只对应 CMP + JMP，极易被黑客构造恶意
 *      输入耗尽 CPU 资源。
 * ============================================================================
 */


 /* ============================================================================
 * 【极客复盘：控制流设计与循环心智模型】
 * ============================================================================
 * 
 * 1. 执行顺序（Time Line）：
 *    代码是按物理时间轴自上而下执行的。涉及输出或状态改变时，
 *    必须严格把控语句的先后顺序（如：先打印内容，再判断换行）。
 * 
 * 2. 状态隔离（Decoupling）：
 *    如果一个变量的“物理寿命”内承担了过多互相冲突的业务逻辑（如i既
 *    当空格计数又当日期），不仅容易把程序员自己绕晕，也极易引发逻辑灾难。
 *    解法：拆分成独立循环，或引入新变量独立记账（如 total_pos）。
 * 
 * 3. for 循环的数学与物理双轨模型：
 *    - 物理轨（死板的机器）：先执行一次表达式1；检查表达式2（只看当下的值）；
 *      执行循环体；执行表达式3；再回头查表达式2。
 *    - 数学轨（人类速算）：第 n 次循环的值 = 初始值 + 步增 * (n - 1)。
 *      导致退出的最后一次步增不计入执行次数。
 * ============================================================================
 */


 /* ============================================================================
 * 【极客复盘：循环变量与状态累加器的底层避坑】
 * ============================================================================
 * 
 * 1. 逻辑本质（状态累加）：
 *    - balance = balance * (1 + rate) - payment;
 *      这种写法叫“原地更新”。底层动作是把内存里的 balance 取到寄存器，
 *      算完后覆盖写回原地址。循环就是在不断迭代这个物理状态。
 * 
 * 2. 致命坑点（浮点数循环变量）：
 *    - 绝对禁止用 float / double 作为 for 循环的计数变量！
 *    - 原因：IEEE 754 浮点数存在精度丢失。长时间累加会导致变量变成 9.999999，
 *      从而绕过程序的退出条件，引发死循环（DoS）。
 *    - 铁律：for 循环的计数器，必须且只能用整型 (int / long long)。
 * 
 * 3. 工程规范：
 *    - 变量名别用 m, i, n 瞎糊弄，用 loan, rate, payment, balance。
 *    - 如果题目要求“输入”，千万别用 #define 写死。宏常量是在预处理阶段
 *      进行文本替换的，改代码还得重新编译。
 * ============================================================================
 */


 /* ============================================================================
 * 【极客复盘：scanf 的返回值、输入校验与缓冲区防御】
 * ============================================================================
 * 
 * 1. 逻辑本质（返回值是什么）：
 *    - scanf 返回一个整型 int，代表【成功读取并赋值的变量个数】。
 *    - 如果遇到文件结尾（Ctrl+Z / Ctrl+D）或底层读取错误，返回 EOF（通常是 -1）。
 * 
 * 2. 返回值状态解析（物理场景）：
 *    - 完美命中：scanf("%d/%d", &a, &b) 输入 "5/10"，返回 2。
 *    - 匹配失败：输入 "5/abc"，返回 1（a 成功，b 失败）。若输入 "abc"，返回 0。
 *    - 遇到 EOF：按 Ctrl+Z 强制结束输入流，返回 -1。
 * 
 * 3. 工程/安全铁律（Fail-Fast 卫语句）：
 *    - 铁律：必须把 scanf 的返回值塞进 if 或 while 里做条件判断！
 *    - 示例：if (scanf("%d/%d/%d", &m, &d, &y) != 3) { 处理错误/退出 }
 *    - 只要返回值不等于期望的变量个数，就说明输入不合规，绝对不能带着脏数据
 *      或未初始化的变量继续往下跑。
 * 
 * 4. 坑与反例（输入死循环 DoS）：
 *    - 致命坑：当 scanf 匹配失败（如要数字却输入字母），读取失败的字符会【卡在
 *      输入缓冲区中】。下一次循环 scanf 会直接去读这个字母，再次失败，引发
 *      “输入死循环”，导致程序疯狂打印错误且无法停止。
 *    - 防弹解法：发现返回值异常时，必须清空缓冲区。
 *      代码：while ((c = getchar()) != '\n' && c != EOF); 
 * 
 * 5. [安防微架构视角]：
 *    - 拒绝服务（DoS）：黑客若知道程序存在未校验 scanf 返回值的漏洞，只需
 *      持续发送垃圾字符（非格式串要求的类型），就能让服务器陷入死循环，耗尽 CPU。
 *    - 逻辑绕过：若程序读取失败但未拦截，后续代码可能使用上一次残留的垃圾值
 *      进行权限判断，导致业务逻辑被绕过。
 * ============================================================================
 */



 /*2026.11.1*/
 /* 第七章 基本类型*/
 /*7.1 整数类型*/
 // 整数类型的值是整数，而浮点类型的值则可能还有小数部分。而整数类型又分为两类:有符号整数和无符号整数。

 // 有符号整数如果为整数或零，那么最左边的位(符号位)为0;如果是负数，则符号位为1.因此，最大的16位数整数的二进制表示是0111111111111111，
 // 对应的数值是32767(即2^15-1),最大的32为整数就是(0后面跟31个1)对应2147483647(即2^31-1)
 // 不带符号位(最左边的位是数值时的一部分)的整数称为无符号整数。最大16位无符号整数是65535(即2^16-1)，32位无符号则是4294967295(即2^32-1)。

 // 默认情况下，C语言中的整型变量都是有符号的，也就是说最左位保留为符号位。若要告诉编译器变量没有符号位，需要把它声明成unsigned类型。
 // 无符号主要用于系统编程和底层与机器相关的应用

 // int型通常是32位，但是老CPU可能是16位。有些时候数很大，int无法存储，或者为了节省空间，C语言提供了长整型和短整型。
 // 为了构造整数整型满足要求，可以指明变量是long型或short型、singed型或unsigned型，甚至把说明符组合起来(如long unsigned int):
 // short int
 // unsigned short int

 // int
 // unsigned int

 // long int
 // unsigned long int

 /* ============================================================================
 * 【极客速记：C语言整型家族底裤】
 * ============================================================================
 * 
 * 【铁律 1】C 语言只规定“谁不能比谁小”，没规定死字节数！
 *   short <= int <= long <= long long
 *   (现在的 64 位 Windows/Linux 下：short=2字节, int=4字节, long=8字节, long long=8字节)
 * 
 * 【铁律 2】四大金刚与极值计算公式（n = 位数）：
 * 
 * 1. short (短整型) —— 2字节 (16位)
 *    - signed short 最小值: -2^15 = -32,768
 *    - signed short 最大值:  2^15 - 1 = 32,767
 *    - unsigned short 最大值: 2^16 - 1 = 65,535
 * 
 * 2. int (整型) —— 4字节 (32位) 【日常绝对主力】
 *    - signed int 最小值: -2^31 ≈ -21.4亿
 *    - signed int 最大值:  2^31 - 1 ≈ 21.4亿
 *    - unsigned int 最大值: 2^32 - 1 ≈ 42.9亿
 * 
 * 3. long (长整型) —— 4或8字节
 *    - 在 Linux/64位下是 8字节(64位)，在 Windows 下常被当成 4字节。
 *    - 极值套公式：-2^63 到 2^63-1。
 * 
 * 4. long long (超长整型) —— 8字节 (64位) 【防溢出神器，C99新增】
 *    - unsigned long long 最大值: 2^64 - 1 ≈ 1844亿亿
 * 
 * ============================================================================
 * 【格式符对应表】（printf / scanf 必用）：
 *   short:       %hd (有符号)    %hu (无符号)
 *   int:         %d  (有符号)    %u  (无符号)
 *   long:        %ld (有符号)    %lu (无符号)
 *   long long:   %lld(有符号)    %llu(无符号)
 *   (注：scanf 里读 short 需要加 &，读 long 用 %ld)
 * 
 * ============================================================================
 * 【极客安防暴击：最致命的无符号陷阱】
 * 
 * 1. 永动机死循环：
 *    for (unsigned int i = 10; i >= 0; i--)
 *    因为无符号数永远 >= 0，当 i=0 再减 1，会直接下溢变成 42.9亿，死循环。
 * 
 * 2. 逻辑绕过提权：
 *    if (length > 0) { copy_data(); } // 如果 length 是 unsigned
 *    黑客传入负数 -1，隐式转换为 42.9亿 (极大正数)，完美绕过长度校验，触发缓冲区溢出。
 * ============================================================================
 */


 /* ============================================================================
 * 【C语言底层硬核笔记：整型家族在不同架构下的字节数矩阵】
 * ============================================================================
 * 
 * 数据类型        16位系统        32位系统        64位(Linux/Mac)   64位(Windows)
 * ----------------------------------------------------------------------------
 * short           2 字节          2 字节          2 字节            2 字节
 * int             2 字节          4 字节          4 字节            4 字节
 * long            4 字节          4 字节          8 字节            4 字节 (坑!)
 * long long       8 字节          8 字节          8 字节            8 字节
 * void* (指针)    2 字节          4 字节          8 字节            8 字节
 * ----------------------------------------------------------------------------
 * 
 * 【极客避坑铁律】：
 * 1. Windows 下的 long 永远是 4 字节（微软为了兼容性死守 LLP64 模型）；
 *    Linux/Mac 下的 long 随系统位数升级，变成了 8 字节（LP64 模型）。
 *    跨平台写 C 语言，千万别瞎用 long，一不小心数据就被截断引发漏洞！
 * 
 * 2. 永远不要假设 int 就是 4 字节。要用固定字节，去包含 <stdint.h> 头文件，
 *    直接用 int32_t、uint64_t，这是搞底层和安全开发的最强护甲。
 * ============================================================================
 */


/*7.1.1 C99中的整数类型*/
// C99提供了long long int 和 unsigned long long int
// C99把 short int、int、long int 和 long long int 类型[以及signed char 类型(7.3节)]称为标准有符号整型
// 把 unsigned short int、unsigned int、unsigned long int 和 unsigned long long int 类型[以及unsigned char 类型(7.3节)]称为标准无符号整型



/*7.1.2 整型常量*/
// 常量————在程序中以文本形式出现的数，而不是读、写或计算出来的数。C语言允许使用十进制(基数为10)、八进制(基数为8)和十六进制(基数为16)形式书写整型常量。

// 八进制使用数字0~7书写的。八进制数的每一位表示一个8的幂(这就如同十进制数的每一位表示10的幂一样)。因此八进制数237转换为十进制数就是2 * 8^2 + 3 * 8^1 + 7 * 8^0 = 128+24+7 = 159
// 十六进制是用数字0~9加上字母A~F书写的，其中字母A~F表示10~15的数。十六进制数的每一位表示16的幂，十六进制数1AF的十进制数值是1 * 16^2 + 10 * 16^1 + 16 * 16^0 = 256+160+15=431

// 十进制常量包含0~9中数字，但是一定不能以零开头: 15  255  32767
// 八进制常量只包含0~7中的数字，而且必须以零开头: 017  0377  077777
// 十六进制常量包含0~9中的数字和a~f中的字母，而且总是以0x开头: 0xf  0xff  0x7fff
// 十六进制常量中的字母既可以是大写字母也可以是小写字母: 0xff  0xfF  0xFf  0xFF  0XFf  0XFF  0Xff

// 请记住八进制和十六进制只是书写数的方式，它们不会对数的实际存储方式产生影响。(整数都是以二进制形式存储的，跟表示方式无关。)
// 任何时候都可以从一种书写方式切换到另一种书写方式，甚至可以混用: 10 + 015 + 0x20 的值为55(十进制).八进制和十六进制更适用于底层程序的编写


/* ============================================================================
 * 【极客复盘：进制前缀的幻觉、物理转码与误差真相】
 * ============================================================================
 * 
 * 1. 核心心法（进制是人类的马甲）：
 *    - 人类写代码时用的“0”、“0x”前缀，仅仅是为了【给编译器看】。
 *    - 在物理内存和 CPU 眼里，根本没有十进制、八进制、十六进制，只有纯粹的 0101。
 *    - 只要“数值”相等，底层 01 绝对一模一样！(例如十进制 10 和十六进制 0xA，
 *      在内存中都是 0000 1010，连一个比特都不会差)。
 *    - 极易踩坑：十进制 10 ≠ 八进制 010 (八进制的010等于十进制8)。
 * 
 * 2. 逻辑本质（文本到二进制的剥离）：
 *    - 源码阶段：int a = 0x10; （此时在硬盘上，这只是一串 ASCII 码文本）
 *    - 词法分析：编译器（Lexer）看到 '0x' 前缀，立刻切换到十六进制解析模式，
 *      将其换算为十进制 16。
 *    - 物理生成：编译器彻底抛弃 '0x' 这个前缀文本，生成纯二进制机器码
 *      （如 0001 0000），存入 .exe 文件。
 * 
 * 3. 底层行为（机器码的凝视与小端序）：
 *    - 内存里的变量 a，实际上是 4 个字节：0x10 0x00 0x00 0x00（小端序）。
 *    - 此时没有任何“进制”的概念，只有高低电平。所谓的“十六进制”，
 *      只是人类为了方便查看内存，把 4 个比特（0101）压缩成 1 个字符（F）的“视觉马甲”。
 * 
 * 4. 为什么现代极客几乎不用八进制（0开头）？
 *    - 现代计算机的基础是字节（8 bit）。
 *    - 十六进制（0x）刚好是 4 bit 一组，两个十六进制字符完美拼成一个字节（8 bit）。
 *    - 八进制（3 bit 一组）无法和字节完美对齐，极难直观看出底层位模式，故被淘汰。
 * 
 * 5. 破除迷信：所谓的“读取误差”到底是什么？
 *    - 整数转换（如 10 和 0xA 互转）绝无误差，底层01完全一致。
 *    - 出现误差只有两种真相：
 *      A. 浮点数精度丢失：如十进制的 0.1，转成二进制是无限循环小数，内存截断后
 *         读出变成了 0.10000000000000001（IEEE 754 物理限制）。
 *      B. 类型截断：把 4 字节的 int 强转为 1 字节的 char，高位被物理砍掉。
 * 
 * 6. [安防/逆向暴击：十六进制的地下世界]：
 *    - 逆向工程（IDA Pro）：你看到的永远不是 C 代码，全是 0x401000 这种十六进制地址。
 *    - PWN 与内存溢出：黑客要把返回地址覆盖为 0x0804a020，必须把这段地址转成
 *      \x20\xa0\x04\x08（小端序字节流）打入内存。没有任何前缀，只有纯粹的字节。
 *    - Shellcode：手搓恶意代码时，汇编指令对应的机器码（如 0x31 0xC0 代表 xor eax, eax）
 *      全是十六进制字节。黑客的眼里，世界就是由 16 个字符构成的。
 * ============================================================================
 */


// 十进制整型常量的类型通常是int，但如果常量的值大得无法存储在int型中，那就用long int型。如果出现也不够的罕见情况，编译器会用unsigned long int做最后尝试。
// 确定八进制和十六进制常量的规则略有不同:编译器会依次尝试int、unsigned int、long int和 unsigned long int类型

// 要强制编译器把常量作为长整数来处理，只需在后边加上一个字母L(或l): 15L  0377L  0x7fffL
// 要指明是无符号常量，可以在常量后边加上字母U(或u): 15U  0377U  0x7fffU
// L和U可以结合使用，以表明常量既是长整型有时无符号的: 0xfffffffUL (字母L、U的顺序大小写无所谓)



/*7.1.3 C99中的整型常量*/
// C99中，以LL或ll(两个字母大小写要一致)结尾的整型常量是long long int 型的。如在LL或ll的前面或后面增加字母U(或u)，则该整型为unsigned long long int
// C99确定整型常量类型的规则和C89不同。对于没有后缀(U、u、L、l、LL、ll)的十进制常量，其类型是int、long int 或long long int中能表示的“最小”的类型
// 对于八进制或十六进制常量可能的类型顺序为int、unsigned int、long int、unsigned long int、long long int 和 unsigned long long int
// 常量后面的任何后缀会改变可能类型的列表。例如，以U(或u)结尾的常量类型一定是unsigned的一种，而L(或l)为后缀的结尾的十进制一定是long中的一种



/*7.1.4 整数溢出*/
// 有符号整数运算中发生溢出时，程序行为是未定义的，结果不确定(看编译器心情)。无符号整数运算溢出有定义:正确答案对2^n取模，其中n是用于存储结果的位数。
// 例如，如果对无符号的16位数65535加1，其结果可以保证为0.



/*7.1.5 读/写整数*/
// 假设其中一个int变量发生了“溢出”而无法工作，不仅要把变量的类型提升，还必须要检查数据类型的改变对其他程序的部分影响，尤其注意printf和scanf调用中。
// 如果已经用了，则需要改变调用中的格式串，因为%d只适用于int类型。
// 读写无符号整数、短整数和长整数需要一些新的转换指定符。

/* ============================================================================
 * 【极客复盘：scanf/printf 格式符与底层整型的致命匹配】
 * ============================================================================
 * 
 * 1. 核心心法：
 *    格式符就是给底层内存的“解码图纸”。类型与格式符不匹配，轻则数据乱码，
 *    重则内存越界（栈溢出），引发致命漏洞。
 * 
 * 2. 基础整型转换符（对应默认 int）：
 *    - %d : 有符号十进制 (signed int)
 *    - %u : 无符号十进制 (unsigned int)
 *    - %o : 无符号八进制 (unsigned int)  <-- 注意：输出无前缀的0
 *    - %x : 无符号十六进制小写 (unsigned int) <-- 输出无前缀的0x
 * 
 * 3. 长度修饰符（极其重要，对应不同物理字节数）：
 *    - h  (short)      : %hd (短整型) %hu (无符号短整) %ho %hx
 *    - l  (long)       : %ld (长整型) %lu (无符号长整) %lo %lx
 *    - ll (long long)  : %lld(超长整) %llu(无符号超长) %llo %llx
 * 
 * 4. 坑与反例（安防视角的物理踩踏）：
 *    - 致命坑一（scanf 强写内存）：如果 s 是 short（2字节），你手滑写了 
 *      scanf("%d", &s)；%d 会强行按 4 字节写入内存！多出的 2 字节会直接
 *      覆盖相邻的变量（栈溢出/内存踩踏），导致极其隐蔽的逻辑Bug。
 *    - 致命坑二（printf 强行解释）：如果 u 是 unsigned，值为 0xFFFFFFFF，
 *      你用 %d 打印，底层不报错，但会按有符号补码解释，输出 -1。
 * 
 * 5. [极客黑话：u、o、x 为什么都对应 unsigned？]：
 *    - 无符号数天生就是为了表示“纯纯的物理比特位”。
 *    - 把负数用 %x 打印，会直接输出它的底层补码形式（如 -1 打印出 ffffffff）。
 *      这是逆向分析、看内存地址、写 Shellcode 时最常用的极客神技。
 * ============================================================================
 */



