/*7.2 浮点类型*/
// C语言提供了3种浮点类型，对应三种不同的浮点类型:
// float: 单精度浮点数
// double: 双精度浮点数
// long double: 扩展精度浮点数

// 当精度不严格时，float类型是很合适的类型，double提供更高的精度，对绝大多数程序来说够用了。long double 支持极高精度的要求，很少用到

// C语言标准没有说明float、double和long double类型提供的精度到底是多少，因为不同的计算机可以用不同的方法存储浮点数。大多数遵循IEEE754标准


/*  IEEE浮点标准  */
// 提供了两种主要的浮点数格式:单精度(32位)和双精度(64位)。
// 数值以科学计数法的形式存储，每一个数都由三个部分组成:符号、指数和小数。指数部分的位数说明了数值的可能大小程度，而小数部分的位数说明了精度。
// 单精度格式中，指数长度位8位，而小数部分占了23位。因此，单精度最大可以表示的值大约是 3.40 * 10^38，其中精度时6个十进制数字

// IEEE标准还描述了另外两种格式:单扩展精度和双扩展精度。标准没有指明这些格式中的位数，但要求单扩展精度类型至少为43位，而双扩展精度类型至少79位。

/* ============================================================================
 * 【极客复盘：IEEE 754 浮点数物理极限表与底层避坑】
 * ============================================================================
 * 
 * 1. 逻辑本质（人类语言翻译）：
 *    - 浮点数就是为了在固定大小的内存里，同时塞下“极大的宇宙级数字”和“极小的
 *      量子级数字”，而发明的一种“科学记数法”妥协方案。
 *    - 它不是精确的，它只是“极其逼近”的近似值。
 * 
 * 2. 物理特征矩阵（表 7-4 极客速查）：
 *    ------------------------------------------------------------------------
 *    类型      最小正数(离0多近)        最大值(能多大)          有效数字(多准)
 *    ------------------------------------------------------------------------
 *    float     1.17549 × 10^-38        3.40282 × 10^38        6 位数字
 *    (单精度)  (极小，但不等于0)       (超出直接变成 inf)      (再长就截断)
 * 
 *    double    2.22507 × 10^-308       1.79769 × 10^308       15 位数字
 *    (双精度)  (真正的微尘)            (宇宙级容量)           (工业级精度)
 *    ------------------------------------------------------------------------
 * 
 * 3. 底层行为解析：
 *    - 【最大值的悬崖】：如果计算超过了最大值（如 float 超出 10^38），底层会触发
 *      上溢（Overflow），C语言输出为 inf（Infinity，无穷大）。黑客可借此打崩系统。
 *    - 【最小值的底线】：为什么最小是正数？因为 IEEE 754 有“非规格化数”兜底。
 *      一旦小于这个最小正数，底层会触发下溢（Underflow），直接强制变成 0.0。
 *    - 【精度的代价】：float 只能保证前 6 位有效数字，意味着第 7 位开始就是盲盒。
 * 
 * 4. 坑与反例（安防视角）：
 *    - 【大数吃小数】：如果有一个极大的 float (10^20) 加上一个 1.0，因为精度只有 6 
 *      位，那个 1 会被底层无情截断（吞没），加了个寂寞。
 *    - 【0.1 永远存不准】：0.1 在二进制里是无限循环小数，23位尾数根本存不下，所以
 *      存进去的其实是 0.100000001490116...。在做金融计算时，这种微小误差累加会
 *      变成致命的业务漏洞。
 * 
 * 5. [拓展认知]：
 *    - C99 还引入了 long double（80位或128位），以及 _Complex 复数类型。
 *    - 但记住一个铁律：在跨平台开发时，不要迷信 long double，因为它的物理大小在
 *      x86、ARM 甚至不同编译器下是完全不一样的！要固定大小，直接上 <stdint.h>。
 * ============================================================================
 */



