/*7.3.1 字符操作*/
// C语言中字符的操作非常简单，因为:C语言把字符当作小整数进行处理。毕竟所有字符都是以二进制的形式进行编码的。
// 例如:在ASCII码中，字符的取值范围是0000000~1111111，可以看成0~127的整数。字符'a'的值为97，'A'的值为65，'0'的值为48，而' '的值为32.

/* ============================================================================
 * 【极客极简笔记：ASCII 码的 127 分水岭与扩展底裤】
 * ============================================================================
 * 
 * 1. 有符号与 127 的极限：
 *    - 标准 ASCII 码规定了 0 ~ 127 代表英文字母、数字和符号。
 *    - 为什么只到 127？因为 C 语言默认 `char` 是【有符号】的（最高位是符号位）。
 *    - 127 的二进制是 `0111 1111`（\(2^7 - 1\)），这是 7 个比特能表示的最大正数。
 * 
 * 2. 无符号与剩下的扩展（128 ~ 255）：
 *    - 第 8 位（最高位）如果不要符号，`unsigned char` 就能装到 255。
 *    - 128 ~ 255 被称为“扩展 ASCII 码”（Extended ASCII）。
 *    - 【物理真相】：在单纯的英文环境，128~255 没人用。后来为了显示汉字等
 *      多字节字符，各国就拿这块区域开刀了（比如 GBK 就规定：只要字节大于 127，
 *      就说明这是个汉字的开头，需要连着读后一个字节）。
 * 
 * 3. 🚨 安防暴击（宽字节注入的万恶之源）：
 *    - 黑客输入 `%bf%27`。`0xbf` 是 191（大于 127），底层解码器一看：“哟，汉字开头！”
 *    - 于是它强行吃掉后面的单引号转义符 `\`（0x5c），导致单引号逃逸，SQL注入成功。
 *    - 【铁律】：处理底层二进制（网络包/固件），坚决用 `unsigned char`，避免 128~255
 *      的数据被当成负数（-128~-1）引发内存错乱。
 * ============================================================================
 */


// 当计算中出现字符时，C语言只是使用它对应的整数值:
//    char ch;
//    int i;
//    i = 'a';    <-- i是97(最后主要还是要看它的类型，这直接关系到内存划分于图纸翻译)
//    ch = 65;    <-- ch是'A'
//    ch = ch + 1;    <-- ch是'B'
//    ch++;           <-- ch是'C'

// 可以像比较数一样比较字符:(检查ch中是否有小写字母，有就转为大写)
//    if ('a' <= ch && ch <= 'z')   <-- 编译器发现字符做运算，做判断，就会转换
//      ch = ch - 'a' + 'A';

// 字符拥有和数相同的属性，这一事实会带来一些好处。例如，可以让for语句中的控制变量遍历所有的大写字母:
//    for (ch 'A'; ch <= 'Z'; ch++)...
// 字符终究是给人看的文本，不要老扒开它的外衣，用底层的二进制数字去做加减乘除。要处理字符，就用字符专属的函数；要做数学运算，就老老实实用整数。



