/*2026.11.2*/
/* ============================================================================
 * 【极客终极复盘：栈、堆、栈帧与 CPU 执行流的物理真相】
 * ============================================================================
 * 
 * 【一、 宏观内存版图：栈与堆的相向而行】
 * 1. 物理生长方向：
 *    - 栈（Stack）：从高地址向低地址生长（向下长）。极小（通常几MB），极快。
 *    - 堆（Heap）：从低地址向高地址生长（向上长）。极大，由程序员手动 malloc/free。
 * 2. 生死对决：
 *    两者相向而行，中间是空闲区。如果栈太深（无限递归）或堆太大（疯狂 malloc 不释放），
 *    两人就会在中间撞车，直接触发 OOM 或段错误（Segmentation Fault）。
 * 
 * 【二、 CPU 执行流：瞎子的导航仪（RIP 寄存器）】
 * 1. 顺序执行（滑行）：
 *    CPU 只认 RIP（指令指针）。没遇到特殊情况，读一条指令，RIP 自动加上长度，接着往下滑。
 * 2. 为什么不能一直滑下去？（为什么需要返回地址？）
 *    - 因为编译/链接后，代码在内存里的排布是乱序的（函数A后面不一定是函数B）。
 *    - 函数调用是动态的（主函数可以随时调 A 或 B）。
 *    - 如果把函数当成流水线一路滑过去，主函数的逻辑就彻底断片了。
 * 3. 终极解法（Call & Ret）：
 *    - 调用函数时：必须把“回来时的下一条指令地址”（书签）压入栈中，这就是【Return Address】。
 *    - 函数执行完：通过 ret 指令把书签取出来塞给 RIP，精准跳回原处继续滑行。
 * 
 * 【三、 栈帧解剖图（以 64 位倒挂栈为例）】
 * 物理内存（从高到低）：
 * --------------------------------------------------------------------------
 * [ 父函数的栈帧 ]      -> 调用者的地盘。
 * [ Return Address ]    -> 👑 核心！返回地址（书签）。ret 时塞给 RIP。
 * [ Saved RBP ]         -> 🛡️ 地基！上一层函数的基址指针。leave 时还给 RBP 寄存器。
 * [ 局部变量 (buf) ]    -> 📦 容器！数据从这里开始写入。
 * --------------------------------------------------------------------------
 * 极客法则：“栈向低处长，数据向高处写”。压栈是从上往下，写数据是从下往上。
 * 
 * 【四、 黑客的暴力覆盖（栈溢出物理现场）】
 * 1. 攻击原理：
 *    往局部变量（如 char buf[8]）中写入超长数据。数据像倒水一样，从低地址向高地址漫延。
 * 2. 覆盖 Saved RBP（换地基）：
 *    - 后果：上一层函数的“地基”被改成了垃圾值。当函数返回上一层后，所有局部变量基于 RBP
 *      的寻址（如 [rbp-4]）全部失效，数据乱放或程序当场崩溃。
 * 3. 覆盖 Return Address（劫持控制流）：
 *    - 后果：书签被篡改。函数执行 ret 时，CPU 拿着黑客伪造的地址塞进 RIP，直接跳进
 *      黑客的 Shellcode 或恶意函数中，系统彻底沦陷。
 * 4. 连环爆破（多层栈溢出）：
 *    只要输入数据够长，不仅能覆盖当前栈帧，还能一路向上淹没多个栈帧的 RBP 和返回地址。
 * 
 * 【五、 现代操作系统的防弹衣（绕过与防御）】
 * 1. Canary（金丝雀）：在局部变量和 RBP 之间插入一个随机数。溢出必踩死金丝雀，函数 ret 
 *    前校验失败，直接杀掉进程。
 * 2. ASLR（地址随机化）：栈的初始基址每次运行都随机，黑客无法写死绝对地址，必须先搞
 *    信息泄露（Leak）。
 * 3. NX（栈不可执行）：强行规定栈内存（数据）不可执行，黑客不能直接跳到栈上跑 Shellcode，
 *    逼得黑客发明了 ROP（返回导向编程）。
 * 4. Stack Pivoting（栈迁移）：高级黑客甚至故意修改 Saved RBP，利用 leave 指令将整个
 *    栈顶迁移到黑客控制的内存里，进行更复杂的花式攻击。
 * ============================================================================
 */


/*
【高地址】（天花板，比如 0x7FFF_FFFF_FFFF）
====================================================================
  [ 父函数的栈帧 ]  (Caller)
  假设这是 main() 函数的代码
  原本 main 里的变量在更上面
====================================================================
  【参数传递区】（可选）
  如果函数参数多于 6 个，多出来的参数会从右向左压入这里
====================================================================
  【Return Address】（返回地址）  👑 核心目标！
  - 怎么来的？ 执行 `call func` 指令时，CPU 自动压入的。
  - 有什么用？ 当 func 执行完，CPU 靠它知道该回 main 的哪一行继续执行。
  - 黑客视角？ 栈溢出就是改这里，改成恶意代码的地址。
====================================================================
  【Saved RBP】（保存的旧栈底指针） 🛡️ 保护现场
  - 怎么来的？ func 刚进门，执行 `push rbp` 压入的。
  - 有什么用？ 保护 main 函数的“地皮起点”。等 func 结束后，要把它还给 RBP 寄存器。
====================================================================
  【局部变量区】 (Local Variables)  📦 你的地盘
  - 怎么来的？ 执行 `sub rsp, 0x20` 分配出来的。
  - 存什么？ 比如 char buf[16]、int a、int b 等。
  - 危险地带？ 数组、缓冲区全在这里，越写越长就会向上漫延。
====================================================================
【低地址】（地板，比如 0x0000_0000_0000）
  ↑
【RSP 寄存器】 (栈顶指针：永远指着当前最底下那块砖) 
*/


/*7.3.4 转义序列*/
// 字符常量通常是单引号括起来的单个字符。然而，一些特殊符号(比如换行符)是无法采用上述方式书写的，因为它们不可见(非打印字符)，或者无法从键盘输入。
// 因此，为了使程序可以处理字符集中的每一个字符，C语言提供了一种特殊的表示方式————转义字符。

// 转移序列共有两种:字符转义序列和数字转义序列。
// 警报(响铃符)  \a          垂直制表符   \v             回退符    \b
// 反斜杠        \\          换页符      \f              问号      \?
// 换行符        \n          单引号      \'              双引号     \"
// 回车符        \r          水平制表符   \t

// \a、\b、\f、\r、\t和\v表示常用的ASCII控制字符，转义序列\n表示ASCII码的回行符

// 有个问题，转义序列没有包含所有可打印的ASCII字符，只包含了最常用的字符
// 为了把特殊字符书写成数字转义序列，首先在类似附录E那样的表中查找字符的八进制或十六进制值。例如，ASCII码中的ESC字符(十进制值为27)对应的八进制为33，对应的十六进制为1B

// 八进制转义序列由字符 \ 和跟随其后的一个最多含有三位数字的八进制数组成。(此数必须表示为无符号字符，所以最大值通常是八进制的377)
// 可以将转义字符写成\33或\033。跟八进制常量不同，转义序列中的八进制数不一定要用0开头。

// 十六进制转义序列由\x和跟随其后的一个十六进制数组成。虽然标准C对十六进制数的位数没有限制，但其必须表示成无符号字符(因此，如果字符长度是8位，那么十六进制数的值不能超过FF)
// 若采用这种表示法，可以把转义字符写成 \x1b或 \x1B的形式。字符x必须小写，但是十六进制的数字(例如b)不限大小写

/* ============================================================================
 * 【极客复盘：转义序列的进制占位与物理比特对齐】
 * ============================================================================
 * 
 * 1. 核心物理真相（看进制先看比特）：
 *    - 1 个二进制位（Binary） = 1 bit （状态：0~1）
 *    - 1 个八进制位（Octal）  = 3 bit （状态：0~7，对应 000~111）
 *    - 1 个十六进制位（Hex）  = 4 bit （状态：0~F，对应 0000~1111）
 * 
 * 2. 为什么十六进制吊打八进制？（字节对齐强迫症）：
 *    - 计算机的基础寻址单位是【字节（Byte）】，1 个字节 = 8 bit。
 *    - 8 是 4 的倍数：所以 1 字节 = 恰好 2 个十六进制位（完美对齐，如 0xFF）。
 *    - 8 不是 3 的倍数：所以 1 字节在八进制下无法完美切割（只能写成 0377，占 9 bit 的位置，最高位被截断）。
 * 
 * 3. 转义序列的取值范围极限（以 8 位 char 为例）：
 *    - 十六进制（\x）：最大 2 位数，\xFF（即 1111 1111，十进制 255）。
 *    - 八进制（\）：最多 3 位数，\377（即 11 111 111，十进制 255）。
 *    - 注意：八进制转义序列不强制以 0 开头，\33 等价于 \033。
 * 
 * 4. 坑与反例：
 *    - 超出范围截断：如果硬写 \x1FF（9 bit），编译器会截断最高位，或者直接报 Warning。
 *    - 字符串解析歧义：\x 会尽可能吞掉后面的十六进制字符。如 "\xff1"，会被解析为一个巨大的十六进制数（超范围），而不是 "字符 \xff" 拼上 "字符 1"。
 * 
 * 5. [安防/PWN 视角：黑客为什么要用十六进制]：
 *    - 构造 Payload 时，内存地址和机器码全是以字节为单位。用十六进制写 \x20\xa0\x04\x08 
 *      可以精准映射到内存的每一个字节，一目了然。
 *    - 如果用八进制写 \040\240\004\010，不仅冗长，且极易因为多敲一位数字导致越界截断，让 Payload 报废。
 * ============================================================================
 */


// 作为字符常量的使用，转义序列必须用一对单引号括起来。例如，表示转义字符的常量可以写成'\33'(或'\x1b')的形式
// 转义序列可能有点隐晦，所以采用#define的方式给它们命名是不错的注意:
//    #define ESC '\33'



