/* ============================================================================
 * 【极客极简笔记：toupper 的越界暗雷与强转防御】
 * ============================================================================
 * 
 * 1. 物理真相（为什么符号会变成负数）：
 *    - 底层没有“符号”，只有 0~255 的字节。
 *    - 默认 char 是有符号的（-128~127）。如果输入特殊符号（如 0xFF），最高位为 1，会被解析成负数（-1）。
 * 
 * 2. 越界原理（为什么程序会崩）：
 *    - toupper 底层是【数组查表】：return table[c];
 *    - 传入负数（如 -1）时，变成 table[-1]，导致数组负下标越界！
 *    - 结果：轻则段错误（Segmentation Fault）闪退，重则泄露相邻内存的敏感数据（越界读）。
 * 
 * 3. 极客防弹铁律：
 *    - 永远、绝对要在输入传给 toupper / 字符处理函数前，强转为无符号！
 *    - 代码：ch = toupper( (unsigned char)ch );
 *    - 原理：把负数强行拉回 0~255 的正数区间，把 table[-1] 变成合法的 table[255]，彻底拆除越界炸弹。
 * 
 * 4. [安防视角]：
 *    - 黑客故意输入 0xFF 等畸形乱码，就能引发 WAF（防火墙）程序崩溃（DoS攻击）或造成信息泄露。这是代码审计的必查点。
 * ============================================================================
 */

// toupper函数不是在C函数库中唯一实用的字符处理函数。



