// 在读入i的同时，scanf函数调用将留下没有消耗掉的任意字符，包括但不限于换行符。getchar函数随后将取回第一个剩余字符。(缓冲区残留)

/* ============================================================================
 * 【极客复盘：getchar/putchar 返回值类型阴谋与 EOF 陷阱】
 * ============================================================================
 * 
 * 1. 逻辑本质（为什么返回 int 而不是 char）：
 *    - getchar() 读取一个字节，但为了能明确区分“正常读到的字符”和“文件结束符”，
 *      它返回 int（4 字节）。
 *    - 正常字符：返回 0~255 的正数。
 *    - 文件结束（或错误）：返回 EOF（宏定义，通常是 -1）。
 * 
 * 2. 底层物理真相（隐式转换与截断撞车）：
 *    - 如果直接用 char 接收：char ch = getchar();
 *    - 默认 char 是有符号的（-128~127）。
 *    - 如果读到一个特殊的二进制字符 0xFF（十进制255），把它塞进 char 时，最高位为 1，
 *      它会被截断并解释为 -1。
 *    - 灾难：此时 -1 既可能是正常字符 0xFF，也可能是文件结束符 EOF。程序彻底瞎眼。
 * 
 * 3. 坑与反例（死循环灾难）：
 *    char ch;
 *    while ((ch = getchar()) != EOF) { ... } 
 *    遇到含有 0xFF 的文件会引发无限死循环或提前退出（逻辑错乱）。
 * 
 * 4. 极客防弹铁律：
 *    - 接收 getchar() 的返回值，永远、必须使用 int！
 *    - 代码：int ch; while ((ch = getchar()) != EOF)
 * 
 * 5. 关于 putchar()：
 *    - putchar(int c) 参数也是 int。传入 char 会自动【整型提升】为 int，
 *      内部再截断只取最低 8 位输出到屏幕。
 * 
 * 6. [安防视角]：
 *    - 这是典型的【类型混淆漏洞】温床。如果在处理网络二进制流或文件解析时用错了类型，
 *      黑客故意传入含 0xFF 的数据，就能引发死循环（DoS）或截断绕过逻辑检测。
 * ============================================================================
 */



