/*2026.11.3*/
/*7.4 类型转换*/
// 为了让计算机执行算术运算，通常要求操作数有相同大小(即位的数量相同)，并要求存储的方式也相同。计算机也许可以直接将两个16位整数相加，
// 但是不能直接将16位整数和32位整数相加(无法对其，CPU不算，可以让编译器整型提升)，也不能直接将32位整数和32位浮点数相加(底层图纸不一样)。

// C语言允许表示中混合使用基本类型。在单个表达式可以组合整数、浮点数甚至是字符。编译器可能对操作数进行转换成不同类型，是的硬件可以对操作数进行计算。
// 例如，如果对16位short型数和32位int型数进行加法操作，那么编译器会把16位short型值转换成32位值。如果是int型和float型进行加法操作，安排int型转为float格式(相对复杂，存储类型不同)

// 因为编译器可以自动处理这些转换，所以称为隐式转换。C语言还允许程序员使用强制运算符执行显示转换，先讨论隐式转换，(复杂，C语言有大量不同的算术类型)

// 当发生下列情况时会进行隐式转换:
// 当算术表达式或逻辑运算符(关系运算符（<、>）真的会发生类型转换，但纯逻辑运算符（&&、||）在真正的汇编底层，往往是不转类型的！)操作数的类型不同相时。(C语言执行所谓的常规算术转换)
// 当赋值运算符右侧表达式的类型和左侧表达式变量的类型不匹配时。
// 当函数调用的实参类型与其对应的形参类型不匹配时。
// 当return语句中表达式的类型和函数返回值的类型不匹配。



/*7.4.1 常规的算术转换*/
// 常规算数转换可用于大多数二元运算符(包括算术运算符、关系运算符和判等运算符)的操作数。
// i为int，f为float，f+i显然要将变量i转换为float类型(匹配变量f的类型)比把变量f转换成int类型(匹配变量i的类型)更安全。
// 整数转float类，最糟糕是精度会有少量损失，但是浮点转int型，将会有小数部分的损失;更糟糕的是，如果原始的数大于最大可能值或者小于最小可能值，那么得到完全没意义的数

// 安全准换两个类型数值“最狭小的”数据类型。通常可以将相对较狭小类型的操作数转换成另一个操作数类型来实现(提升)，相对常用的提升是整数提升。

// 执行常规算数转换的规则可以划分成两种情况:
// 任一操作数的类型是浮点类型的情况:  float -> double -> long double  (只往上精度去转换，int类型，包括long int无条件转浮点类那边)
// 两个操作数的类型都不是浮点类型的情况: int -> unsigned int -> long int -> unsigned long int  (有一种特殊情况，只有在long int 和 unsigned int 类型长度相同(比如32位)时发生:如果一个操作数时long int 一个是unsigned int ，那么都变成unsigned long int)

// 注意:有符号操作数和无符号操作数组合起来时，有符号操作数会被“转换”为无符号的值。转换过程中需要加上或减去n+1的倍数(取模)，其中n是无符号类型能表示的最大值。这条规则可能导致隐蔽的编程错误
// 假设int类型的变量i值为-10，而unsigned int 类型的变量u值为10。如用<比较i和u，i会转换为无符号，也就是加上4294967296的结果，所以为假。
// 因为此类陷阱的存在所以尽量避免使用无符号整数，特别是不要把它和有符号混合整数混合使用。

// 下面的例子显示了常规算术转换的实际执行操作:
//    char c;
//    short int s;
//    int i;
//    unsigned int u;
//    long int l;
//    unsigned long int ul;
//    float f;
//    double d;
//    long double ld;

//    i = i + c;    <-- c转换为int
//    i = i + s;    <-- s转换为int
//    u = u + i;    <-- i转换为unsigned int
//    l = l + u;    <-- u转换为long int
//    ul = ul + l;  <-- l转换为unsigned long int
//    f = f + ul;   <-- ul转换为float
//    d = d + f;    <-- f转换为double
//    ld = ld + d;  <-- d转化为long double



/*7.4.2 赋值过程中的转换*/
// C语言遵循把赋值运算右边的表达式(更强调值)转换成左边变量的类型。如果变量的类型至少和表达式类型一样“宽”，那么这种转换将没有任何障碍:
//    char c;
//    int i;
//    float f;
//    double d;

//    i = c;   <-- c转换为i
//    f = i;   <-- i转换为float
//    f = d;   <-- d转换为float(都是依着左边的变量类型，我管你什么精度不精度的)(但是会造成精度丢失)
//    d = f;   <-- f转换为double

// 其他情况下是有问题的，把浮点数赋值给整型变量会丢掉该数的小数部分:
//    int i;
//    i = 842.97;  <-- i是842
//    i = -842.97;  <-- i是-842   (补充一下，浮点数必须是有符号的)
// 此外，把某种类型的值赋给类型更狭小的变量时，如果该值在变量类型范围之外，那么将得到毫无意义的结果(甚至更糟[未定义行为]):
//    c = 10000;   <-- WRONG   (宽度过小，高位砍掉)
//    i = 1.0e20;  <-- WRONG   (浮点转整型溢出，未定义行为)
//    f = 1.0e100; <-- WRONG   (浮点之间的宽度过小，(发生上溢则变成+inf无穷大，发生下溢则变成0.0))

// 如果浮点常量被赋值给float型变量，那么建议后面尾部加上f:
//    f = 3.14159f;    <-- 如果没有后缀，那么常量3.14159是double类型，但是f存的还是float类型。


/* ============================================================================
 * 【极客复盘：C语言的物理边界——赋值截断、算术溢出与图纸重解释】
 * ============================================================================
 * 
 * 【一、 核心心法：赋值（搬运） vs 运算（加工）】
 * - 赋值（=）：是数据搬入指定大小的内存坑位。装不下就物理切割（截断）或报错（UB）。
 * - 运算（+ - *）：是 CPU 计算。超出容器极限就是溢出，无符号回绕，有符号引发 UB。
 * 
 * ----------------------------------------------------------------------------
 * 【二、 存入/赋值时（宽转窄）的物理惨状】
 * 1. 整数变窄（如 int 赋给 char）：物理截断。
 *    - 底层动作：电锯直接切掉高位，保留低位。
 *    - 例子：int 10000 赋给 char，高位被砍，剩下 16，发生残酷的“轮回”(不算那种溢出轮回)。
 * 
 * 2. 浮点转整型（超界）：未定义行为（UB）。
 *    - 底层动作：如果浮点数远超整数最大范围，x86 CPU 不会去切高位，而是直接
 *      塞一个硬编码的极端垃圾值（如 INT_MIN = -2147483648）。
 *    - 例子：int i = 1.0e20; 结果变得毫无意义。
 * 
 * 3. 浮点变窄（如 double 赋给 float）：精度销毁。
 *    - 底层动作：尾数被截断（精度丢失），指数过大直接变成 +inf（无穷大），
 *      指数过小直接变成 0.0。绝不发生“轮回”。
 * 
 * 4. 有符号赋给无符号：纯纯的“图纸重解释”。
 *    - 底层动作：比特位一个都不改。原本代表负数的最高位 1，瞬间被当成正数的数值，
 *      -1 直接变成 4294967295（42亿）。
 *    - 安防暴击：黑客传 -1 绕过长度检测，转无符号后变成天文数字，引发堆溢出。
 * ----------------------------------------------------------------------------
 * 
 * 【三、 计算时（算术溢出）的物理真相】
 * 1. 加法溢出（进位爆表）：
 *    - 无符号：最高位进位被硬件无情丢弃，发生“表盘轮回”（如 255 + 1 = 0）。
 *    - 有符号：最高位翻转变成负数。C 标准规定为 UB，O2 编译器可能因此删掉你的防御代码。
 * 
 * 2. 乘法溢出（宽度爆炸）：
 *    - 硬件层：CPU 乘法器（如 32位乘 32位）天生产生双倍宽度（64位）结果。
 *    - 赋值层：若你只用 32 位容器去接，高 32 位被无情丢弃，只留低 32 位。
 *    - 安防暴击（提权温床）：黑客利用 `size = count * 100`，让高位溢出被丢弃，
 *      使 size 变成极小值（绕过 malloc 限制），后续循环写入撑爆堆内存。
 * ----------------------------------------------------------------------------
 * 
 * 【四、 极客安防终极铁律】
 * 1. 凡涉及“大转小”：必须做边界检查（卫语句拦截），防止截断绕过。
 * 2. 凡涉及“乘法”：必须用除法反向验证（如 `if (a > MAX / b)`），坚决防范乘法溢出。
 * 3. 凡涉及“有符号转无符号”：坚决禁止裸奔，代码审计必查负数绕过漏洞。
 * 4. 永远不信任编译器的默认优化，保护溢出代码记得加 `-fwrapv` 或 `volatile`。
 * ============================================================================
 */



/* ============================================================================
 * 【极客复盘：补码的“轮回”机制与图纸解码法则】
 * ============================================================================
 * 
 * 1. 逻辑本质（轮回与溢出机制）：
 *    - 内存就是一个容量为 2^n 的环形表盘。负数并不是真的带个负号，而是从 0 
 *      开始“倒车”的结果。补码的本质是【同余定理（取模）】。
 *    - 例：-1 在 8 位系统里，等价于 255（全1）；在 32 位系统里等价于 42 亿。
 *    - 【终极真相】：CPU 硬件里根本没有“减法器”，只有“加法器”。减法（A - B）
 *      在底层被偷偷转换成了加法（A + (-B)）。
 *    - 【神级溢出】：为什么 5 + (-5) 能等于 0？因为在硬件加法器里，最高位的进位
 *      (Carry) 被物理抛弃了！靠这种“丢弃”，完美还原了真实的数学结果。
 * 
 * 2. 底层物理沙盘（以 8 位系统为例）：
 *    - 5 的补码：0000 0101
 *    - -5 的补码：1111 1011 (取反加一)
 *    - 相加物理过程：
 *        0000 0101
 *      + 1111 1011
 *      -------------
 *      1 0000 0000  <-- 最高位的 1 超出了 8 位寄存器，被物理电路无情丢弃！
 *      留下的 0000 0000 就是 0。靠硬件的“算术溢出”，算出了绝对精确的数学值。
 * 
 * 3. 底层物理真相（图纸解码三步曲）：
 *    拿到一串 0101，怎么解释？看【最高位】和【图纸（类型）】：
 *    - 如果最高位是 0（正数）：原码 = 反码 = 补码(这是规定，不需要执行取反加一操作)。
 *      直接按二进制算数值。
 *    - 如果最高位是 1（负数）：
 *        - 图纸是 unsigned：无视符号位，全当正数算（极大值）。
 *        - 图纸是 signed：按补码逆向推导（减一取反 / 或再取反加一），解出负数真实值。
 * 
 * 4. 致命误区（必须避开的坑）：
 *    - 【浮点数不用补码】：float/double 底层走的是 IEEE 754（符号+指数+尾数），
 *      如果把浮点数的位模式当补码解，会得出极度离谱的垃圾值。
 * 
 * 5. [安防视角：溢出即灾难]：
 *    - 既然补码靠“溢出”算减法，那如果【正数 + 正数】发生溢出呢？
 *    - 灾难：正数相加导致最高位变成了 1，在有符号图纸下，它会瞬间变成负数！
 *    - 类型混淆：黑客把 -1 传给无符号变量（如 size_t 或 unsigned int），底层瞬间
 *      变成 42 亿。如果用于申请内存或拷贝长度，直接引发堆溢出或拒绝服务。
 *    - 铁律：永远不要在有符号和无符号之间“裸奔”比较，写代码前先想好，这块内存
 *      到底该用哪种图纸去解释。计算前必须做边界溢出检查。
 * ============================================================================
 */



/*7.4.3 C99中的隐式转换*/
// C99增加了一些类型(_Bool、long long类型、扩展的整数类型和复数类型)
// 为了定义转换规则，C99允许每个整数类型具有“整数转换等级”。下面按从最高级到最低级的顺序排列:
// (1) long long int、unsigned long long int
// (2) long int、unsigned long int
// (3) int、unsigned int
// (4) short int、unsigned short int
// (5) char、signed char、unsigned char
// (6) _Bool
// 简单起见，这里忽略了扩展到整数类型和枚举类型。

// C99用整数提升取代了C89中的整值提升，可以将任何等级低于int和unsigned int 类型转换为int(只要该类型的所有值都可以用int类型表示)或unsigned int。(根本不存在比int小的类型操作数在CPU运算)
// 与C89一样，C99中执行常规算术转换的规则可以分为两种情况:
// ·任意操作数类型是浮点数的情况与之前一样

// ·两个操作数类型都不是浮点类型的情况。首先对两个操作数进行整数提升。如果这时两个操作数类型相同，过程结束，否则，依次尝试下面的规则，一旦遇到可应用的规则就不考虑别的了
// 如果两个操作数都是有符号型或者都是无符号型，将整数转换等级较低的操作数转换为等级高的操作数的类型。
// 如果无符号操作数的等级高于或等于有符号操作数的等级，将有符号操作数转为无符号操作数的类型。
// 如果有符号的操作数可以表示无符号操作数类型的所有值，将无符号操作数转换为有符号操作数类型。
// 否则，将两个操作数都转换为与有符号操作数的类型相对应的无符号类型。

// 另外，所有算术类型都可以转换为_Bool类型。如果原始值为0则转换结果为0，否则结果为1



/*
铁律一：浮点数永远是霸霸
只要算式里有一个 float 或 double，管你另一边是 long long 还是 int，统统给我变成浮点数。（因为 CPU 的 ALU 和 FPU 是不同的加工厂，见浮点必进 FPU）。

铁律二：整数先“内部升职”
只要你是 char、short、_Bool，或者枚举，只要你敢参与运算，编译器直接把你提拔成 int。因为 32 位寄存器处理 int 最快。

铁律三：有符号撞无符号，有符号直接祭天（致命雷区）
这是教材里写得很绕，但极其致命的地方。“如果无符号操作数的等级高于或等于有符号操作数的等级，将有符号操作数转为无符号操作数的类型。”

· 人话翻译：int 和 unsigned int 遇到一起，int 必须变成 unsigned int。
· 物理真相：负数在底层是一堆 1（补码）。变成无符号后，这堆 1 就会被当成一个巨大的天文数字。
· 安防暴击：如果你以为它只是“向大范围转”，那你就死了。因为它为了“范围大”，把负号直接扬了。黑客输入 -1，转完变成 42 亿，你的系统直接裂开。

铁律四：如果是两个大老爷们，怎么转？
“如果有符号的操作数可以表示无符号操作数类型的所有值，将无符号转为有符号……”
· 人话翻译：如果一个有符号数（比如 long long 64位）碰到了无符号数（比如 unsigned int 32位）。因为 long long 足够大，装得下所有 unsigned int 的正数，所以把 unsigned int 变成 long long，这样大家都有符号，相安无事。

五、 关于 _Bool 的物理真相
书里最后一句：“所有算术类型都可以转换为 _Bool 类型。如果原始值为 0 则转换结果为 0，否则结果为 1”。
· 人话翻译：这就是底层汇编里的 TEST 或 CMP。管你是 3.14 还是 -100，只要你不全为 0，进 _Bool 的坑里，就会被强制轮回归一化为 1（真）。
*/


// 反正记住，操作数在运算时，编译器想办法把它们的类型转换为一样的，之后返回的值也是这个类型(超过限制就回流或者有符号溢出未定义)



/*7.4.4 强制类型转换*/
// C语言提供强制转换:
// [强制转换表达式] (类型名) 表达式      <-- 这里的类型名表示的是表达式应该转换成的类型。
// 下面的例子显示了使用强制类型转换表达式计算float类型值小数部分的方法:
//    float f, frac_part;
//    frac_part = f - (int) f;     <-- 这时(int) f 将f的值转换成int类型后的结果，但是在进行减法前，还是要求转换为float[这叫常规算数转换]
// 不过C语言常规算术转换则要求在进行减法运算前(因为两边类型要一致)把 (int) f 转回float类型。f和 (int) f的不同之处就在于f的小数部分在强制类型转换时丢掉了

// 如果表达式里出现了强制类型转换，底层的物理执行顺序是：先强制转换（变出一个临时的图纸），然后再根据运算规则（常规算术转换/整数提升）统一类型，最后才进行加减乘除。

// 强制类型转换表达式可以用于显示那些肯定会发生的类型转换(相当于做一个注释，不过底层动作还是不变[强制转换->常规算术转换->整数提升]):
//    i = (int) f;   <-- f转换为int

// 它也可以用来控制编译器并且强制它进行我们需要的转换:
//    float quotient;
//    int dividend, divisor;
//    quotient = dividend / divisor;    <-- 这样除法结果是一个整数
//    quotient = (float) dividend / divisor;     <-- 这样除法结果就是浮点类型

// 顺便提一下，C语言把(类型名)视为一元运算符。一元运算符的优先级高于二元运算符，因此编译器会把表达式 (float) dividend / divisor 解释为 ((float) dividend / divisor)

// 有些时候，需要使用强制类型转换来避免溢出:
//    long i;
//    int j = 1000;
//    i = j * j;   <-- 两个int型相乘返回也是int型，如果值太大则会溢出，我们使用强制转换类型避免这种情况的发生:
//    i = (long) j * j;    <-- 因强制运算符优先级高于*，所以第一个变量j会转换成long int类型(准确来说是把j的值拿出来转换为一个临时值)，同时也迫使第二个j进行转换(常规算术转换)

//    i = (long) (j * j);  <--这样是不对的，在转换时就已经发生溢出了



/*7.5 类型定义*/
// 5.2节用#define创建了一个宏，可以用来定义布尔型数据:   #define BOOL int
// 更好的是利用类型定义特性:   typedef int Bool;
// 注意，Bool是新类型的名字。还要注意，我们使用首字母大写的单词Bool。将类型名的首字母大写不是必须的，只是一些习惯。

// 采用typedef定义Bool会导致编译器在他所识别的类型名列表中加入Bool。现在Bool类型可以和内置的类型名一样用于变量声明、强制类型转换表达式和其他地方。例如用Bool声明变量:
//    Bool flag;    <-- 与int flag相同
// 编译器把Bool类型看成是int类型的同义词;因此，变量flag实际就是一个普通的int类型变量。
// 这些在C99已经被淘汰(了解一下就行)



/*7.5.1 类型定义的优点*/
// 是程序更容易理解。假设变量cash_in和变量cash_out将用于存储美元数量。把Dollars声明成
//    typedef float Dollars;
// 并随后写出:
//    Dollars cash_in, cash_out;
// 这样的写法比下面的更有实际意义:
//    float cash_in, cash_out;
// 类型定义还可以使程序更容易修改。如果稍后决定Dollars实际应该定义为double类型，那么只需要改变类型定义就足够了:
//    typedef double Dollars;

// · 前面的是实体（类型）：int。
// · 后面的是马甲（新名字）：Bool。
// 物理真相：编译器在编译的时候，只要在代码里看到 Bool，就会在脑子里把它替换成 int。它没有创造任何新的物理类型，它只是给 int 穿上了一件叫 Bool 的马甲。



/*7.5.2 类型定义和可移植性*/
// 如果i使int型变量，那么赋值语句i = 100000;在使用32位整数机器是没问题的，但是在使用16位整数的机器就会出错。
// 可以执行技巧   为了更大的可移植性，可以考虑使用typedef定义新的整数类型名。
//    typedef int Quantity;
//    Quantity q;
// 将程序切换至使用叫短整数的机器上时，需要改变Quantity的定义:
//    typedef long Quantity;
// 可惜是这样无法解决所有问题，一些格式转换符都需要替换

// C语言库自身使用typedef为那些可能因C语言实现的不同而不同的类型创建类型名。这些类型名字经常以_t结尾:
//    typedef long int ptrdiff_t;       <-- 也可以直接写typedef long ptrdiff_t (省略int)
//    typedef unsigned long int size_t;

// 在C99中，<stdint.h>头使用typedef定义占用特定位数的整数类型名。例如 int32_t是恰好占用32位的有符号整数。这是一种有效的定义方式，更易于移植。



/*7.6 sizeof运算符*/
// sizeof运算符允许程序获取存储指定类型的值所需要的内存空间。
// [sizeof表达式] sizeof (类型名)
// 表达式的值是一个为无符号整数，代表存储属于类型名的值所需要的字节数。表达式sizeof(char)的值始终为1，但是对于其他类型计算出的值可能有所不同。
// 在32位机器上，表达式sizeof(int)的值通常为4，。注意，sizeof运算符是一种特殊的运算符，因为编译器本身通常就能够确定sizeof表达式的值。

// 通常情况下，sizeof可以用于常量、变量、表达式。如果i和j是整型变量，那么在32位机器sizeof(i)和表达式sizeof(i+j)都是4。
// sizeof不要求使用圆括号，可以用sizeof i 代替sizeof(i)。但是由于优先级问题(一元运算符)，sizeof i + j 会被解释为 (sizeof i) + j，所以圆括号很有必要

// 显示sizeof值时需要注意，因为sizeof表达式的类型时size_t，一种由实现定义的类型(C语言标准规定有这个类型，但是属性和尺寸由编译器自己规定)。
// 在C89中，最好在显示前把表达式的值转换为一种已知的类型。size_t一定是无符号整型(64位系统是unsigned long,32位系统是unsigned int)，所以最安全的方法是把sizeof表达式强制转换成unsigned long 类型(C89中最大的无符号类型)
// 使用转换说明%lu显示:
//    printf("Size of int: %lu\n", (unsigned long) sizeof(int));
// 在C99中，size_t类型可以比unsigned long更长。但C99中的printf可以直接显示出size_t类型而不需要强制转换。
// 方法是在转换说明中的一般整数(通用为u)代码前使用字母z:
//    printf("Size of int: %zu\n", sizeof(int));     <-- 仅限C99往后的版本使用


/* ============================================================================
 * 【极客终极复盘：补码物理本质、溢出回绕与转换法则】
 * ============================================================================
 * 
 * 1. 逻辑本质（人类直觉 vs 机器物理）：
 *    - 原码（人类直觉）：最高位当符号位，剩下当绝对值。但在硬件里做加减法极其恶心
 *      （有 +0 和 -0，还要判断符号位），早被物理淘汰。
 *    - 补码（机器物理）：为了迎合“无脑加法器”而设计的作弊码。完全违背人类视觉
 *      直觉（1111 1111 竟然是 -1），但保证了硬件的连续性与闭环。
 *    - 本质是【同余定理】的钟表模型：机器根本不管符号位，它算的是“谁与这个数相加
 *      会溢出变成 0”，那个数就是它的负数。
 * 
 * 2. 底层物理真相（物理回绕）：
 *    - CPU 只有一个无脑加法器。遇到进位（超出寄存器宽度），直接物理丢弃。
 *    - 8 位系统：127 (0111 1111) + 1 = 1000 0000 (-128)。
 *    - 只要发生进位溢出，最高位翻转，正数瞬间变负数，这就是物理回绕的本质。
 * 
 * 3. 认知碰撞（1000 0001 到底是谁）：
 *    - 同一串 1000 0001，按原码读是 -1；按补码读是 -127。
 *    - 如果强行把 CPU 算出的补码当原码看，-128 + 1 = -1，中间 126 个数全被吞了，
 *      数学逻辑直接崩溃。所以内存里、寄存器里，躺着的全是补码。
 * 
 * 4. 核心转换法则（双向对称）：
 *    - 万能钥匙：原码与补码互转，操作完全对称 —— 【整体减 1，符号位外全部取反】。
 *    - 减 1 是算术运算（作用于整体，借位吃掉前面的 0 或 1）。
 *    - 取反是逻辑运算（只针对数据位，绝不动最高位符号）。
 *    - 速算法：从右往左找第一个 1，这个 1 和它右边的 0 保持不变，左边除符号位外全部取反。
 * 
 * 5. 致命特例（无原码的孤儿）：
 *    - -128（1000 0000）没有原码。因为它减 1 时，后面的全 0 借位，直接把符号位
 *      的 1 吃掉了（变成 0111 1111），原码空间根本表示不了它。
 * 
 * 6. [极客箴言]：
 *    - 抛弃原码！内存里躺着的、CPU算出来的，全是补码。
 *    - 遇到负数底层计算，闭着眼睛按补码和溢出回绕算就对了。
 * ============================================================================
 */



/*2026.11.7*/
/*第八章 数组*/
/*8.1 一堆数组*/
// 数组是含有多个数据值的数据结构，并且每个数据值具有相同的数据类型。这些数据类型称为元素(element)，可以根据元素在数组的位置把它们一个个选出来
// 为了声明数组，需要指明数组元素的类型和数量。例如，为了声明数组a又10个int类型的元素，可以写成:
//    int a[10];
// 数组可以是任何类型，数组的长度可以用任何(整数)常量表达式(5.3节)指定。因为程序以后改变时可能需要调整数组的长度，所以可用宏定义
//    #define N 10
//    ...
//    int a[N];



/*8.1.1 数组下标*/
// 为了取特定的数组元素，可以在写数组名的同时在后边加上一个用方括号围绕的整数值[这被称为对数组取下标或进行索引]
// 数组元素始终从0开始，因此长度为n的数组元素的索引时0~n-1。例如，a是含有10个元素的数组，那么这些元素可以按如下所示:
// a[0] a[1] a[2] a[3] a[4] a[5] a[6] a[7] a[8] a[9]
// 形如a[i]的表达式是左值(4.2节)，因此数组元素可以像普通变量一样使用:
//    a[0] = 1;
//    printf("%d\n", a[5]);
//    ++a[i];
// 一般来说，如果数组包含T类型的元素，那么数组中的每个元素均被视为T类型的变量。本例中，a[0]、a[5]和a[i]可以看作int类型

// 数组和for循环结合在一起使用。许多程序所包含的for循环是为了对数组中的每个元素执行一些操作。下面给出一些长度为N的数组a的事例:
// [惯用法] for (i = 0; i < N; i++)    <-- N个元素的数组，我们只要取到N-1就行
//            a[i] = 0;     <-- 清空数组a
// [惯用法] for (i = 0; i < N; i++)
//            scanf("%d", &a[i]);  <-- 读取a数组中的元素
// [惯用法] for (i = 0; i < N; i++)
//            sum += a[i];    <-- 求取数组中所有元素的和
// 注意，在调用scanf函数读取数组元素时，就像对待普通变量一样，必须使用取地址符号&。

// 注意: C语言不要求检查下标的范围，当下标超出范围时，程序可能执行不可预知的行为:
//    int a[10], i;
//    for (i = 1; i <= 10; i++)   <-- 这里不再是读到N-1了
//      a[i] = 0;
// 对于某些编译器来说，这个表面上正确的for语句却产生了一个无限循环！当变量i的值变为10时，程序将数值0存储在a[10]中。
// 但是a[10]并不存在，因此在元素a[9]后数值0立刻进入内存。如果内存中变量i放置在a[9]的后边(只是有可能的)，那么变量i被重置为0，导致循环重新开始

// 数组是按从栈地位到高位排布，也就是后面的元素在高位置

// 数组下标可以是任何整数表达式:
//    a[i+j*10] = 0;
// 表达式甚至可能有副作用:
//    i = 0;
//    while (i < N)
//      a[i++] = 0;  <-- 别用i++，这样拿到的是第二个元素，而非第一个

// 当数组下标有副作用时，一定要注意，下面这个循环吧数组b中的元素复制到数组a中，但它可能无法正常工作:
//    i = 0;
//    while (i < N)
//      a[i] = b[i++];   <-- 未定义行为
// 通过下面避免:
//    for (i = 0; i < N; i++)
//        a[i] = b[i];



