// 如果比初始化器比数组短，那么数组中剩余的元素赋值为0:
//    int a[10] = {1, 2, 3, 4, 5, 6};   <-- 剩下的四个元素全是0
// 利用这一特性，可以很容易地把数组初始化为全0:
//    int a[10] = {0};
// 初始化为空非法，初始化器比数组长非法

// 如果给定了初始化器，可以省略数组的长度:
