/*8.1.3 指示器*/
// 想让元素2为29，元素9为7，元素14为48，而其它为0(注意不是第几个元素)。C99中指示器可以用于解决这一问题:
//    int a[15] = {[2] = 29, [9] = 7, [14] = 48};
// 既简短，还可以打乱次序写: 等价于   int a[15] =  {[14] = 48, [9] = 7, [2] = 29};

// 组成指示器的方括号里必须是整型常量表达式。如果待初始化的数组长度为n，则每个表达式的值必须在0和n-1之间(如果不在范围内是UB)。
// 但是，如果数组的长度是省略的，指示器可以指定任意非负整数;对于后一种情况，编译器将根据最大的值推断出数组的长度:
//    int b[] = {[5] = 10, [23] = 13, [11] = 36, [15] = 29};  <--指示符最大值为23，有24个元素

// 初始化器中可以同时使用老方法(逐个元素初始化)和新方法(指示器):
//    int c[10] = {5, 1, 9, [4] = 3, 7, 2, [8] = 6};


/* ============================================================================
 * 【极简复盘：数组初始化、平坦化与指示器覆盖机制】
 * ============================================================================
 * 
 * 1. 底层物理：平坦化与花括号（Brace Elision）
 *    - 内存是线性的一维字节流。多维数组在物理上就是连续的。
 *    - int m[2][3] = {1, 2, 3, 4, 5, 6}; 合法。内层花括号只是人类阅读的视觉分组，
 *      编译器会直接将其展平。省略内层 {} 没问题，但最外层 {} 绝对不能省。
 *    - 数组名是常量指针，不可整体赋值。只有在声明时 {} 才是初始化，a = {1,2}; 违法。
 * 
 * 2. 核心机制：指示器（Designated Initializers）的游标与覆盖
 *    - C99 引入 [index] = value。编译器维护一个隐形游标（当前下标），从左到右扫描。
 *    - 空降：遇到 [x] = y，游标强行跳至 x 赋值，随后游标顺延到 x+1。
 *    - 覆盖：同一个槽位若被多次赋值，后发制人（后面的指令覆盖前面的）。
 *      例：int a[5] = {1, 2, [1] = 99, 9};
 *      过程：a[0]=1，a[1]=2；[1]=99 游标跳到 1 并覆盖，顺延到 2；9 顺延填入 a[2]。
 *      结果：{1, 99, 9, 0, 0}。a[1] 的 2 被覆盖，a[2] 的 3 根本不存在。
 *    - 铁律：绝对不要将普通元素与指示器混写。游标漂移极易引发逻辑灾难。全用指示器或全按顺序。
 * 
 * 3. 易错遗漏点（防坑铁律）
 *    - 自动补 0：int a[10] = {1}; 剩下 9 个元素全部物理清零。
 *    - 越界拦截：[x] 中的 x 若超出数组最大下标，属于约束违规。GCC/Clang 直接报 Error。
 *    - 字符串陷阱：char str[5] = "hello"; 直接报错。数组长度必须 >= 字符串长度 + 1（留给 \0）。
 *    - 表达式禁区：普通代码中（非声明期）不能用 {}。如 a[0] = {1}; 纯属作死。
 * 
 * 4. [验证命令]
 *    - 验证平坦化：int m[2][3] = {1,2,3,4,5,6}; 用 (int*)m 遍历打印。
 *    - 验证覆盖：编译时加 gcc -Wall，看编译器抛出的 warning: initialized field overwritten。
 * ============================================================================
 */



