/*程序 判定素数(prime.c)*/



/* 9.2 函数声明 */
/************************ 【历史遗迹：C89 隐式声明】 *******************************/
// [注意：仅 C89 可用，C99 及 C23 已彻底废除，现代编译器直接报错]

// 在古老的 C89 时代，如果函数定义在调用点之后，且没有前置声明：
// 1. 编译器不报错，而是创建“隐式声明”。
// 2. 编译器不知道参数类型，只能进行“实参提升”（char->int, float->double），瞎猜。
// 3. 编译器默认该函数返回 int 型。
// 4. 【底层灾难：ABI 协议的彻底错位】：
//    调用方以为返回 int，去通用寄存器（如 EAX/RAX）里拿；
//    而被调函数实际返回 double，根据底层架构不同，它可能把值放在浮点寄存器（如 XMM0）或 x87 栈顶（ST0）里，甚至大结构体会通过隐藏指针写回内存。
//    两边协议完全对不上，拿到的全是垃圾残留值。这就是严重的“未定义行为 (UB)”，程序会在毫无防备的地方精神错乱、莫名崩溃。

/************************ 【现代规范：C99/C23 函数原型】 *******************************/
// 现代 C 语言铁律：先声明，后调用。编译器必须看到“函数原型”。
// 原型的作用：告诉编译器参数个数、类型、返回类型。让调用方和被调方严格遵守同一个 ABI 协议。

// [函数声明格式]
//    返回类型  函数名 (形参类型 [形参名]); 
//    例如：double average(double, double); 

// 【极客解读】：
// - 类型是给编译器查错和生成正确 ABI 指令用的，必须有；
// - 名字是给人看的（提示参数含义），可省略。但为了代码可读性，通常不省。

/************************ 【标准演变】 *******************************/
// C99 及之后的规则：在调用一个函数之前，必须先对其进行声明或定义。
// 如果编译器没见到声明或定义就遇到调用，直接抛出编译错误（Error），连生成汇编的机会都不给。



/*9.3 实际参数*/
