// 编译器在调用前遇到原型，就像使用赋值一样，以形参类型为主转换。
// 调用前没遇到原型直接报错



/*9.3.2 数组型实际参数*/
// 数组经常被用作实际参数。当形式参数是一堆数组时，可以(而且通常情况下)不说明数组的长度
//    int f(int a[])
//    {
//    }

// 实际参数可以是元素类型正确的任何一堆数组。只有一个问题:f函数如何知道数组是多长你?可惜的是，C语言没有为函数提供任何简便的方法来确定传递给它数组
// 的长度;如果函数需要，我们必须把长度作为额外的参数提供出来

/* ============================================================================
 * 【极客终极复盘：C 语言数组传参的“盲盒”灾难与越界物理防线】
 * ============================================================================
 * 
 * 1. 核心微观物理：数组传参的本质
 *    - 【物理真相】：C 语言传数组绝不拷贝整体。编译器执行“退化（Decay）”，只把一个
 *      8 字节的首地址（指针）塞进寄存器（如 RCX）。
 *    - 【打包盒与打手】：被调函数只是个打包盒（死板机器码），CPU 是无情打手。它们只认
 *      绝对地址和偏移量，物理上根本不存在“边界”概念，给什么指令就执行什么指令。
 * 
 * 2. 逻辑本质：到底是谁不知道？
 *    - 【编译器装傻】：它明明知道数组大小，但一传参就执行类型退化，拒绝插桩检查。
 *    - 【程序员彻底抓瞎】：C 语言不提供“胖指针”，写函数的程序员不知道未来谁会传多大的
 *      数组。若不手动传 size 参数，完全是在悬崖边盲开。
 * 
 * 3. 物理灾难：越界的终极粉碎（Buffer Overflow）
 *    - 若程序员盲猜长度导致越界写：
 *      - 覆盖父函数的局部变量。
 *      - 踩烂 `[rbp]`（旧基址）甚至 `[rbp + 8]`（返回地址）。
 *    - 后果：执行 `ret` 时，CPU 顺着被篡改的地址跳跃，程序当场飞升（或被黑客利用）。
 * 
 * 4. 认知碰撞：现代语言的护甲
 *    - C 语言（裸奔）：只传首地址，安全全凭程序员脑子里的那根弦。
 *    - 现代语言（胖指针 Slice）：底层传结构体【首地址 + 长度 + 容量】。Rust/Go 直接在
 *      语言层面把长度焊死，从根源上救了程序员。
 * 
 * 5. 💻 汇编映射：
 *    - 调用者：`lea rcx, [rbp-0x20]` (传首地址) -> `mov rdx, 10` (手动传长度)
 *    - 被调函数：`mov [rbp-8], rcx` (拿到地址)
 *      ; 若没 rdx，这段机器码根本不知边界在哪，直到物理越界崩溃。
 * 
 * 6. [极客箴言]：
 *    - 数组的本质 = 基址 + 偏移量上限。
 *    - CPU 不会问“越界了吗”，操作系统只会在你踩穿页表时给你一刀（段错误）。
 *    - 地址是上一任给的，但命是你自己的。没有自动拦截，只有栈帧被顶穿的满地残骸。
 * ============================================================================
 */

