/* ============================================================================
 * 【极客终极复盘：函数传数组的“生死契约”与一锤定音的大小】
 * ============================================================================
 * 
 * 1. 核心微观物理：一锤定音的物理地盘
 *    - 【实参定生死】：当父函数调用 `func(arr, 5)` 的瞬间，数组的地盘（在栈或在堆）和
 *      大小（5 个元素）就已经被物理划死了。
 *    - 函数拿到的只有两个值：8 字节的首地址（门牌号） + 4 字节的长度（边界线）。
 * 
 * 2. 逻辑本质：传参即签订“生死契约”
 *    - 调用者传递 `size`，本质上是在告诉函数：“这块地只有这么大，你干活绝不能超出这
 *      个范围”。
 *    - 在函数内部，`size` 变成了一个普通的局部变量。如果函数内部瞎改这个 `size`（比如
 *      强行改成 100），或者无视传入的 `size` 强行去读 `arr[6]`，就是单方面撕毁契约。
 * 
 * 3. 底层物理真相：为什么“以后调用只能在这个范围里”？
 *    - 因为内存是别人的！如果你越界写数据，就会直接踩烂父函数的局部变量，或者踩烂
 *      返回地址（导致程序瞬间暴毙）。
 *    - 硬件和操作系统只保护“进程/页表”级别的边界，绝对不会保护“数组”级别的边界。
 * 
 * 4. 认知碰撞：编译器为什么不拦着？
 *    - 编译器会把 `arr[i]` 翻译成 `*(arr + i)`（基址 + 偏移量）。
 *    - 它根本不认识“边界”两个字。你写越界代码，它照常编译，连警告都不给，默默等
 *      待程序在运行期崩溃（段错误）。
 * 
 * 5. [极客箴言]：
 *    - 数组的生命周期里，大小一旦确定，物理上就绝对锁死。
 *    - 传参那一刻的 `size`，就是函数在这片内存上活动的“唯一红线”。
 *    - 编译器不给你兜底，操作系统只会在你踩穿系统底线时直接拔枪。守住传入的 `size`，
 *      就是守住程序员的命。
 * ============================================================================
 */


// 函数调用数组能改变原数组，因为它本来就是在那里直接调用，自己连创建都没有创建，直接拿地址去取，取改
// 如果形式参数是多维数组，声明参数时只能省略第一维的长度。例如，如果修改sum_array函数使得a是一个二维数组，我们可以不指出行的数量，但是必须指定列的数量:
//    #define LEN 10
