//      for (i = 0; i < n; i++)
//        for (j = 0; i < LEN; j++)
//           sum += a[i][j];
//      return 0;
//    }
// 不能传递具有任意列数的多维数组是很讨厌的。幸运的是，我们经常可以通过使用指针数组(13.7节)解决这种苦难。C99中的变长数组形式参数则提供了一种很好的解决方案。
// 编译器偷懒要先算步长，后面也只能按照它的步长去做，去算，不然报错
// 你看代码里的 arr[i][j]，不再是第几行第几列，而是：“首地址 + (i * 写死的常量 + j) * 元素大小 = 最终的物理绝对地址。”


/* ============================================================================
 * 【极客终极复盘：多维数组的步长骗局与一维降维打击】
 * ============================================================================
 * 
 * 1. 物理基石：多维只是语法幻觉
 *    - 内存条里没有二维表格，只有一条无限延伸的一维直线。
 *    - `arr[3][4]` 在物理上，仅仅是首地址后面紧挨着的 12 个元素。
 * 
 * 2. 底层真相：根本没有“列数”，只有“字节步长 (Byte Stride)”
 *    - 理论公式 `(i * 列数 + j) * sizeof(T)` 只是人类数学抽象。
 *    - 在真实的汇编与 CPU 运算中，编译器早已将其拆解为：
 *      【目标地址 = 首地址 + i * 行步长 + j * 列步长】
 *    - 例如 int[3][4]，行步长 = 16 字节，列步长 = 4 字节。
 *      底层指令直接用 i 乘以 16，j 乘以 4，根本没有什么“列”的概念。
 * 
 * 3. 分工本质：步长写死 vs 偏移现算
 *    - 为什么形参必须写列数 `[3]`？因为编译器必须在编译期算出行步长（12 字节），
 *      将其作为硬编码常量写进指令。如果没这个参数，编译器连指令的乘法系数都填不上。
 *    - 行号和列号（i 和 j）在运行期传入，CPU 配合写死的步长，直接现场算出偏移量。
 *    - 反正都在一条直线上，选到哪个坐标，就抓哪个数据。
 * 
 * 4. 物理灾难：步长错位的“规律性连环车祸”
 *    - 若形参写死 `[3]`，实参真实是 `[4]` 列。
 *    - 编译器按 3 元素步长跳行，想去 `[1][0]`，实际踩到了 `[0][3]`。
 *    - 编译器不看边界，导致数据规律性错位，最终越界崩溃。
 * 
 * 5. 极客破局：抛弃语法糖，自己定步长
 *    - 拍平为一维指针 `int *arr`，动态传入 `cols`，写 `arr[i * cols + j]`。
 *    - 步长随心算，首地址在手，天下内存皆可去得。
 * 
 * 6. [极客箴言]：
 *    - 多维数组的语法是给人类看的，一维直线的地址和字节步长才是给 CPU 看的。
 *    - 编译器为了省乘法，强迫程序员交出列数；真正的极客，直接用一维指针拍平一切：
 *      管你几行几列，只要偏移的“字节步长”算对了，选到哪个地址，就抓哪个数据！
 * ============================================================================
 */ 



/*9.3.3 变长数组形式参数*/
// C99增加了几个与数组型参数相关的特性。第一个是变长数组，这一特性允许我们非常量表达式指定数组的长度。变长数组也可以作为参数。
// 给出定义:
//    int sum_array(int n, int a[n])   <-- 使用变长数组形式参数时参数的顺序很重要，要先有n才行 
//    {
//    ...
//    }

// 对于新版本的sum_array函数，其函数原理有好几种写法。一种写法是使其看起来更函数定义一样:
//    int sum_array(int n, int a[n]);
// 另一种写法是用*(星号)取代数组长度:
//    int sum_array(int n, int a[*]);
// 使用*的理由如下。函数声明时啊，形式参数的名字是可选的。如果第一个参数定义被省略了，那么就没有办法说明数组a的长度是n，而星号的使用则为我们提供了一个线索
// 数组的长度与形式参数列表中前面的的参数相关:
//    int sum_array(int, int [*]);   <-- 提供了一个线索，给人看的
// 另外，方括号为空也是合法的，但仅限于行:
//    int sum_array(int n, int a[]);
//    int sum_array(int, int []);
// 但是让括号为空不是一个很好的选择，因为这样没有说明n和a之间的关系。

// 一般来说变长数组形式参数的长度可以是任意表达式。例如，写一个函数来来连续两个数组a和b，要求先复制a元素再b，把结果写入第三个数组c:
//    int concatenate(int m, int n, int a[m], int b[n], int c[m+n])   <-- 给自己看到，编译器只管你传递的数组
//    {
//    ...
//    }
// 这点说明变长数组非常自由，你的表达式可以使用函数外部的变量，甚至可以调用其他的函数

/* ============================================================================
 * 【极客终极复盘：VLA 形参的双标真相与寻址性能博弈】
 * ============================================================================
 * 
 * 1. 核心双标：形参里的表达式到底执不执行？
 *    - 【一维形参（纯装饰）】：如 `int a[m+n]`。退化为 8 字节指针，内部表达式在运行期
 *      【绝对不会被执行】，纯粹是给程序员和静态分析工具看的一张“契约便签”。
 *    - 【二维形参步长（被迫营业）】：如 `int a[][n*2]`。因为编译器需要生成跨行乘法的
 *      指令，必须在运行期拿到真实步长。
 * 
 * 2. 核心纠偏：表达式只算一次，不代表步长只算一次！
 *    - 【入口求值（只算1次）】：函数进门（Prologue）时，编译器生成指令执行一次 `n*2` 
 *      或调用 `get_cols()`，并将结果存起来。C 标准规定绝不在循环里重复调用该表达式。
 *    - 【动态寻址（每次必算）】：进入 `for` 循环访问 `a[i][j]` 时，只要 `i` 变了，
 *      就必须用存好的步长去执行一次 `imul`（乘法）算偏移量。这个乘法指令【一次都逃不掉】。
 * 
 * 3. 底层物理真相：步长存哪了？（寄存器 Spill）
 *    - 入口求值的结果如果寄存器够用，会一直霸占在寄存器里（极速）。
 *    - 如果函数太复杂导致寄存器不够用，步长会被 Spill（溢出）到栈内存。每次寻址时，
 *      CPU 都要先 `mov` 读一次栈，再 `imul` 做乘法。
 * 
 * 4. 工业界生存法则：为什么禁止 VLA？
 *    - 致命的不是那几次乘法（现代 CPU 乘法极快），而是【爆栈风险】与【极差兼容性】。
 *      运行期传一个巨大尺寸直接爆掉 1MB 栈空间，且微软 MSVC 根本不支持。
 * 
 * 5. 💻 极客正解：降维打击
 *    - 抛弃形参里花里胡哨的表达式和 VLA。
 *    - 拍平成一维指针 `int *a`，外部算好 `cols` 传入，在循环里自己写 `a[i * cols + j]`。
 *      把乘法的控制权和内存的绝对边界，死死攥在自己手里。
 * 
 * 6. [极客箴言]：
 *    - 语法上的自由（允许在形参写表达式），绝不代表物理执行的合理。
 *    - 多维数组全是语法幻觉，底层只有基址、偏移量、和无情的一维直线。
 *    - 真正的底层掌控者，永远只给编译器留下最纯粹的变量和最极致的控制力。
 * ============================================================================
 */

// 如果变长数组是多维的，则更加实用:
//    int sum_two_dimensional_array(int n, int m, int a[n][m])
//    {
//      int i, j, sum = 0;
//      for (i = 0; i < n; i++)
//        for (j = 0; j < m; j++)
//          sum += a[i][j];
//      return sum;
//    } 
// 这个函数的原型可以是以下几种:
//    int sum_two_dimensional_array(int n, int m, int a[n][m]);
//    int sum_two_dimensional_array(int n, int m, int a[*][*]);
//    int sum_two_dimensional_array(int n, int m, int a[][m]);
//    int sum_two_dimensional_array(int n, int m, int a[][*]);
// 二维数组的列空着，或使用*占位，仅限于声明，定义时，列的参数绝不能空着。(注意)



/*9.3.4 在数组参数声明中使用static(C99)*/
// C99允许在数组参数声明中使用关键字static(C99之前static关键字就已经存在了，18.2节会讨论它的传统用法)
// 在下面这个例子，将static放在数字3之前，表明数组a的长度至少可以保证是3:
//    int sum_array(int a[static 3], int n)
//    {
//    ...
//    }
// 这样使用static不会对程序的行为有任何影响。static的存在只不过是一个“提示”，C编译器可以据此生成更快的指令来访问数组。(如果编译器知道数组总是具有某个最小值，
// 那么它可以在函数调用时预先从内存取出这些元素值，而不是遇到函数内部需要用到这些元素的语句时才取出相应的值。)


/* ============================================================================
 * 【极客终极复盘：C 语言数组传参的“底裤”与 static 生死状】
 * ============================================================================
 * 
 * 一、 永远不要相信“多维”这个词（万物皆一维）
 *    - 内存条是一根无限延伸的直线。什么二维、三维，全是人类骗自己的视觉幻觉。
 *    - 二维数组 `arr[3][4]` 在底层，就是紧挨着的 12 个数字。
 * 
 * 二、 寻址的终极公式与“控制权”（乘法 vs 加法）
 *    - 底层公式只有一个： 【绝对偏移 = i * 形参的列数(步长) + j】
 *    - 【为什么公式最后不加 1？】：因为首地址（基址）本身就已经对应了一个值！
 *      它已经踩在第 0 个元素上。后面的运算纯粹只算“你跨了多少行、多少列（多少步）”。
 *    - 不加 static 时，【乘法归形参，加法归实参（你）】。
 *    - 极客骚操作：如果实参是 4 列，形参写了 3 列。你可以在循环里偷偷用 `a[i][i + j]` 
 *      把误差补回来，底层照样能精准抓到真实偏移量！因为加法你说了算。
 * 
 * 三、 加了 static 的保证函数（编译器抽风许可证）
 *    - 含义：“我用命担保，这块地至少有这么多元素。”它只保证下限，不限制上限。
 *    - 【致命反转】：一旦加上 static，编译器可能不再按公式一步步算，而是直接按
 *      “形参的形状”强行预取、打包进 CPU 缓存。它不看实参到底多大了。
 *    - 【结论】：别瞎用！没加 static，你还能自己补 j 作弊；加了 static，编译器直接接管预取边界。
 * 
 * 四、 内存重塑（黑客级玩法）
 *    - 传 4x3 的数组，形参声明 3x4？只要总字节数一样，你顺着错误步长去遍历，
 *      依然能把 12 个元素一个不漏地全抓出来！因为底下是一维直线。
 * 
 * 五、 越界方向（往上偷，往下死）
 *    - 向上越位：会读/写到父函数的局部变量、返回地址。这就是栈溢出的原理。
 *    - 向下越位：计算出的偏移量是负数，错位且极易撞上保护页，当场 Segmentation Fault。
 * 
 * 六、 极客正解（终极奥义）
 *    - 永远不要用 `[][]` 这种语法糖去绑架自己。
 *    - 直接传一维指针：`int *a`，外部传列数 `cols`。
 *    - 在函数里自己写 `a[i * cols + j]`。把命运和乘法的控制权，死死攥在自己手里。
 * 
 * 七、 [极客箴言]
 *    - 数组传参永远只是给一个 8 字节的门牌号（首地址）。
 *    - 基址本身就已经命中了一个值（第0个），所以后面的运算只算“走了几步”。
 *    - 没有 `static`，你就是包工头；有了 `static`，编译器就是拿着图纸乱砸墙的流氓。
 * 
 * 八、 [工业级底线：别和语法糖谈恋爱]
 *    - 真正的矩阵运算库，形参永远只有 `int *matrix` 和 `int rows, int cols`。
 *    - 因为 `[][]` 语法无法做到“切片”（子矩阵），而一维指针可以 (`matrix + offset`)。
 *    - 内核对内存的绝对把控，靠的不是 `[][]`，而是踏踏实实的 `base + i * cols + j`。
 * 
 * 九、 [关于 static 的终极警告与“反向骗局”]
 *    - C99 引入 static 形参，初衷是帮编译器做极致优化（SIMD 预取/向量化）。
 *    - 【谎言一：物理不够（找死）】：承诺 `static 5`，实际只给 4 个。编译器盲目预取，
 *      踩穿保护页，当场引发“未定义行为（UB）的反噬”，死无全尸。
 *    - 【谎言二：物理够用（黑客骚操作）】：承诺 `static 3[1]`，实际给 `2x2`（4个）。
 *      物理容量够，编译器预取不会崩。但因为步长变成了 1，你遍历时会发现数据错位。
 *      此时，只要你自己心里有数，通过**自己补偏移量（修改 j）**，就能强行从底层抓取。
 *    - 【铁律】：只要你确保【实际物理内存 >= 承诺内存】，你就能把 static 当成玩弄编译器的工具！
 * ============================================================================
 */



/* ============================================================================
 * 【极客终极复盘：宏定义的文本骗局与预处理器物理学】
 * ============================================================================
 * 
 * 一、 核心微观物理：预处理器（Preprocessor）的“无脑复制”
 *    - 宏（Macro）绝对不是函数！它是预处理阶段的“纯文本替换机”。
 *    - 在编译器开始生成汇编代码之前，预处理器像文本编辑器一样，对代码进行
 *      【无脑查找与替换】。它不懂 C 语言的语法，不懂类型，也不懂运算符。
 * 
 * 二、 宏 vs 函数：物理底层的两道鸿沟
 *    - 【函数调用】：有类型检查、有求值动作（如算出 3+2=5）、有物理跳转（call）、
 *      会开辟栈帧（push rbp）、有返回指令（ret）。
 *    - 【宏调用】：无类型、无求值（直接把 "3+2" 这段字符粘过去）、无栈帧、
 *      无 call 跳转。代码直接被【内联】暴力塞进当前的位置，体积可能膨胀。
 * 
 * 三、 带参宏的致命天坑（带血的历史教训）
 *    - 【坑一：优先级灾难（不加括号）】
 *      #define SQUARE(x) x * x
 *      调用 SQUARE(3 + 2) 会直接展开成 3 + 2 * 3 + 2 = 11（而不是 25）。
 *      因为预处理器只管复制，真正算数的编译器会按乘除优先级无情切割你的逻辑。
 * 
 *    - 【坑二：副作用的成倍放大（逻辑变异 vs 真正的 UB）】
 *      · 【情况 A：确定发生的逻辑变异（有序列点）】
 *        宏：`#define MAX(a, b) ((a) > (b) ? (a) : (b))`
 *        调用：`MAX(i++, j)`
 *        展开：`((i++) > (j) ? (i++) : (j))`
 *        【物理真相】：因为三元运算符 `?:` 的条件求值后有【序列点】，若条件为真，
 *        i 会【确定地】自增两次。这虽然违背了函数调用的直觉，但它是合法的。
 *        极客玩法：如果你本意就是要借机控制自增两次，这甚至是个绝妙的魔法（但不推荐）。
 * 
 *      · 【情况 B：真正的未定义行为（UB，无序列点）】
 *        调用：`MAX(i++, i++)` 或使用 `#define SUM(a,b) ((a)+(b))` 并传入 `SUM(i++, i++)`。
 *        【物理真相】：在 `>` 或 `+` 运算符的两侧没有序列点。同一个变量在两个序列点
 *        之间被修改多次，这才是真正的 UB！编译器先算左边还是先算右边完全随机，结果不可控。
 * 
 * 四、 极客的生存法则（必须死死焊在脑子里）
 *    - 规则 1：宏名必须全大写（如 MAX_SIZE），警告所有人这是宏，不是函数！
 *    - 规则 2：形参和整个表达式必须用括号包死！
 *    - 规则 3：绝对不要向宏传递带有副作用的参数（i++、函数调用等），除非你
 *      极其清楚序列点在哪，且完全掌控了副作用的发生次数。
 * 
 * 五、 工业界替代方案：Inline 函数（C99 降维打击）
 *    - 既然宏零调用开销，但有那么多坑，现代 C 语言给出了完美解药：inline 函数。
 *    - inline int max(int a, int b) { return a > b ? a : b; }
 *    - 编译器看到 inline，会将函数体直接内联到调用处（相当于宏的零开销），
 *      同时又保留了严格的类型检查、参数求值和绝对的安全性。
 * 
 * 六、 [极客箴言]：
 *    - 宏是 C 语言诞生初期的性能妥协，是一把没有保险销的散弹枪。
 *    - 预处理器在编译器看到代码之前，已经拿着剪刀和胶水，把代码改得面目全非了。
 *    - 能用 inline 函数解决的，绝不碰带参宏；能用普通变量解决的，绝不碰宏定义。
 *    - 宏不是用来计算和传递值的，它是用来在编译前“篡改现实”的。
 *    - 别怕未定义行为，只要你把底层逻辑看透，UB 也能变成你手里的可控核聚变。
 * ============================================================================
 */

 
/* ============================================================================
 * 【极客终极复盘：进程内存版图、只读枷锁与 I/O 物理链路】
 * ============================================================================
 * 
 * 一、 进程物理内存全景图（从高地址向低地址排列）
 *    - 【内核态内存】：极高地址。用户程序无权直接访问，只有系统调用（syscall）能进。
 *    - 【栈区（Stack）】：向下生长。存放局部变量、函数形参、旧的 rbp、返回地址。
 *      特点：自动分配/释放，空间极小（默认 1MB~8MB），极易爆栈。
 *    - 【共享库映射区（mmap）】：中间区域。存放动态链接库（如 .dll, .so）。
 *    - 【堆区（Heap）】：向上生长。由 malloc/free 手动掌控。空间极大，是存放动态大数据的唯一归宿。
 *    - 【BSS 段】：存放未初始化的全局变量和 static 变量。程序启动时 OS 自动清零（0x00）。
 *    - 【Data 段】：存放已初始化的全局变量和 static 变量（如 int g = 10;）。
 *    - 【只读数据段（.rodata）】：存放字符串字面量（如 "hello"）、全局 const 变量。
 *    - 【代码段（.text）】：存放编译后的机器指令（汇编代码）。
 * 
 * 二、 🔪 死亡禁区：哪些内存绝对不能改？（强行写入 = Segmentation Fault）
 *    - 【禁区 1：代码段 .text】：
 *      物理权限：只读（R）、可执行（X）。
 *      原因：代码指令是给 CPU 取指执行的，如果能改，黑客就能直接篡改程序逻辑。
 *    - 【禁区 2：只读数据段 .rodata】：
 *      物理权限：只读（R）。
 *      陷阱案例：
 *        char *p = "hello"; // p 指向 .rodata
 *        p[0] = 'H';        // ❌ 灾难！强行写只读内存，被 MMU 拦截，当场段错误！
 *      破局：要想改，必须搬进栈里或堆里：char arr[] = "hello"; arr[0] = 'H'; (✅ 合法)
 *    - 【易碎区：栈（Stack）】：
 *      物理权限：可读可写。
 *      陷阱：没越界时随便改；一旦越界，就会踩烂返回地址导致程序崩溃，或被黑客利用。
 *    - 【自由区：堆（Heap）与全局区（Data/BSS）】：
 *      物理权限：可读可写。只要指针合法，想怎么改就怎么改。
 * 
 * 三、 缓冲区到底在哪？（三生三世）
 *    - 【用户自建缓冲区】：你写的 char buf[1024]（在栈），或 malloc 出来的（在堆）。
 *    - 【C 标准库缓冲区】：printf/scanf 内部维护的，通常在【堆】上（如 stdout 缓冲区）。
 *    - 【OS 内核缓冲区】：操作系统维护的，在【内核态】。键盘敲击的字符先存在这里。
 * 
 * 四、 🔄 输入输出的底层物理链路（以 getchar / printf 为例）
 *    - 【输入（键盘 -> 变量）】：
 *      键盘硬件中断 -> 数据进入【OS 内核缓冲区】 -> 你调用 getchar 触发系统调用 ->
 *      OS 把数据搬到【C 库缓冲区（堆）】 -> 逐个字符吐给你的【变量（栈）】。
 *      陷阱：getchar 不会自动补 '\0'，且极易把留在缓冲区的 '\n' 误读。
 * 
 *    - 【输出（变量 -> 屏幕）】：
 *      变量 -> 格式化后写入【C 库 stdout 缓冲区（堆）】 -> 遇到 \n 或缓冲区满 ->
 *      调用系统调用 write() -> 数据进入【OS 内核缓冲区】 -> 显卡驱动 -> 屏幕亮起。
 * 
 * 五、 极客终极总结：
 *    - 内存本无段，OS 和编译器为了保护系统，强行给虚拟内存页打上了“只读”、“可执行”的标签。
 *    - 所有的“段错误”，本质都是你的程序试图通过【写操作】去挑衅【只读的页表权限】。
 *    - 字符串字面量是刻在石头上的（.rodata），数组是写在沙子上的（栈/堆）。想改字，就把石头上的字抄到沙子上。
 *    - 内存寻址是一条一维直线，但权限是一道道物理枷锁。
 * ============================================================================
 */


/* ============================================================================
 * 【极客终极复盘：类型欺骗、首地址退化与汇编解引用的底层物理（完全体）】
 * ============================================================================
 * 
 * 一、 核心微观物理：汇编里的“传值”与“解引用”
 *    - 【传值（mov）】：把寄存器或内存里的纯数据直接拷贝。如 `mov eax, rbx`。
 *    - 【解引用（加中括号）】：把数据当成绝对内存地址，去该地址里顺藤摸瓜。如 `mov eax, [rbx]`。
 *    - 所谓的“段错误”，本质就是 CPU 拿到了非法的地址（如数字 10），并对其执行了中括号 `[]` 解引用。
 * 
 * 二、 编译器的“两副面孔”：强制地址化
 *    - 【普通变量（如 int）】：编译器老老实实传“值”（mov）。
 *    - 【复合类型（如数组、字符串）】：编译器强制执行“数组名退化”，只传“首地址”（lea 指令）。
 *      - 无论是 `char str[]`（栈上），还是手写的 `"hello"`（只读数据段），一律只把起始内存的门牌号塞进寄存器。
 *      - 物理原因：寄存器（8 字节）装不下连续大块内存，只能给入口坐标。
 * 
 * 三、 接收方的“死心眼”：格式符的强制解引用
 *    - `printf` 是可变参数函数，底层没有类型检查，只认格式符。
 *    - 看到 `%d`：直接把寄存器里的二进制当作整数打印，不读内存。
 *    - 看到 `%s`：底层强制生成带 `[]` 的指令，把寄存器里的值当作【绝对地址】去内存里逐个字节读取，直到遇到 `\0`。
 * 
 * 四、 物理灾难复盘：为什么 `%s` 打印 `int` 会死？
 *    - 灾难链条：`int a = 10`（编译器传数字 10） -> `%s`（死脑筋，把 10 当地址） -> 
 *      CPU 去读绝对地址 `0x0000000A` -> 触发 MMU 页表拦截（保护区域） -> 当场 Segmentation Fault。
 *    - 如果侥幸没崩：读到的全是历史残留的乱码（脏数据）。
 * 
 * 五、 🔪 极客高危盲区：`getchar` 抓取字符串不带 `\0` 的灾难
 *    - 【物理真相】：`getchar` 是个无情的单字节搬运工。它只负责从缓冲区拿一个字符给你，
 *      绝对、绝对不会主动在你的数组末尾补上 `\0`。
 *    - 【灾难链条】：如果你用 `getchar` 循环抓取了 "abc" 存入 `char buf[10]`，里面就是 'a','b','c'，
 *      后面全是未初始化的垃圾数据。此时如果你直接 `printf("%s", buf)`，`%s` 会因为没有看到 `0x00`
 *      而继续向后疯狂越界读取，直到撞上一个 0 字节。
 *    - 【后果】：轻则打出满屏乱码（内存泄露），重则越过栈帧边界踩中 MMU 保护页，当场段错误暴毙。
 *    - 【极客解法】：必须手动封口。`buf[i] = '\0';`（强行在有效字符后写入一个 0x00 刹车片）。
 * 
 * 六、 📜 终极名单：谁会帮你自动加 `\0`？
 *    - 【字符串字面量】：`"hello"`（编译器在 .rodata 或栈上自动补齐 6 个字节，末尾自带 \0）。
 *    - 【数组初始化】：`char str[] = "hello";`（编译器按 6 字节分配）。
 *    - 【scanf 读字符串】：`scanf("%s", buf);`（`scanf` 底层会在读完字符后主动补 \0，但极其危险，因为它不检查数组边界，容易导致缓冲区溢出）。
 *    - 【fgets 读字符串】：`fgets(buf, sizeof(buf), stdin);`（不仅安全限制了长度，还会自动加 \0）。
 *    - 【各种 str 库函数】：`strcpy`, `strncpy`, `sprintf`, `snprintf` 等（作为标准库函数，它们在操作字符串时都会有补 \0 的机制）。
 * 
 * 七、 [极客箴言]：
 *    - C 语言只有一种传参方式：传值。传普通变量是传数值，传数组/指针是传地址的数值。
 *    - 编译器负责“递纸条”，格式符负责“念纸条”，CPU 负责“跑腿”。
 *    - `\0`（0x00）是 C 语言字符串在物理内存中的唯一“刹车片”。没有它，`%s` 就是一辆失控的列车。
 *    - 底层无类型，万物皆字节。只有地址与偏移量，才是唯一的物理真理。
 * ============================================================================
 */



/*9.3.5 复合字面量(C99)*/
// 可以这样调用sum_array:
//    int b[] = {3, 0, 3, 4, 1};
//    total = sum_array(b, 5);
// 这里唯一问题是需要把b作为一个变量声明，并在调用前进行初始化。如果b不作它用，浪费
// C99可以使用复合字面量来避免该问题，复合字面量是通过指定其包含的元素而创建的没有名字的数组:
//    total = sum_array((int []) {3, 0, 3, 4, 1}, 5);  <-- 第一个参数就是复合字面量
// 这里没有对数组长度做特别的声明，其长度是由复合字面量的元素个数决定的。当然也可以显示地指明初始值。因此可以在初始化器中使用指示器。

// 函数内部创建的复合字面量可以包含任意表达式，不限于常量:
//    total = sum_array((int []) {2 * i, i + j, j * k}, 3);  <-- 因为这里的复合字面量不在全局变量，后面笔记会说
// 复合字面量为左值，所以其元素的值可以改变。如果要求其值为“可读”，可以再类型前加上const，如(const int []) {5, 4}


/* ============================================================================
 * 【极客终极复盘：复合字面量的物理分身与生命周期陷阱】
 * ============================================================================
 * 
 * 一、 核心微观物理：凭空捏造的“匿名变量”
 *    - 复合字面量（如 `(int[]){1, 2, 3}` 或 `(struct Point){1, 2}`）的本质，
 *      是编译器在背后偷偷帮你创建了一个【没有名字的临时变量】。
 *    - 既然是变量，它就必须遵守 C 语言的内存分区铁律：写在哪，就在哪开地址。
 * 
 * 二、 物理坐标分布：写在哪，就在哪安家
 *    - 【写在函数内部（局部）】：分配在当前函数的【栈（Stack）】上。
 *      生命周期随函数结束而灰飞烟灭。
 *    - 【写在所有函数外部（全局）】：分配在【.data 或 .bss 段】。若加了 const，
 *      则被打入【.rodata 只读段】。生命周期等于整个程序。
 *    - 【写在函数实参里】：分配在【调用者（Caller）的栈帧】上。编译器在当前栈帧挖坑、
 *      填入数据，然后把地址塞进寄存器传给被调函数。
 * 
 * 三、 🔪 绝对死亡禁区：返回局部复合字面量的地址
 *    - 灾难代码：
 *      int* create_array() {
 *          return (int[]){1, 2, 3}; // ❌ 灾难！
 *      }
 *    - 物理真相：
 *      1. `create_array` 在栈上挖了 12 字节填入 1, 2, 3。
 *      2. `return` 返回了这 12 字节的首地址。
 *      3. 函数结束，执行 `mov rsp, rbp` 销毁栈帧，这 12 字节被物理回收。
 *    - 后果：返回的指针变成【悬垂指针（野指针）】。下次读取，读到的全是别的函数
 *      踩烂的垃圾数据，或直接触发段错误（Segmentation Fault）。
 * 
 * 四、 极客工业级正解：如何安全转移数据？
 *    - 【解法 1：升维到堆区】用 malloc 动态分配，并手动填入数据。必须由调用者负责 free。
 *    - 【解法 2：让调用者提供地皮】把指针作为参数传进去，在里面填数据（最安全）。
 *    - 【解法 3：转正为静态】加 static 关键字，强行把它塞进全局静态区。
 *      `static int arr[] = {1, 2, 3}; return arr;`
 * 
 * 五、 💻 汇编映射（实参传递时的微观动作）：
 *    - C 代码：`func((int[]){10, 20}, 2);`
 *    - 底层动作：
 *      mov [rbp-16], 10  ; 在【当前】栈帧填入数据
 *      mov [rbp-12], 20
 *      lea rdi, [rbp-16] ; 取当前栈帧的地址
 *      call func         ; 把地址传给下一个函数
 * 
 * 六、 [极客箴言]：
 *    - 复合字面量是编译器提供的一把“便利贴”，即写即用，极其优雅。
 *    - 但别把便利贴钉在了即将拆除的脚手架上（栈帧）。
 *    - 永远记住：返回指针之前，先看清这个指针指向的地皮，到底是永生（Heap/Data），
 *      还是速朽（Stack）。
 * ============================================================================
 */


/* ============================================================================
 * 【极客终极复盘：编译期的“生死簿”与运行期的“狂飙”】
 * ============================================================================
 * 
 * 一、 核心宏观认知：图纸与施工的物理隔离
 *    - 【编译器（画图纸）】：在程序运行（生成 exe）之前工作。它面对的是静态的代码文本，
 *      必须在此时把所有“物理尺寸、偏移量、固定数据”全部算死，写进可执行文件。
 *    - 【运行期（CPU施工）】：当双击 exe，操作系统分配虚拟内存后，CPU 根据图纸开始
 *      疯狂执行指令。此时产生的数据变化，编译器已经"死了"，根本管不着。
 * 
 * 二、 编译器必须在【编译期】焊死的事（绝不能留给运行期）：
 *    - 【常量表达式求值（常量折叠）】：如全局数组初始化 `int g[2] = {1+2, 4*5}`。
 *      编译器在生成 exe 之前，就直接算成了 3 和 20，写死在 .data 段里。
 *    - 【栈帧的静态布局】：局部变量相对于 `rbp` 的偏移量（如 `[rbp-4]`）、参数相对于
 *      `rbp` 的偏移量（如 `[rbp+16]`），全在编译期算死。
 *    - 【形参的退化与步长写死】：如前所述，多维数组形参必须写明列数（如 `[][3]`），
 *      编译器要把乘法指令的系数（3）硬编码进机器码。
 *    - 【宏的纯文本替换】：`#define` 在预处理阶段就被物理抹除，编译器看到的已经是替换后
 *      的代码。
 *    - 【全局/静态变量的物理分区】：哪些进 .rodata（只读）、哪些进 .data、.bss，都在
 *      编译期决定。
 * 
 * 三、 编译器只能干瞪眼，留给【运行期】算的事：
 *    - 【局部变量的动态计算】：`int a = 10; int b = 20; int arr[3] = {a, a+b, get_val()};`。
 *      编译器只画图纸，具体的 a+b 的值，必须等 CPU 运行到那一行时现场去算。
 *    - 【堆（Heap）内存的分配】：`malloc(n)`。到底分配在哪、分配多大，完全取决于程序跑
 *      起来时的物理内存状态，编译期根本无从得知。
 *    - 【栈帧的绝对物理地址】：编译器只写偏移量，真实的绝对地址（如 `0x7ffd1000`）是
 *      操作系统在运行期分配好，并塞进 RBP/RSP 寄存器里的。
 *    - 【函数的真实跳转地址】：如果是动态链接库（DLL），真实地址只有运行期加载后才知道。
 * 
 * 四、 极客底线：数组初始化的“双标”
 *    - 局部数组：可以在初始化时使用变量、函数调用（因为运行期才分配栈）。
 *    - 全局/静态数组：只能用“常量表达式”（因为数据段必须提前写入 exe 中，死数据）。
 * 
 * 五、 [极客箴言]：
 *    - 编译器是个极度严谨又胆小的会计，凡是能在 Excel（exe 文件）里算清的账，它绝不
 *      拖到现场（运行期）去算。
 *    - 凡是现场才能知道的结果（变量、函数返回值、内存分配），编译器只留下公式（指令），
 *      让 CPU 去解。
 *    - 看懂了“编译期能算什么”，你就看懂了 C 语言为什么会有那么多的“常量约束”和“未定义
 *      行为”。
 * ============================================================================
 */
 
 

/*9.4 return 语句*/ 
// 非void的函数必须使用return语句来指定将要返回的值。return语句有如下形式:
//    [return 语句] return表达式;
// 该表达式经常只有常量或变量:
//    return 0;
//    return status;
// 但它也可能是更加复杂的表达式。例如，在return语句的表达式中看到条件运算符是很平常的:
//    return n >= 0 ? n : 0;
// 如果return语句中表达式的类型和函数的返回类型不匹配，那么系统会把表达式的类型隐式转换成返回类型。声明什么转换什么。
// 如果没有给出表达式，return语句可以出现在返回类型为void的函数中:
//    return;

// return 语句执行后直接返回上一个调用地方，后面的语句不执行。
// 如果非void语句没有return，是未定义



/*9.5 程序终止*/
// 最好显示main函数没有参数。[后面将看到，main函数有时是有两个参数的，通常名为argc和argv(13.7节)]
// main函数返回的值是状态码，在某些操作系统中程序终止时可以检测到状态码。如果程序正常终止，main函数应该返回0;为了表示异常终止，main函数应该返回非0的值。(也可以有别的目的)
// 即使不打算使用状态码，确保每个C程序都返回状态码是一个很好的实践，因为以后运行程序的人可能需要测试状态码。

/*exit函数*/
// 在main函数执行return语句是终止程序的一种方法，另一种方法是调用exit函数，此函数属于<stdlib.h>头(26.2节)。传递给exit函数的实际参数和main函数的返回值具有相同的含义:
// 两者都说明程序终止时的状态。为了表示正常终止，传递0:
//    exit(0);
// 因为0有点模糊，所以C语言允许用EXIT_SUCCESS来代替(效果是相同的):
//    exit(EXIT_SUCCESS);
// EXIT_SUCCESS和EXIT_FAILURE都是定义在<stdlib.h>的宏。通常分别是0和1.

// 作为终止程序的方法，return语句和exit函数关系紧密。事实上，main函数中的语句  return 表达式;  --> 等价于  exit(表达式);

// 它们的差异是不管哪个函数调用exit都会导致程序终止，而return仅限于main函数。



/*9.6 递归*/
// 如果函数调用它本身，那么此函数就是递归的。例如，利用公式n!=n*(n-1)!，下面的函数可以递归地计算出n!的结果:
//    int fact(int n)
//    {
//      if (n <= 1)
//        return 1;
//      else
//        return n * fact (n - 1);
//    }

// 有些编程语言极度依赖递归，另一些编程语言则甚至不允许使用递归。C语言介于两者之间:它允许递归，但是大多数C程序员并不经常使用递归。
// 为了了解递归的工作原理，一起来追踪下面这个语句的执行:
//    i = fact(3);
// 3大于1，执行 3*fact (3 - 1)
// 3-1大于1，执行2*fact(2 - 1)
// 2-1等于1，返回1
// 最后是3*2*1

// 我自己总结以下递归，递归，一般至少有两个分支，一个作为停止的条件，一个作为递归的条件。怎么确定递归最后的值是什么，你需要注意，每次递归会改变什么，会返回什么?
// 如果每次递归都有外部条件，那么它们是叠加的，且要看每次递归它们有没有变化。如果每次递归没有外部条件，只是一味的取调用，那么最后返回的值就是最终的值。

/* ============================================================================
 * 【极客终极复盘：递归的物理法则与栈帧博弈】
 * ============================================================================
 * 
 * 一、 递归的核心逻辑（极客四问）：
 *    - 停止条件（Base Case）：在哪里刹车？（汇编底层的 cmp + je 拦截）。
 *    - 递归条件（Recursive Case）：如何向刹车点逼近？
 *    - 改变了什么：每次传参的变量（如 n-1）必须在物理上收敛。
 *    - 返回了什么：这是决定“叠加”还是“穿透”的关键。
 * 
 * 二、 递归的两大物理形态：
 *    - 【非尾递归（叠加式）】：如 `return n * fact(n-1);`
 *      - 物理动作：在递归调用未返回结果前，当前栈帧（Stack Frame）绝对不能销毁。
 *      - 结果：空间复杂度 O(n)，极易爆栈。触底反弹时，在出栈过程中层层执行乘法（叠加）。
 *    - 【尾递归（穿透式）】：如 `return fact(n-1);`
 *      - 物理动作：当前栈帧的所有工作都已完成，无需等待下层返回。现代编译器会直接销毁
 *        当前栈帧并 `jmp`，这叫“尾调用优化（TCO）”。物理上等价于 while 循环。
 * 
 * 三、 为什么 C 程序员不常用递归？
 *    - 栈空间极小（默认 1MB），一爆就死（Stack Overflow）。
 *    - 每次 call 都有压栈开销（保存 rbp 和返回地址），比纯循环慢。
 *    - 除非面对树、图等具有“天然递归属性”的数据结构，否则能用 for 绝不用递归。
 * 
 * 四、 [极客箴言]：
 *    - 递归的本质，是把一个大任务拆成小包裹，向下踢皮球（递），直到最小的包裹解开，再
 *      一层层往回打包（归）。
 *    - 有外部运算的递归（如乘法），会在归来的路上不断叠加（消耗栈帧）；没有外部运算的
 *      递归（尾递归），会被编译器直接暴力压缩成原地循环。
 *    - 你的总结极其准确：看懂了每次递归改变和返回了什么，你就看穿了栈帧的生死。
 * ============================================================================
 */

 
// 下面是递归的另一个示例:利用公式X^n = x * x^(n-1)的函数
//    int power(int x, int n)
//    {
//      if (n == 0)
//        return 0;
//      else
//        return x * power(x, n - 1);
//    } 
